MultiLanguageItemData['de'][199815] = {name = "[q3]Formel: Umhang - Regenerativer Lebensraub", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Regenerativer Lebensraub' durchführt.\n[q2]Einen Umhang dauerhaft verzaubern, sodass der Lebensraub um 75 erhöht wird und Ihr Euch alle 5 Sek. um 9925 Gesundheit heilt, wenn Ihr Euch außerhalb des Kampfes befindet. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt Ruhmrang 10 bei den Tuskarr von Iskaara.\nVerkaufspreis:"}
MultiLanguageItemData['de'][199816] = {name = "[q3]Formel: Brust - Bewegungsbeschleunigung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Bewegungsbeschleunigung' durchführt.\n[q2]Eine Brustrüstung dauerhaft verzaubern, sodass Eure Beweglichkeit um 77 und Eure Geschwindigkeit um 200 erhöht werden. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt Ruhmrang 10 bei den Tuskarr von Iskaara.\nVerkaufspreis:"}
MultiLanguageItemData['de'][199817] = {name = "[q3]Formel: Umhang - Schnelle Heimkehr", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Schnelle Heimkehr' durchführt.\n[q2]Einen Umhang dauerhaft verzaubern, sodass die Geschwindigkeit um 75 erhöht und die Abklingzeit Eures Ruhesteins auf den Dracheninseln um 0 Min. verringert wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt Ruhmrang 11 beim Valdrakkenabkommen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][199818] = {name = "[q3]Formel: Stiefel - Lehm des Hüters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Lehm des Hüters' durchführt.\n[q2]Stiefel dauerhaft verzaubern, sodass die Ausdauer um 92 erhöht wird. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt Ruhmrang 11 beim Valdrakkenabkommen.\nVerkaufspreis:"}
