MultiLanguageItemData['de'][199893] = {name = "[q3]Kostbare Steinfragmente", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Zerschmetterte Edelsteinfragmente aus einer größeren Juwelenfassung.\""}
MultiLanguageItemData['de'][199894] = {name = "[q3]Torheit des Fischers", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Platziert den Korb für \"Torheit des Fischers\" auf dem Boden und fordert Eure Freunde heraus, zu sehen, wer den kleinen Fisch abbekommt. (1 Min Abklingzeit)\nBenötigt Ruhmrang 17 bei den Tuskarr von Iskaara."}
MultiLanguageItemData['de'][199895] = {name = "[q3]Bruchstück einer Skulptur", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Ein großes Stück einer Skulptur... Das Motiv ist unbekannt.\""}
MultiLanguageItemData['de'][199896] = {name = "[q3]Gummiartiger Fischkopf", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört einen gummiartigen Fischkopf am Zielort, der 5 Min. lang als Zielattrappe dient.\n\n Kann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)\nBenötigt Ruhmrang 17 bei den Tuskarr von Iskaara.\n[q]\"Ein großes Nebenprodukt, das ordentlich was einstecken kann, passt aber auf den Geruch auf.\""}
