MultiLanguageItemData['de'][200506] = {name = "[q3]Getriebener Setzling", additional_info = "[q2]Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n[q]\"Ein magischer Samen, der vor Leben vibriert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200507] = {name = "[q3]Verrotteter getriebener Setzling", additional_info = "[q2]Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n[q]\"Ein Samen, der von der Macht des Verfalls heimgesucht wurde. In ihm scheint jedoch immer noch ein Rest Leben zu ruhen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200508] = {name = "[q3]Selbstverbreitender getriebener Setzling", additional_info = "[q2]Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n[q]\"Die Essenz des Lebens wogt darin und versucht fortwährend, sich zu befreien.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200509] = {name = "[q3]Aufgebrachter getriebener Setzling", additional_info = "[q2]Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n[q]\"Der Samen hat eine bedrohliche Aura. Möglicherweise müsst Ihr für ihn Verbündete versammeln.\"\nVerkaufspreis:"}
