MultiLanguageItemData['de'][200548] = {name = "Schlüssel zu Maldras Fesseln", additional_info = "Questgegenstand\n[q]\"Orian Dunkelwasser hat Malda angekettet. Dieser Schlüssel könnte sie befreien.\""}
MultiLanguageItemData['de'][200549] = {name = "[q3]Restauriertes Titanenartefakt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Intelligenz\n[q2]Benutzen: Gewährt einem Verbündeten aus großer Distanz einen Schild in Höhe von bis zu 37740 und gewährt Euch bis zu 5726 Geschwindigkeit. Der Absorptions- und Geschwindigkeitswert variiert abhängig von der Distanz zwischen Euch und Eurem Ziel. Je näher Ihr einander seid, desto höher der Absorptionswert und desto niedriger der Geschwindigkeitswert. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][200550] = {name = "[q3]Sehr bequemer Pelz", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Macht es Euch bequem wie die Maruuk! (20 Min Abklingzeit)\nBenötigt Ruhmrang 3 bei den Zentauren der Maruuk und den Abschluss der Quest \"Kultureller Austausch\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][200551] = {name = "[q3]Bequemer Pelzstapel", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Ruht Euch wie die Khanam aus, egal, wo Ihr seid! (20 Min Abklingzeit)\nBenötigt Ruhmrang 3 bei den Zentauren der Maruuk und den Abschluss der Quest \"Kultureller Austausch\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][200552] = {name = "[q3]Hülle des Schwallrufers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Stärke\n[q2]Benutzen: Kanalisiert Ströme um Euch herum, die Gegnern in der Nähe im Verlauf von 3 Sek. [ 1906 * (6) * (1 + Vielseitigkeit)] Naturschaden zufügen. Löst dann eine mächtige Explosion aus, die 53355 Naturschaden verursacht, der zwischen allen Gegnern in der Nähe aufgeteilt wird. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][200553] = {name = "Panthisnektar", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt den Panthisnektar Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die schalenförmige Blume bildet eine Vertiefung, in der sich Nektar sammelt. Dank seines hohen Zuckergehalts ist der Nektar eine begehrte Kochzutat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200554] = {name = "Tropfkappenhut", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt den öligen Tropfkappenhut Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Tropfkappe sondert eine ölige Substanz ab, wenn sie reift. Als Brandbeschleuniger ist dieses Öl ein gefragtes und kostbares Gut.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200555] = {name = "Infernosamen", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Infernosamen Euren Vorräten der Dracheninseln hinzu.\n[q]\"Ähnlich wie Schießpulver explodieren die Infernokapseln, wenn sie vollständig gereift sind, und verstreuen so ihre Samen. Die Djaradin sammeln sie, während sie gerade erst blühen, und nutzen sie später, um ihre Schmieden auf Schmelztemperatur zu bringen.\"\nVerkaufspreis:"}
