MultiLanguageItemData['de'][200563] = {name = "[q3]Urzeitliche Ritualmuschel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Führt das Beschwörungsritual aus und haltet Zwiesprache mit einer der Urschildkröten, um ihren Segen zu erhalten.\n\n Die Ritualstelle befindet sich südlich des Piers von Uktulut an der Küste des Erwachens, nahe der Überreste eines Drachen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][200586] = {name = "Heruntergekommene Sonnenbrille", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Dieses modische Accessoire wurde durch die Zeit im Bad der Ruhigen Träume sehr beschädigt, aber vielleicht hat es für einen der Gäste einen sentimentalen Wert.\""}
MultiLanguageItemData['de'][200587] = {name = "[q0]Ledergebundene Expeditionsnotiz", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieses fest zusammengerollte Pergament wurde in rissiges, gefärbtes Leder eingewickelt. Auf der Bindung erkennt man die Initialen T und S.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200588] = {name = "Fleischiger Stängel", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt den fleischigen Stängel Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Stacheln sind ein Zeichen dafür, dass die Pflanze reift, und sollen das proteinreiche Fleisch am Stängel schützen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200589] = {name = "Hydrolebenssamen", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt Hydrolebenssamen Euren Vorräten der Dracheninseln hinzu.\n[q]\"Lebenssamen werden an den Lebensbecken gezüchtet, denn wenn man sie zusammen mit anderen Samen anpflanzt, verzehnfacht sich deren Wachstum.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200590] = {name = "[q0]Sorgfältig zusammengerollte Nachricht", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Rolle wurde so fest zusammengerollt, dass sie sich kaum entrollen lässt.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200592] = {name = "[q0]Dreckiger alter Ranzen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Öffnet den Beutel und offenbart den Inhalt.\n[q]\"Ein zerbröckeltes, verblichenes Siegel der Drachenschuppenexpedition befindet sich auf dem Knopf an der Lasche des Ranzens.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200593] = {name = "[q0]Versiegelte Expeditionsnotiz", additional_info = "Wird beim Aufheben gebunden\n[q]\"Unterschrieben und versiegelt durch die Drachenschuppenexpedition.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200594] = {name = "[q0]Thaelins zweitliebster Kamm", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eignet sich perfekt selbst für die struppigsten Zwergenbärte.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200595] = {name = "[q0]Duftendes Pergament", additional_info = "Wird beim Aufheben gebunden\n[q]\"Was auch immer auf dem Pergament geschrieben stand, wurde durch Wasser hinfortgewaschen und hinterließ einen einzigartigen Duft und verwaschene Schriftzeichen.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200596] = {name = "[q0]Brief von Thaelin Schwarzamboss", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieser Brief wurde auf frischem Pergament verfasst und mit dem Siegel der Drachenschuppenexpedition versehen.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][200597] = {name = "[q2]Strauß der Liebenden", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Werft den Strauß der Liebenden einem Freund oder einer Freundin zu. (5 Min Abklingzeit)\n[q]\"Wer ist als Nächstes dran?\""}
