MultiLanguageItemData['de'][200628] = {name = "[q3]Einigermaßen stabilisiertes Arkana", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört außerhalb des Kobaltkonvents eine Arkanakugel. (1 Stunde Abklingzeit)\n[q]\"Instabile Energien bemühen sich, möglichst stabil zu erscheinen, weil Ihr es von ihnen erwartet.\""}
MultiLanguageItemData['de'][200630] = {name = "[q3]Ruhestein des Windweisen der Ohn'ir", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Bringt Euch zurück zu Eurem Heimatort: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n[q]\"Kehrt mit Ohn'ahras Anmut nach Hause zurück.\""}
