MultiLanguageItemData['de'][200689] = {name = "[q3]Frostklauenband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+234 Ausdauer\n[q2]+ 329 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 391.\n[q]\"Elementarenergie schlummert darin und wartet darauf, dass ein Tarasek von ihr Gebrauch macht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200690] = {name = "Ritheremblütenblätter", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Ritheremblütenblätter Euren Vorräten der Dracheninseln hinzu.\n[q]\"Zu einem feinen Pulver gemahlen, dienen die Blätter der Ritheremblüte als natürliches Gerinnungsmittel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200691] = {name = "Klauendisteldornen", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Klauendisteldornen Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Dornenspitzen verfügen über ein natürliches Betäubungsmittel, das von den Maruuk für medizinische Behandlungen verwendet wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200692] = {name = "Geschenk des Hains", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt das Geschenk des Hains Euren Vorräten der Dracheninseln hinzu.\n[q]\"Das Extrakt dieser Pflanze kann verwendet werden, um die Effektivität von Verbänden zu erhöhen, wodurch größere Schnitte und Abschürfungen schneller heilen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200693] = {name = "Teratablätter", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Teratablätter Euren Vorräten der Dracheninseln hinzu.\n[q]\"Das Öl in den Blättern der Teratapflanze kann zum Behandeln von Verbrennungen verwendet werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200694] = {name = "Flussglöckchenknollen", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Flussglöckchenknollen Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die belebenden Wasser des Flusses von Ohn'ahra versorgen die Knollen mit natürlichen Mineralien. Sie werden auf den Ebenen gemeinhin für ihren Vitamingehalt geschätzt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200695] = {name = "Fangzähnchenblütenblätter", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Fangzähnchenblütenblätter Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Zentauren der Ebenen nutzen eine Paste, die aus den Blütenblättern des extrem giftigen Fangzähnchens hergestellt wird, um ihre Pfeilspitzen für die Jagd auf große Beute mit Gift zu versehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200696] = {name = "Winterbeeren", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Winterbeeren Euren Vorräten der Dracheninseln hinzu.\n[q]\"Diese Beeren gedeihen im kalten Klima des Azurblauen Gebirges. Sie enthalten viel Zucker und werden überall auf den Dracheninseln gehandelt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200697] = {name = "Pestling", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt den Pestling Euren Vorräten der Dracheninseln hinzu.\n[q]\"Dieser aus der Seuche erwachsene Pilz ist in größeren Mengen giftig, aber in kleinen, kontrollierten Dosen dient er als wirksames Schmerzmittel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200698] = {name = "Leykugel", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Leykugel Euren Vorräten der Dracheninseln hinzu.\n[q]\"Wenn sie kurz vor der Reife geerntet wird, kann die Kugel zu einem Pulver zerstoßen werden, das einen schillernden und ablenkenden Nebel erzeugen kann.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200699] = {name = "Seidenpflanzenfasern", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Seidenpflanzenfasern Euren Vorräten der Dracheninseln hinzu.\n[q]\"Werden zum Isolieren von Kleidung oder Wohnräumen in kalten Umgebungen genutzt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200700] = {name = "Zypressenbeeren", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Zypressenbeeren Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Öle der beerenartigen Zapfen werden häufig als harntreibendes Mittel genutzt, können aber auch zu Alkohol mit Kiefernnote destilliert werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200701] = {name = "Tizianextrakt", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt das Tizianextrakt Euren Vorräten der Dracheninseln hinzu.\n[q]\"Dieses kräftige Rotgoldpigment wird fast ausschließlich für titanische Architektur und Freilichtmalerei verwendet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200702] = {name = "Purpurtizianextrakt", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt das Purpurtizianextrakt Euren Vorräten der Dracheninseln hinzu.\n[q]\"Eine Variante der klassischen Tizianorchidee, die selektiv gezüchtet werden muss, um ihre purpurne Farbe zu erhalten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][200703] = {name = "Rankenblumenfasern", additional_info = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\n[q2]Fügt die Rankenblumenfasern Euren Vorräten der Dracheninseln hinzu.\n[q]\"Die Fasern der Rankenblume sind flexibel und robust. Flechtet man genug von ihnen zu einem Strang, erhält man ein hervorragendes Seil.\"\nVerkaufspreis:"}
