MultiLanguageItemData['de'][201411] = {name = "[q3]Uraltes Gewölbeartefakt", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieses Artefakt scheint aus der Zeit der Inkarnationen zu stammen. Lillian Mondenschein von der Drachenschuppenexpedition würde sich bestimmt für diesen Gegenstand interessieren.\""}
MultiLanguageItemData['de'][201412] = {name = "[q3]Uraltes Gewölbeartefakt", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Dieses Artefakt stammt aus der Zeit, als die Inkarnationen gefangen waren. Lillian Mondenschein von der Drachenschuppenexpedition würde sich bestimmt für diesen Gegenstand interessieren.\""}
MultiLanguageItemData['de'][201413] = {name = "Ewigkeitserfüllte Burrata", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Dieser Leckerbissen, der mit Wasser aus dem Brunnen der Ewigkeit zubereitet wurde, war einst ein Leibgericht der Kaldorei. Natürlich vor der Zerschlagung.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][201414] = {name = "[q3]Schwingenreißer der Qalashi", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zwingt einen gegnerischen Spielercharakter, der aktuell in der Luft ist, zum Absitzen. Kann nur im Kriegsmodus auf den Dracheninseln eingesetzt werden. (1 Min Abklingzeit)"}
MultiLanguageItemData['de'][201415] = {name = "Temporalparmesan", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\n[q]\"Völlig losgelöst von der Zeit hat dieser Parmesan die nette Angewohnheit, sich schon vor der Zubereitung auf der Pasta zu materialisieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][201416] = {name = "Brunost des Schwarzen Imperiums", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\n[q]\"Wenn Ihr diesen übel riechenden Käse an Euer Ohr haltet, könnt Ihr ein seltsames Flüstern hören. Der Käse ist außerdem sehr fetthaltig.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][201417] = {name = "Käsebruch aus Stratholme", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\n Ihr müsst beim Essen sitzen bleiben.\n[q]\"Die ganze Molke muss entsorgt werden! Alles andere ist Käse!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][201418] = {name = "[q3]Kugel der Obsidianschuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Nehmt das Aussehen eines zufälligen Obsidiandrakoniden an. (1 Stunde Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][201419] = {name = "Apexis-Asiago", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Der Apexiskristall, der die Rezeptur dieses Käses enthielt und von den Gelehrten der Anhari und Skalaxi perfektioniert wurde, ist längst verloren gegangen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][201420] = {name = "Gnolans Spezialität des Hauses", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n[q]\"Fleischig und überraschend gut gewürzt, mit einem Hauch von Knorpelknusper.\"\nVerkaufspreis:"}
