MultiLanguageItemData['de'][201435] = {name = "[q3]Schwingende Sande", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Diese Sande verleihen Eurem Körper den Schwung, nach dem er sich sehnt!\n\n Werdet 10 Min. lang zum tanzenden Teufel! (30 Min Abklingzeit)\nVerkaufspreis:"}
