MultiLanguageItemData['de'][202243] = {name = "Honigfrosthonig", additional_info = "Questgegenstand\n[q]\"Dank seines hohen Zuckergehalts friert er selbst im bittersten Winter nicht ein. Das macht ihn auch perfekt, um Hochprozentiges daraus zu brauen.\""}
MultiLanguageItemData['de'][202244] = {name = "Frostiger Futtervorrat", additional_info = "Questgegenstand\n[q]\"Eine Sammlung aus Beeren, Fleisch, Nüssen und Knollen, die in allen Teilen der Oberen Frostlande gesammelt wurden. Die bittere Kälte hat sie haltbar gemacht.\""}
MultiLanguageItemData['de'][202245] = {name = "Rostkieferzapfen", additional_info = "Questgegenstand\n[q]\"Die bemerkenswert robusten Zapfen kommen mit allen Elementen in Berührung. So repräsentieren sie das Gleichgewicht der Natur und dienen als Symbol für Erneuerung.\""}
