MultiLanguageItemData['de'][202610] = {name = "[q4]Drachenfeuerbombenspender", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 Beweglichkeit\n[q2]Benutzen: Befestigt eine Drachenfeuerbombe an Eurem Ziel, die nach 7 Sek. 38559 Feuerschaden verursacht. Wenn Euer Ziel stirbt, während die Bombe an ihm befestigt ist, verursacht sie stattdessen 32132 Schaden, der zwischen allen Gegnern innerhalb von 10 Metern aufgeteilt wird. Kann maximal 3 Bomben enthalten. (30 Sek. Abklingzeit)\n\n Nachdem Ihr 60 kritische Treffer erzielt habt, wird ein inspirierender Blitz ausgelöst, durch den Ihr spontan eine zusätzliche Bombenladung anfertigen könnt. (5 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202611] = {name = "[q4]10.1 Raid - Black Dragon Labs - Boss <#> - <Boss Name> - Accessory - Trinket - Physical DPS", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+447 [Beweglichkeit oder Stärke]\nVerkaufspreis:"}
MultiLanguageItemData['de'][202612] = {name = "[q4]Schreiende schwarze Drachenschuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+473 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure Angriffe und Fähigkeiten haben die Chance, Euch vergängliche Drachenflügel zu gewähren, die 15 Sek. lang Euren kritischen Trefferwert um 1022 und Euren Lebensraub um 285 erhöhen. (15s Abklingzeit)\n[q2]Benutzen: Ruft ein Echo von Neltharions Macht und lässt es auf den Boden unter Euch stürzen. Fügt Gegnern in der Nähe 24246 Schattenflammenschaden zu, wenn Ihr mindestens 15 Meter zurückgelegt habt. (3 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202613] = {name = "[q4]Chaosgreifkette der Zaqali", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+447 Stärke\n[q2]Benutzen: Schleudert die Greifkette bis zu 20 Meter weit, um Euer Ziel zu durchbohren. Verursacht 61039 körperlichen Schaden und zieht Euch mit gewaltiger Kraft zum Ziel. Verursacht beim Einschlag 83082 Vulkanschaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\n Der Einschlagsschaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202614] = {name = "[q4]Rashoks geschmolzenes Herz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+460 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, das Herz zu erwecken, was im Verlauf von 10 Sek. ( 146 * 10) Mana wiederherstellt und bewirkt, dass Eure Heilzauber im Verlauf von 10 Sek. zusätzlich ( 1491 * 10) Gesundheit pro Sekunde wiederherstellen.\n\n Überheilung durch diesen Effekt belebt Euer Ziel, was ihm 12 Sek. lang bis zu 380 Vielseitigkeit gewährt. (10s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202615] = {name = "[q4]Gefäß des sengenden Schattens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+447 Intelligenz\n{[q2]Anlegen: Eure offensiven Zauber haben eine hohe Chance, instabile Flammen aus dem Gefäß zu ziehen, was Euer {Tempo um 90 erhöht und Euch im Verlauf von 30 Sek. ( 133 * 30 / 3) {Feuerschaden} zufügt.\n\n Beim Erreichen von 5 Stapeln springen die Flammen auf Euer Ziel über und explodieren, was ihm sofort 29019 Schattenschaden} sowie im Verlauf von 12 Sek. zusätzlich ( 7255 * 6) Schattenflammenschaden zufügt.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][202616] = {name = "[q4]Robuste Schreckensplatte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+447 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Bedeckt Euch mit 5 Höllenstahlplatten, die pro Platte den erlittenen Schaden um 5320 und Eure Bewegungsgeschwindigkeit um 3% verringern. Hält bis zu 15 Sek. lang an.\n\n Das Erleiden von 44323 Schaden lässt eine Platte aufbrechen, was diese entfernt und eine Schattenflammensäule ausstößt, die allen von ihr erfassten Gegnern 19593 Schattenflammenschaden zufügt. Dieser Effekt kann nur einmal alle 2 Sek. auftreten. Bei Ablauf des Effekts brechen alle verbleibenden Platten. (2s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202617] = {name = "[q4]Elementiumtaschenamboss", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+447 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Schärft Eure Waffe mit Elementium, was [der Hauptklassenfähigkeit Eurer Nahkampfschadensspezialisierung] eine Chance gewährt, bei Treffern zusätzlich ( 37814 * 0.6) Schattenflammenschaden zu verursachen.\n[q2]Benutzen: Schlagt mit Eurer Waffe auf den Amboss, um sie zusätzlich zu verstärken. Fügt Gegnern in der Nähe 7221 Schattenflammenschaden zu und erhöht den Trefferschaden bis kurz nach Verlassen des Kampfes um 33%. 5-mal stapelbar. (1 Min Abklingzeit)\nVerkaufspreis:"}
