MultiLanguageItemData['de'][202667] = {name = "[q3]Versiegelte Artefaktschriftrolle", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q2]Benutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n[q]\"Eine magisch versiegelte Schriftrolle zum Fundort eines vergessenen Artefakts auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Drachenschuppenexpedition von Interesse sein.\""}
MultiLanguageItemData['de'][202668] = {name = "[q3]Versiegelte Geisterschriftrolle", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q2]Benutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n[q]\"Eine magisch versiegelte Schriftrolle zum Aufenthaltsort einer Geisterbestie auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Zentauren der Maruuk von Interesse sein.\""}
MultiLanguageItemData['de'][202669] = {name = "[q3]Versiegelte Fischschriftrolle", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q2]Benutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n[q]\"Eine magisch versiegelte Schriftrolle zu den Aufenthaltstorten seltener Fische auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für die Tuskarr von Iskaara von Interesse sein.\""}
MultiLanguageItemData['de'][202670] = {name = "[q3]Versiegelte Wissensschriftrolle", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q2]Benutzen: Markiert den Aufenthaltsort eines besonderen Schatzes auf Eurer Karte.\n[q]\"Eine magisch versiegelte Schriftrolle zu den Aufenthaltstorten verborgenen Wissens auf der Verbotenen Insel, wie vom blauen Drachen Lapisagos katalogisiert. Dies könnte für das Valdrakkenabkommen von Interesse sein.\""}
MultiLanguageItemData['de'][202690] = {name = "Ziersträucher", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Schön geformte Sträucher mit einem gewissen Extra.\""}
MultiLanguageItemData['de'][202691] = {name = "Henrys Handtasche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n10 Platz Reagenzientasche\nVerkaufspreis:"}
MultiLanguageItemData['de'][202692] = {name = "[q3]Dreschflegel des Gnollunholds", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Streitkolben}\n37 - 49 Schaden Geschwindigkeit 2.60\n(16.5 Schaden pro Sekunde)\n+15 [Beweglichkeit oder Stärke]\n+22 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 29.\nHaltbarkeit 110 / 110\n[q]\"Gnolle haben so kräftige Gebisse, dass sie damit die Knochen ihrer Gegner ganz einfach zermalmen können. Das hier nutzen sie nur zum Spaß.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][202693] = {name = "Drachenfruchtküchlein", additional_info = "Questgegenstand\n[q]\"Mit Liebe in Flammen gebacken.\""}
MultiLanguageItemData['de'][202694] = {name = "Lehmige Erde", additional_info = "Questgegenstand\n[q]\"Angereichert mit Nährstoffen aus dem Traum.\""}
MultiLanguageItemData['de'][202695] = {name = "Uraltes Wasser", additional_info = "Questgegenstand\n[q]\"Das Wasser scheint immer eine perfekte, erfrischende Temperatur zu haben.\""}
MultiLanguageItemData['de'][202696] = {name = "Trostentchen", additional_info = "Questgegenstand\n[q]\"Ein weiches Plüschtier, das schon von vielen Jungtieren geliebt wurde.\""}
MultiLanguageItemData['de'][202697] = {name = "Blutrotes Kissen", additional_info = "Questgegenstand\n[q]\"Höchster Komfort für Welpen.\""}
MultiLanguageItemData['de'][202698] = {name = "Die Stimme der Drachkin 4: Macht & Recht", additional_info = "Questgegenstand\n[q]\"Die Drachen haben über uns geherrscht, weil sie stärker waren als wir. Aber gemeinsam, in großen Zahlen, sind wir stärker als sie. Wenn Macht einem recht gibt, sind wir im Recht, solange wir den Mut haben, uns gemeinsam aufzulehnen. - Anstifterin Belaphon\""}
MultiLanguageItemData['de'][202699] = {name = "Die Stimme der Drachkin 2: 100 Jahrhunderte verlassen", additional_info = "Questgegenstand\n[q]\"Für 100 Jahre haben sie uns alleingelassen, während wir uns um \"ihre\" Inseln gekümmert, \"ihre\" Städte und \"ihre\" Straßen beschützt und den Frieden gewahrt haben. Und für was? Nur, um 99 weitere Male so zurückgelassen zu werden. Sollen wir sie mit offenen Armen willkommen heißen und uns ihnen wie gewohnt unterwerfen? - Anstifterin Belaphon\""}
MultiLanguageItemData['de'][202700] = {name = "Die Stimme der Drachkin 3: 100 Jahrhunderte unabhängig", additional_info = "Questgegenstand\n[q]\"Die Drachen sind zurückgekehrt und erwarten von uns, wie früher zu sein, doch wir haben uns in diesen 100 Jahrhunderten geändert. Wir sind gewachsen. Wir dienen ihnen nicht länger, sind keine Leibeigenen mehr. Wir haben unseren Pfad gewählt, für 10.000 Jahre, und das werden wir wieder. - Anstifterin Belaphon\""}
MultiLanguageItemData['de'][202701] = {name = "Die Stimme der Drachkin 5: Der Kodex der Rebellen", additional_info = "Questgegenstand\n[q]\"Und so schwören wir gemeinsam auf den Kodex der Rebellen. Keine Herrscher außer uns selbst. Keine Bestimmung ohne Unabhängigkeit. Kein Schwarm außer den Schwarmlosen. - Anstifterin Belaphon\""}
MultiLanguageItemData['de'][202702] = {name = "Die Stimme der Drachkin 1: Der Wert der Drachkin", additional_info = "Questgegenstand\n[q]\"Die Drachen glauben, dass sie mehr wert sind als wir. Deswegen musste sich Sendrax für ein Drachenei opfern, das vermutlich nicht mal lebensfähig ist. Sie sagen, sie wäre eine Heldin, doch in Wahrheit ist sie eines ihrer Opfer. - Anstifterin Belaphon\""}
MultiLanguageItemData['de'][202703] = {name = "Vergänglicher Sand", additional_info = "Questgegenstand\n[q]\"Die Sandkörner verschwinden vor Euren Augen.\""}
MultiLanguageItemData['de'][202705] = {name = "Schneckenschleim", additional_info = "Questgegenstand\n[q]\"Schleim, der von Schnecken gesammelt wurde und sich perfekt für die Herstellung von Räucherwerk eignet.\""}
MultiLanguageItemData['de'][202706] = {name = "[q2]Zandali-Piri-Piri", additional_info = "Questgegenstand\n[q]\"Kleine Chilischoten aus den Dschungeln Zandalars. Extrem scharf!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][202707] = {name = "[q2]Kokosnuss von Un'Goro", additional_info = "Questgegenstand\n[q]\"Außen hart, innen lecker süß. Gorillas lieben sie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][202708] = {name = "[q3]Kokoskrabbencurry", additional_info = "Questgegenstand\n[q]\"In exotischen Gewürzen und Kokosnussmilch geschmorte Krabbe.\""}
MultiLanguageItemData['de'][202709] = {name = "[q3]Scharfes gebratenes Talbuksteak", additional_info = "Questgegenstand\n[q]\"Ein Talbuksteak in Trockenmarinade, das über sengenden Flammen gegart wurde.\""}
MultiLanguageItemData['de'][202710] = {name = "[q3]Gegrillter Südstromlachs", additional_info = "Questgegenstand\n[q]\"Gewürzt und anschließend gegrillter Lachs. Wird mit Zitrone serviert.\""}
MultiLanguageItemData['de'][202711] = {name = "[q3]Verlorener Kompass", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Hält den Kompass.\n[q]\"Obwohl ein Fuß fest in der Mitte verankert ist, ist der Kreis vollendet, denn der andere endet, wo alles beginnt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][202712] = {name = "[q2]Gummifisch", additional_info = "[q2]Benutzen: Ihr könnt die meisten Haustiere apportieren lassen. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][202713] = {name = "Verstreute Vorräte", additional_info = "Questgegenstand\n[q]\"Ein Teil von Jeb und Tachas Expeditionsausrüstung.\""}
MultiLanguageItemData['de'][202714] = {name = "M.A.S.T.", additional_info = "Questgegenstand\n[q2]Benutzen: Wird genutzt, um den verderbten Verstand von Refti zu entgiften. (2s Abklingzeit)\n[q]\"Der \"Mehrzweck-Abfüll- und Speichertank\", kurz M.A.S.T., kann zum Abfüllen und Speichern verschiedener Arten von Energie verwendet werden und funktioniert anschließend wie eine Art Batterie.\""}
