MultiLanguageItemData['de'][202869] = {name = "Sengender Schlüssel", additional_info = "Wird beim Aufheben gebunden\n[q]\"Durch den Körper der Kernbestie aufgeheizt. Fast schon zu heiß für die Finger!\""}
MultiLanguageItemData['de'][202870] = {name = "[q3]Mysteriöse Schriften", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q]\"Ein Transkript verschlüsselter Geheimnisse, die einem von Neltharion verfassten Folianten entnommen wurde. Kann bei einem Gesandten des Valdrakkenabkommens auf der Verbotenen Insel eingetauscht werden.\""}
MultiLanguageItemData['de'][202871] = {name = "[q3]Drakonisches Artefakt", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q]\"Ein vorsichtig verpacktes Artefakt, das zum Vermächtnis der Dracthyr gehört. Kann bei einem Gesandten der Drachenschuppenexpedition auf der Verbotenen Insel eingetauscht werden.\""}
MultiLanguageItemData['de'][202872] = {name = "[q3]Zeichen des Segens", additional_info = "Dracheninselartefakte\nWird beim Aufheben gebunden\n[q]\"Ein Zeichen des von Ohn'ahra gewährten Glücks. Kann bei einem Gesandten der Maruukzentauren auf der Verbotenen Insel eingetauscht werden.\""}
MultiLanguageItemData['de'][202873] = {name = "Hängepilzzuschnitt", additional_info = "Questgegenstand\n70 ( 70)\n[q]\"Gibt etwas in Eurer Hand nach, während Ihr es in einer Tasche verstaut. Das wird ein hervorragender Verband.\""}
MultiLanguageItemData['de'][202874] = {name = "Heilgebräu", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Stellt bei einer verletzten Dunkelkralle oder einem verletzten Obsidianwächter Gesundheit wieder her. (2 Sek. Abklingzeit)\n[q]\"\"Für maximale Effektivität direkt die Kehle hinabschütten.\"\""}
MultiLanguageItemData['de'][202875] = {name = "Schneckenlasso", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft ein Lasso nach einer Schnecke, um sie zu bändigen und ihren Schleim einzusammeln."}
