MultiLanguageItemData['de'][203394] = {name = "Elementar geladene Kugel", additional_info = "Questgegenstand\n[q]\"Ein merkwürdiges, kugelförmiges Artefakt, das titanischen Ursprungs zu sein scheint. Doch ein Leuchten elementarer Macht dringt aus dem Inneren.\""}
MultiLanguageItemData['de'][203395] = {name = "Forschungsaufzeichnungen", additional_info = "Questgegenstand\n[q]\"Die Aufzeichnungen sind im Anbetracht ihres Alters in bemerkenswertem Zustand. Die Notizen darin werden Drachenschuppengelehrte über Jahre hinweg beschäftigen.\"\n[q2]<Zum Lesen rechtsklicken>"}
