MultiLanguageItemData['de'][203407] = {name = "[q4]Drakonisches Unterdrückungspulver", additional_info = "Handwerkliche Kuriositäten\n[q]\"Diese Lösung kann bestimmten Bemühungen der Primalisten auf der Verbotenen Insel entgegenwirken. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203408] = {name = "[q4]Uralter zeremonieller Dreizack", additional_info = "Handwerkliche Kuriositäten\n[q]\"Dieser Dreizack ist nicht für den Kampf gemacht. Er scheint ritueller Natur zu sein. Passt auf, wo Ihr in auf der Verbotenen Insel ablegt. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203409] = {name = "[q4]Beutel funkelnder Gewürze", additional_info = "Handwerkliche Kuriositäten\n[q]\"Die fehlende Zutat war Liebe! Das Aroma ist phänomenal. Ein wunderbarer Geschmack der Verbotenen Insel. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203410] = {name = "[q4]Leuchtendes Kristalllesezeichen", additional_info = "Handwerkliche Kuriositäten\n[q]\"Dieses glitzernde Lesezeichen bettelt darum, in ein gutes Buch, wie eines der Verbotenen Insel, gelegt zu werden. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203411] = {name = "[q4]Gnomischer Sprachkasten", additional_info = "Handwerkliche Kuriositäten\n[q]\"Wie kommt Gnomentechnologie auf die Verbotene Insel? Ihr benötigt eine Brummsäule, um sie abzuspielen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203412] = {name = "[q4]Arkane Bannrune", additional_info = "Handwerkliche Kuriositäten\n[q]\"Nachdem die Linien ausgebessert wurden, ist Euch klar geworden, dass diese Rune Zauberschutze, wie die auf der Verbotenen Insel, bannen soll. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203413] = {name = "[q4]Kristallstimmgabel", additional_info = "Handwerkliche Kuriositäten\n[q]\"An den richtigen Kristall auf der Verbotenen Insel geschlagen, könnte ein melodischer Klang entstehen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203414] = {name = "[q4]Verstärktes makelloses Leder", additional_info = "Handwerkliche Kuriositäten\n[q]\"Diese Flicken aus verstärktem Leder werden von den Tuskarr von Morqut oft verwendet, um beschädigte Bälge der Verbotenen Insel zu reparieren. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203415] = {name = "[q4]Traditioneller Morqutdrachen", additional_info = "Handwerkliche Kuriositäten\n[q]\"Manche sagen, dass an Pfosten geknüpfte Tuskarrdrachen auf der Verbotenen Insel auf den Schwingen des Geistes fliegen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203416] = {name = "[q4]Inaktiver Lebensblütensamen", additional_info = "Handwerkliche Kuriositäten\n[q]\"Auf der Verbotenen Insel gesammelt. Örtliches Ungeziefer wird vom Duft dieser besonderen Blüte angezogen. Löst womöglich eine besondere Begegnung aus.\"\nVerkaufspreis:"}
