MultiLanguageItemData['de'][203652] = {name = "Gaunahs Allzweck-Verzierungspulver", additional_info = "Optionales Handwerksmaterial\n\n[q2]Gewährt die folgende Eigenschaft: Gewährt Eurer hergestellten Ausrüstung eine nicht wahrnehmbare, aber garantiert echte Verbesserung.\n[q]Benutzbar mit: Techniken der Dracheninseln für die meisten schmucklosen, epischen Ausrüstungsteile.\n[q]\"Lässt jegliche vorherigen Verzierungen Eurer Ausrüstung garantiert alt aussehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][203653] = {name = "Leerer Elementarkern", additional_info = "Questgegenstand\n[q]\"Der inaktive Stein kühlt rasch in Eurer Hand ab und wartet darauf, sich an neue magische Energien zu binden.\""}
MultiLanguageItemData['de'][203654] = {name = "Flammentotem der Zaqali", additional_info = "Questgegenstand\n[q]\"Strotzt vor geschmolzener Lava, die durch Risse im Stein glüht.\""}
MultiLanguageItemData['de'][203655] = {name = "Durchnässter Schlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (2)\n[q]\"Ein nasser und schleimiger Schlüssel.\""}
MultiLanguageItemData['de'][203656] = {name = "Seltsames Gerät", additional_info = "Questgegenstand\n[q]\"Dieses Gerät sieht aus wie eine Rute mit einem Kristall an einem Ende und einem Griff am anderen Ende, um es zu halten. Es sieht alt aus, kommt Euch aber irgendwie bekannt vor, so als hättet Ihr es schon mal irgendwo gesehen. Könnte für Voraxian von Interesse sein.\""}
MultiLanguageItemData['de'][203657] = {name = "[q2]Toxingegenmittel", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine kleine Flasche Gegenmittel, um die Auswirkungen der Gase im Unterstützungshort zu bekämpfen.\""}
