MultiLanguageItemData['de'][204344] = {name = "Leitfähiger Leitstein", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht getöteten bröckelnden Schlacken in der Nähe Energie.\n\n Wenn der Leitstein voll aufgeladen ist, setzt ihn gegen Hochbeschwörerin Wahuna ein, um ihren Schild zu überladen.\n[q]\"Der polierte Stein zerrt Euch in die Richtung von Quellen großer elementarer Macht.\""}
