MultiLanguageItemData['de'][204352] = {name = "[q3]Elementarschleimrest", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 50 Elementarschleimreste, um etwas Neues zu erschaffen.\n[q]\"Sich windender Elementarschleim, den mächtige Anführer der Primalisten bei sich hatten. Die Masse scheint sich selbst wieder zusammenziehen zu wollen.\""}
MultiLanguageItemData['de'][204353] = {name = "[q3]Urzeitliches Juweliersset", additional_info = "Questgegenstand\n[q]\"Eine Sammlung von einzigartigen Werkzeugen. Um sie alle zu beherrschen, würde es Jahre dauern.\""}
MultiLanguageItemData['de'][204354] = {name = "[q3]Geheiligtes Nahrungsbündel der Furbolgs", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nRücken\nErfordert einen wohlwollenden Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][204355] = {name = "[q3]Geheiligtes Nahrungsbündel der Winterpelze", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nRücken\nErfordert einen respektvollen Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][204356] = {name = "[q2]Glänzender Juwelenstaub", additional_info = "Wird beim Aufheben gebunden\nHandwerksmaterial\n[q]\"Wird von Juwelenschleifern durch das Zermahlen von Edelsteinen gefertigt, die durch den Kataklysmus offengelegt wurden. Kann in Sturmwind oder Orgrimmar gegen Symbole des erhabenen Juweliers eingetauscht werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][204359] = {name = "[q3]Geldbeutel des Rennmeisters", additional_info = "Wird beim Aufheben gebunden\n[q]\"Voller Gold, Vorräten der Dracheninseln und einer Chance auf ein Drachenwächtermanuskript.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][204360] = {name = "[q3]Seltsam versteinerte Kugel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die seltsam versteinerte Kugel und ein Fragment schwarzer Drachenschuppen, um die Versteinerung umzukehren.\n[q]\"Dieses Objekt ist seit Tausenden von Jahren in den Gewölben eingeschlossen und dabei steinhart geworden. Vielleicht kann mächtige Erdmagie seinen ursprünglichen Zustand wiederherstellen.\""}
MultiLanguageItemData['de'][204361] = {name = "[q4]Schlängelnder Kriecherdrache", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren schlängelnden Kriecherdrachen oder gibt ihn wieder frei.\n\n Bei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Diese Drachen fühlen sich in den Tiefen der Erde und den Weiten des Himmels zuhause.\"\nErfolg:\nEine schlangenhafte Entdeckung"}
MultiLanguageItemData['de'][204363] = {name = "[q3]Besonders gewöhnliches Ei", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer besonders gewöhnliches Ei mit einem Tropfen mit Magie des blauen Drachenschwarms, um es zu verzaubern.\n[q]\"An diesem Ei scheint nichts Besonders zu sein. Vielleicht kann es durch etwas in den Gewölben verzaubert werden.\""}
MultiLanguageItemData['de'][204364] = {name = "[q3]Magisch verändertes Ei", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombinieren Euer magisch verändertes Ei und einige ewig brennende Rubinkohlen, um es auszubrüten.\n[q]\"Ein Ei, das mit geheimnisvoller Magie des blauen Drachenschwarms durchwirkt wurde. Vielleicht findet Ihr in den Gewölben etwas, das es ausbrüten kann.\""}
MultiLanguageItemData['de'][204365] = {name = "Bündel Schwarzspeere", additional_info = "Questgegenstand\n[q2]Benutzen: Durchbohrt die Leiche eines Djaradin der Zaqali mit einem Schwarzspeer. (5 Sek. Abklingzeit)\n[q]\"Eine Ansammlung von Speeren, die vom schwarzen Drachenschwarm geführt werden. Immer noch so scharf wie an dem Tag, an dem sie geschmiedet wurden.\""}
MultiLanguageItemData['de'][204366] = {name = "[q3]Ei unbekannten Inhalts", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer Ei unbekannten Inhalts mit einem Bronzestaubkorn, um es altern zu lassen.\n[q]\"Das mysteriöse Ei ist endlich fertig ausgebrütet, aber die Kreatur darin lässt sich nicht ausmachen. Vielleicht erkennt man sie besser, wenn sie weiter gewachsen ist. In den Gewölben findet sich bestimmt etwas für beschleunigtes Wachstum.\""}
MultiLanguageItemData['de'][204367] = {name = "[q3]Schlafendes uraltes Mammut", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer schlafendes uraltes Mammut mit einer Smaragddrachenbrosche, um es aufzuwecken.\n[q]\"Aus Eurem veränderten Ei ist ein Mammut entwachsen? Das scheint so nicht vorgesehen zu sein, aber es gibt auch keinen Grund, jetzt aufzuhören. Findet einen Weg, es aufzuwecken, und holt Euch Euren Preis!\""}
MultiLanguageItemData['de'][204369] = {name = "[q3]Fragment schwarzer Drachenschuppen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die seltsam versteinerte Kugel und ein Fragment schwarzer Drachenschuppen, um die Versteinerung umzukehren.\n[q]\"Diesen abgeworfenen schwarzen Drachenschuppen wohnt immer noch ein Schimmer von Erdmagie inne. Mit dem Fragment könnten vielleicht kleinere Versteinerungen rückgängig gemacht werden.\""}
MultiLanguageItemData['de'][204370] = {name = "Stinkender heller Trank", additional_info = "Toxisch\n[q2]Benutzen: Erhellt die Welt um Euch herum.\n[q]\"Mischt zwei Teile zerstampftes Steinbrich mit einem Teil reinen Verfall und gebt ein paar mysteriöse Sporen dazu, um den Anwender auf Trab zu halten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][204371] = {name = "[q3]Tropfen mit Magie des blauen Drachenschwarms", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer besonders gewöhnliches Ei mit einem Tropfen mit Magie des blauen Drachenschwarms, um es zu verzaubern.\n[q]\"Das Bild auf der Phiole ist schwer zu erkennen, aber es handelt sich wohl um einen Drachen. Die Phiolen sollten am besten neue Etiketten bekommen.\""}
MultiLanguageItemData['de'][204372] = {name = "[q3]Bronzestaubkorn", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer Ei unbekannten Inhalts mit einem Bronzestaubkorn, um es altern zu lassen.\n[q]\"Niemand würde Staub in einer Schatztruhe verstecken. Es handelt sich wahrscheinlich um einen potenten Bronzedrachenkatalysator für Zeitmagie. Davon sollte man nicht zu viel verwenden!\""}
MultiLanguageItemData['de'][204373] = {name = "[q3]Mitgenommene Rumble-Folie", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Macht sie wieder glatt.\n[q]\"Macht sie wieder glatt.\""}
MultiLanguageItemData['de'][204374] = {name = "[q3]Smaragddrachenbrosche", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert Euer schlafendes uraltes Mammut mit einer Smaragddrachenbrosche, um es aufzuwecken.\n[q]\"Trotz der kleinen Risse ist darin die verborgene Macht des Smaragdgrünen Traums zu spüren. Damit sollte jede Kreatur aufzuwecken sein.\""}
MultiLanguageItemData['de'][204375] = {name = "[q3]Ewig brennende Rubinkohlen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombinieren Euer magisch verändertes Ei und einige ewig brennende Rubinkohlen, um es auszubrüten.\n[q]\"Eine Handvoll Kohlen, die sich warm anfühlen. Die Wärme muss von den heilenden Feuern eines alten roten Drachen stammen. Vielleicht helfen die Kohlen, etwas Kleines zum Leben zu erwecken.\""}
MultiLanguageItemData['de'][204377] = {name = "Leuchtsporen", additional_info = "Questgegenstand\n[q]\"Leuchtender Pilz den Schnüffelmäuse besonders gut aufspüren können.\""}
MultiLanguageItemData['de'][204378] = {name = "[q4]Randvolles Vorratspaket der Drachenschuppenexpedition", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q]\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Drachenschuppenexpedition erwiesen haben.\"\n[q2]<Zum Öffnen rechtsklicken>"}
