MultiLanguageItemData['de'][204471] = {name = "[q4]Fehlerhaftes Überlebenspaket", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Gedacht, um dem Träger das Schwimmen in Lava zu ermöglichen. Es gibt bestimmt einen guten Grund, warum es zurückgelassen wurde.\""}
MultiLanguageItemData['de'][204473] = {name = "Elementschröpfer", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht erfüllten Felsschnecken Elementarenergie, um einzigartige Kräfte zu erhalten. (5 Sek. Abklingzeit)\n[q]\"Ein Gerät, das von unterirdischen Kreaturen gesammelte unerschütterliche Kräfte aufspürt und ihnen entzieht.\""}
MultiLanguageItemData['de'][204474] = {name = "Silberschuppe", additional_info = "Questgegenstand\n[q]\"Das reine Silber strahlt eine uralte Energie aus.\""}
MultiLanguageItemData['de'][204475] = {name = "[q4]Kaputter Wyrmlochgenerator", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Er wäre noch funktional, hätte der vorherige Besitzer zwei Schritte nach links gemacht.\""}
MultiLanguageItemData['de'][204480] = {name = "[q4]Unauffälliger Datenschürfer", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Hätte das versteckt sein sollen?\""}
MultiLanguageItemData['de'][204481] = {name = "[q2]Herdtotem von Morqut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Teleportiert den Zaubernden zum Morqutdorf. Kann nur auf der Verbotenen Insel aktiviert werden. (20 Min Abklingzeit)\n5 Aufladungen\n[q]\"Nicht alle Tuskarr, die auf Erkundungsreise gehen, sind verloren.\""}
MultiLanguageItemData['de'][204558] = {name = "[q2]Reliquiar-Schriftrolle der Wahrnehmung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ermöglicht dem Zaubernden für 1 Stunde, beim Erforschen der verbotenen Insel kleine Schätze zu finden.\n[q]\"Selbst Drachen haben Schätze gehortet, deren Wert sie nicht kannten.\""}
MultiLanguageItemData['de'][204559] = {name = "[q2]Essenz der Wahrsagung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Ermöglicht dem Zaubernden einen Tag lang, die Geister der Ahnen auf der Verbotenen Insel das Erscheinen einzigartiger Bedrohungen vorhersagen zu hören.\n[q]\"Selbst der jüngste Krieger mag in der Lage sein, den Verlauf der Zukunft zu spüren.\""}
MultiLanguageItemData['de'][204560] = {name = "[q2]Azur-Aufzeichnungskristall", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Erhöht für 1 Stunde die Chance, durch Schätze und Begegnungen auf der verbotenen Insel versiegelte Schriftrollen zu erhalten. Effekt wird bei Plünderung entfernt.\n[q]\"Jede Begegnung ist eine Chance, neue Geheimnisse zu enthüllen.\""}
