MultiLanguageItemData['de'][204699] = {name = "Durchströmte Barren", additional_info = "Questgegenstand\n[q]\"Die Oberfläche dieser Metallstäbe reißt und wellt sich, als wären sie geschmolzen. Ihre physischen Formen sind kaum imstande, die elementare Macht, die sie durchdringt, zurückzuhalten.\""}
MultiLanguageItemData['de'][204704] = {name = "[q4]Adaptive Dracothystarmschützer", additional_info = "Wird beim Aufheben gebunden\nHandgelenk Kette\n277 Rüstung\n+144 [Beweglichkeit oder Intelligenz]\n+234 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 134.\n[q2]Erhöht Eure Meisterschaftswertung um + 134.\nHaltbarkeit 55 / 55\n{[q2]Anlegen: Ihr passt Euch gelegentlich für 12 Sek. Eurer aktuellen Situation an.\n\n Schaden} zu erleiden, kann Eure Vielseitigkeit und Euren kritischen Trefferwert um 170 erhöhen.\n\n Kritischen Schaden} oder Heilung zu verursachen, kann Eure Meisterschaft und Euer {Tempo um 170 erhöhen.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][204705] = {name = "Goldmünzen", additional_info = "Questgegenstand\n[q]\"Das Gewicht fühlt sich gut in Euren Händen an.\""}
MultiLanguageItemData['de'][204706] = {name = "[q4]Schulterschützer der Sporenkolonie", additional_info = "Wird beim Aufheben gebunden\n{Schulter} {Leder}\n258 Rüstung\n+193 [Beweglichkeit oder Intelligenz]\n+312 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 179.\n[q2]Erhöht Eure Tempowertung um + 179.\nHaltbarkeit 100 / 100\n[q2]Anlegen: Wenn Ihr mit Zaubern und Fähigkeiten Schaden verursacht, habt Ihr eine Chance, Euer Ziel mit einem Stapel 'Ewig verfallende Sporen' zu belegen. Bei 5 Stapeln verfallen die Sporen rapide, was ( 776 * 10) Naturschaden im Verlauf von 10 Sek. verursacht.\n\n Manchmal verfallen die Sporen sofort und fügen Euch 776 Naturschaden zu.\n\n Dieser Effekt erhöht sich um 100%, wenn Ihr einen Gegenstand ausgerüstet habt, der mit einem giftigen Rüstungsflicken hergestellt wurde.\nVerkaufspreis:"}
