MultiLanguageItemData['de'][205168] = {name = "[q4]Überschatteter Einschlagsrundschild", additional_info = "Wird beim Aufheben gebunden\n{Schild}hand} {Schild}\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n+208 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 133.\n[q2]Erhöht Eure Meisterschaftswertung um + 106.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Das Erleiden von Schaden gewährt eine Chance, Stapel von 'Überschatteter Feuerbrand' anzusammeln.\n\n Bei 5 Stapeln setzt Eure nächste Fähigkeit die angesammelte Energie frei und verursacht 1989 Schattenflammenschaden, der zwischen allen Gegnern innerhalb von 10 Metern aufgeteilt wird. Dieser Effekt wiederholt sich für jeden Stapel von 'Überschatteter Feuerbrand'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][205169] = {name = "Glimmerpilz", additional_info = "Questgegenstand\n[q]\"Ein köstlicher Wildpilz voll erdiger Aromen, der als niedrigkalorische Proteinquelle mit medizinischen Eigenschaften bekannt ist. Ideal für gesundheitsbewusste Champions, die etwas Nahrhaftes brauchen.\""}
