MultiLanguageItemData['de'][205191] = {name = "[q2]Tiefenlichtglobus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 342.\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, den Globus zu entzünden, was Tiefenlichtmotten anlockt. Wenn Ihr eine angelockte Motte einsammelt, erhaltet Ihr 'Tiefenlichtharmonie', was Eure Hauptwert 10 Sek. lang um 1408 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][205192] = {name = "[q2]Unbeständiger Kristallsplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Intelligenz\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine Chance, den Kristallsplitter auf Euer Ziel abzufeuern. Er zersplittert bei Kontakt mit einem Gegner und verursacht 12669 körperlichen Schaden, der zwischen allen Gegnern in der Nähe aufgeteilt wird.\nVerkaufspreis:"}
