MultiLanguageItemData['de'][205200] = {name = "[q2]Keimende Zwielichtglut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, die Glut zu entzünden, was Euch im Verlauf von 10 Sek. 18935 Schattenflammenschaden zufügt und Euer Tempo um 1367 erhöht.\n[q2]Anlegen: Beim Erleiden von Schattenflammenschaden besteht eine Chance, dass Eure Geschwindigkeit 10 Sek. lang um 382 erhöht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][205201] = {name = "[q2]Schwelendes Heulerhorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Ruft einen Hund herbei, der ein schwelendes Heulen ausstößt und Euren kritischen Trefferwert 20 Sek. lang um 1230 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
