MultiLanguageItemData['de'][205203] = {name = "[q4]Kobaltschieferschwinge", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Brut Karoktas, aufgewachsen im Tiefenlicht der Zaralekhöhle.\"\nBeute von:\nKarokta\nZone:\nZaralekhöhle"}
MultiLanguageItemData['de'][205204] = {name = "[q4]Flammende Schieferschwinge, Subjekt 01", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man eine katalogisierte Schieferschwinge als Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die erste entdeckte Art einer flammenden Schieferschwinge. Neun von zehn Wissenschaftlern sind sich einig: Er ist heiß!\"\nZone:\nZaralekhöhle\nÖffentliches Ereignis:\nForscher unter Feuer"}
MultiLanguageItemData['de'][205205] = {name = "[q4]Schattenflammenschieferschwinge", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ihr Panzer bestand ursprünglich aus dem geschmolzenen Magma, in dem sie geboren wurde, das dann zu dunklem Vulkangestein abkühlte. Die Macht der Schattenflamme machte ihn dann vollends unzerbrechlich.\"\nErfolg:\nRuhm des Aberrusschlachtzüglers"}
MultiLanguageItemData['de'][205207] = {name = "[q4]Happenschnüffler-Zügel", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Niffen von Loamm.\n\n\n[q]\"Eine Schieferschwingenart, die von den Niffen darauf abgerichtet wird, selbst die verstecktesten Happen zu finden.\"\nVerkäufer:\nHarlowe Marl\nZone:\nZaralekhöhle\nKosten:\n800"}
MultiLanguageItemData['de'][205208] = {name = "[q4]Sandige Schieferschwinge", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Muster auf den Schwingen dieser Kreatur ähneln Sand, der durch ein Stundenglas fließt. Man könnte sie ganze Zeitalter lang betrachten...\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000"}
MultiLanguageItemData['de'][205209] = {name = "[q4]Felsbrockenschlepper-Zügel", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Schieferschwingen wurden speziell darauf abgerichtet, große Mengen von Tauschfelsbrocken für die Feilscherei der Niffen zu tragen.\"\nVerkäufer:\nPonzo\nZone:\nZaralekhöhle\nKosten:\n85"}
MultiLanguageItemData['de'][205211] = {name = "[q4]Verdünnte Protonährlösung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)"}
MultiLanguageItemData['de'][205212] = {name = "[q4]Markgereifter Schleim", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)\n[q]\"Ganz egal, wie Ihr ihn haltet, die Knochen schwimmen immer oben.\""}
MultiLanguageItemData['de'][205213] = {name = "[q4]Verdächtiger Schimmel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)\n[q]\"Ihr fühlt, wie er sich in Eurer Hand windet, sobald Ihr wegseht.\""}
MultiLanguageItemData['de'][205214] = {name = "[q4]Schroffe Schneckenhäuser", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigtJuwelierskunst der Dracheninseln\n(25)\n[q]\"Niemand will diese langweiligen Hüllen, wo juwelenbesetzte Häuser doch gerade der letzte Schneckenschrei sind!\""}
MultiLanguageItemData['de'][205216] = {name = "[q4]Leicht durchgeschüttelte Juwelen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigtJuwelierskunst der Dracheninseln\n(25)\n[q]\"Das ist ein höflicher Ausdruck für einen Haufen wertloser Edelsteinsplitter. Wenigstens sind sie hübsch!\""}
MultiLanguageItemData['de'][205217] = {name = "Scharfschnabels Futter", additional_info = "Questgegenstand\n[q]\"Das kräftige Korn wiegt schwer in Eurer Tasche, und der Geruch, der davon aufsteigt, erinnert Euch an goldene Felder.\""}
MultiLanguageItemData['de'][205219] = {name = "[q4]Zerbrochener Tauschfelsbrocken", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigtJuwelierskunst der Dracheninseln\n(25)\n[q]\"Nicht genug raue Kanten, um als Tauschziegel durchzugehen, aber viel zu viele, um als Tauschfelsbrocken akzeptiert zu werden.\""}
