MultiLanguageItemData['de'][205902] = {name = "Tiefenschinderklaue", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Diese Kristallklaue ist rasiermesserscharf!\""}
MultiLanguageItemData['de'][205903] = {name = "Tauschkiesel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft einen Kieselbrocken weg.\n[q]\"Die Überreste einer zerbrochenen Tauschmarke. Kann in Loamm in der Zaralekhöhle gegen Waren eingetauscht oder für ein Silber verkauft werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][205904] = {name = "[q3]Leuchtende klickende Schere", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Klickt drei Mal mit der Schere und verwandelt Euch 10 Min. lang in einen Urmakrura."}
MultiLanguageItemData['de'][205906] = {name = "Gefiederter Freund", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Dieses Entenplüschtier ist stark abgenutzt. Sein früherer Besitzer hat es offensichtlich sehr geliebt.\""}
MultiLanguageItemData['de'][205907] = {name = "Durchnässtes Totem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Diese merkwürdige Statuette ist komplett durchnässt, als wäre sie gerade erst unter Wasser getunkt worden. Sie gibt auch einen strengen fischigen Geruch von sich.\""}
MultiLanguageItemData['de'][205908] = {name = "[q3]Vererbte Weisheit von Senegos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Ein Teil der Weisheit des uralten blauen Drachen, überliefert in einer Form, die er sicherlich für amüsant hielt. Denkt an eine Ja-Nein-Frage und lasst Euch davon leiten. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][205909] = {name = "Gespanntes Segeltuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Ein schönes Stück gespannten Segeltuchs. Könnte für eine Trommel oder als Leinwand für ein Geruchsgemälde verwendet werden.\""}
MultiLanguageItemData['de'][205910] = {name = "Blubberndes Elixier", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Die Flüssigkeit in diesem verzierten Behälter riecht nach Blaubeeren und Meerwasser. Sie blubbert so stark, dass es fast schon wie ein Zischen klingt.\""}
MultiLanguageItemData['de'][205911] = {name = "Mysteriöses Räucherwerk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Das ist definitiv Räucherwerk, doch es riecht komplett anders als das aus Loamm!\""}
MultiLanguageItemData['de'][205912] = {name = "Lederumhüllte Flasche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Es riecht, als wäre die Flasche leer, doch feine Geruchsnoten eines herben Getränks sind noch zu wahrzunehmen.\""}
MultiLanguageItemData['de'][205913] = {name = "Leeres Notizbuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n[q]\"Ein recht großes, leeres Buch (nach Niffenstandard).\""}
