MultiLanguageItemData['de'][206011] = {name = "[q3]Entwürfe der Knochen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Knochenentwürfen.\n[q]\"Dekoriert mit uralten Symbolen von Knochen und Erde.\""}
