MultiLanguageItemData['de'][206013] = {name = "[q3]Entwürfe der Seele", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Seelenentwürfen.\n[q]\"Dekoriert mit uralten Symbolen von Seele und Luft.\""}
MultiLanguageItemData['de'][206014] = {name = "[q3]Ouroboros-Tafel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Knochenentwürfen.\n[q]\"Kreisförmige Zeichnungen zeigen ein großes Spiralmuster, das auf der linken Seite beginnt. Symbole von Wasser und Blut fließen in dieses und die fehlenden Bereiche am unteren Ende.\""}
MultiLanguageItemData['de'][206015] = {name = "[q3]Ouroboros-Tafel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Geistesentwürfen.\n[q]\"Symbole von Knochen und Erde säumen den Weg der Spirale, die sich von unten zur fehlenden rechten Seite windet.\""}
MultiLanguageItemData['de'][206016] = {name = "[q3]Ouroboros-Tafel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Seelenentwürfen.\n[q]\"Symbole von Geist und Feuer winden sich um die geschnitzte Spirale, bewegen sich nach innen und oben, bis sie die Spitze erreichen.\""}
MultiLanguageItemData['de'][206017] = {name = "[q3]Ouroboros-Tafel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert die Ouroborostafel mit Kob'roks leuchtender Schuppe.\n[q]\"Sorgfältig gezeichnete Symbole von Seele und Luft zieren die Spitze, von wo sich die Spirale sich nach innen windet. Der Ouroboros in der Mitte strahlt hell, während violette Energie durch die Spirale und in die Mitte gesogen wird.\""}
