MultiLanguageItemData['de'][206560] = {name = "[q4]Uralte Pläne: Stygischer Schild", additional_info = "[q2]Benutzen: Lehrt Euch, wie man einen stygischen Schild herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\n[q4]Stygischer Schild\nWird beim Anlegen gebunden\n{Schild}hand} {Schild}\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\nHaltbarkeit 120 / 120\n[q2]Anlegen: Bei einem Treffer besteht eine Chance von 15%, dass die Bewegungsgeschwindigkeit des Angreifers 5 Sek. lang um 50% verringert wird. Es besteht die Chance, dass der Effekt gegen Ziele über Stufe 49 nicht wirkt. (Procchance: 15%)\nVerkaufspreis: \nBenötigt Kampfzerrissene Fetzen (60), Goldbarren (20), Arkanitbarren (6), Geisterfarbstoff (16), Großer Opal (20)"}
MultiLanguageItemData['de'][206561] = {name = "[q3]Uraltes Muster: Luciens verlorene Sohlen", additional_info = "[q2]Benutzen: Lehrt Euch, wie man Luciens verlorene Sohlen herstellt.\nBenötigt Klassische Lederverarbeitung (300)\nVerkaufspreis:\n[q3]Luciens verlorene Sohlen\nWird beim Anlegen gebunden\n{Füße} {Leder}\n4 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 60 / 60\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (16), Geschmeidiger unverwüstlicher Balg (4), Essenz des Untodes (6), Runenfaden (6)"}
MultiLanguageItemData['de'][206562] = {name = "[q4]Tuch der verbotenen Magie", additional_info = "Kosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206563] = {name = "[q4]Uraltes Muster: Tuch der verbotenen Magie", additional_info = "[q2]Benutzen: Lehrt Euch, wie man ein Tuch der verbotenen Magie herstellt.\nBenötigt Klassische Schneiderei (300)\n\n\n[q4]Tuch der verbotenen Magie\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (200), Essenz des Untodes (100), Teufelsstoff (50), Großer glänzender Splitter (60), Dunkelrune (25), Geisterfarbstoff (20)"}
MultiLanguageItemData['de'][206564] = {name = "Zeitverschobene Titanenscheibe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Dieser Gegenstand ist eindeutig titanischen Ursprungs. Trotz des Speichels, der davon herabtropft, scheint die Scheibe immer noch funktionsfähig zu sein.\""}
MultiLanguageItemData['de'][206565] = {name = "[q3]Verseuchtes Korn", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Platziert für 3 Min. eine Kiste mit ganz gewöhnlichem Korn. Niemand wird sich etwas dabei denken. (2 Std. Abklingzeit)\n[q]\"Eine an die Kapelle des Hoffnungsvollen Lichts adressierte Kiste. Zum Glück kam sie nie dort an.\""}
MultiLanguageItemData['de'][206566] = {name = "[q4]Zügel des scharlachroten Pterrordax", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen scharlachroten Pterrordax beschwört.\n[q2]Beschwört Euren scharlachroten Pterrordax oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Pterrordax war so eifrig darauf, sich in die Lüfte zu schwingen, dass sein Trainer die Ausbildung nicht beenden konnte.\"\nQuest:\nZeit zum Fliegen"}
MultiLanguageItemData['de'][206567] = {name = "[q4]Hafengreif", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen Hafengreifen beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Greif war der kleinste seines Rudels und wurde zurückgelassen, als seine Geschwister in die Ausbildung geschickt wurden. Heute ist er jedoch bereit, sich zu beweisen.\"\nQuest:\nZeit zum Fliegen"}
