MultiLanguageItemData['de'][206578] = {name = "Ein Schädel mit Geweih", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Trotz der Zeitlinie, aus der er stammt, ist dieser Schädel unerklärlicherweise frei von Teufelsenergie. Ihr spürt eine seltsame Ruhe, wenn Ihr ihn haltet.\""}
MultiLanguageItemData['de'][206579] = {name = "[q4]Phylaktergewebe", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig (1400)\nHandwerksmaterial\n[q]\"Seine seelenabsorbierenden Eigenschaften machen es zu einer essentiellen Komponente bei der Läuterung entweihter Gegenstände.\""}
