MultiLanguageItemData['de'][206585] = {name = "[q4]Zügel von Tapferkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man Tapferkeit beschwört.\n[q2]Beschwört Tapferkeit oder gibt das Ross wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Für die meisten untoten Rösser wird der Reiter ausgewählt. Tapferkeit jedoch wählt seine Reiter selbst.\"\nEntdeckung:\nTapferkeit\nOrt:\nNaxxramas"}
MultiLanguageItemData['de'][206586] = {name = "Epochenextraktor", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht besiegten zeitverlorenen Kreaturen innerhalb von 15 Metern zeitverlorene Essenz. (3 Sek. Abklingzeit)\n[q]\"Ein Gerät, mit dem Ihr die Essenz zeitverlorener Kreaturen stehlen könnt.\""}
