MultiLanguageItemData['de'][206645] = {name = "[q4]Verfluchter Stoff", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\n Der so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Magier, Priester oder Hexenmeister geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206646] = {name = "[q4]Ermattetes Leder", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\n Der so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Druiden oder Schurken geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:"}
