MultiLanguageItemData['de'][206648] = {name = "[q4]Untodesmetall", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\n Der so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Paladin oder Krieger geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206653] = {name = "Teufelskiefernzapfen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (4)\n70 ( 70)\n[q]\"Teuflisch, gärend, verrottet: Perfekt, um damit eine Teufelskanone zu laden!\""}
MultiLanguageItemData['de'][206670] = {name = "[q3]Finsterwurzelgreifer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Zieht ein Paar Finsterwurzelgreifer über Eure Rüstung, um Schattenwurzelranken aus dem Boden ziehen zu können.\n\n Ranken können im Fungusfeld und nahegelegenen Schlüsselflammengebieten gefunden werden. (5 Sek. Abklingzeit)\n[q]\"Robuste Panzerhandschuhe, um Peitscherranken unbeschadet zu greifen.\""}
MultiLanguageItemData['de'][206671] = {name = "[q4]Hellebarde des Obsidiangladiators", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stangenwaffe}\n836 - 1,553 Schaden Geschwindigkeit 3.60\n(331.8 Schaden pro Sekunde)\n+441 Stärke\n+1.295 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 207.\n[q2]+ 517 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:"}
MultiLanguageItemData['de'][206673] = {name = "[q4]Horn des weißen Kriegswolfs", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren weißen Kriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Kann der Hunger eines Wolfs je gestillt werden? Diese Wolfsbestien suchen und verschlingen die Feinde der Horde.\"\nHorde\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nAllianz\nGegenstand:\nGeschenk des weißen Kriegswolfs"}
MultiLanguageItemData['de'][206674] = {name = "[q4]Zügel des hungrigen schwarzen Greifen", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man einen hungrigen schwarzen Greifen beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Krieg hat diese einst stolzen Kreaturen verdorben. Das Flüstern ihrer Schwingen säuselt jetzt von Omen eines nahenden Untergangs.\"\nAllianz\nBeute von:\nZeitrisse\nVerkäufer:\nWächterin Krizzik\nZone:\nTyrholdreservoir\nKosten:\n3.000\n\nHorde\nGegenstand:\nGeschenk des hungrigen schwarzen Greifen"}
MultiLanguageItemData['de'][206675] = {name = "[q4]Goldzehenalbatros", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Aus einem fernen Zeitweg emporgestiegen, wurde dieser noch nie gesehene Vertreter der Vögel in einer geordneten Welt geboren.\"\nBeute von:\nZeitrisse\nVerkäufer:\nSorotis\nZone:\nTyrholdreservoir\nKosten:\n3.000"}
MultiLanguageItemData['de'][206676] = {name = "[q4]Teufelssturmdrache", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Brennende Legion besiegte Drachen in einem fernen Zeitweg. Diese üblen Teufelswyrms wählten Verderbnis und Knechtschaft, um der Vernichtung zu entgehen.\"\nBeute von:\nZeitrisse\nVerkäufer:\nFalara Nachtweise\nZone:\nTyrholdreservoir\nKosten:\n3.000"}
MultiLanguageItemData['de'][206678] = {name = "[q4]Schwefelhundeleine", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren Schwefelhund oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das Schwarze Imperium unterwarf diese demütigen und hasserfüllten Hunde. Grenzenlos unterwürfig dienen sie noch immer den Starken.\"\nBeute von:\nZeitrisse\nVerkäufer:\nVersorgerin Qorra\nZone:\nTyrholdreservoir\nKosten:\n3.000"}
MultiLanguageItemData['de'][206679] = {name = "[q4]Perfektionierter Koloss", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen perfektionierten Koloss beschwört. Das ist ein Bodenreittier.\n[q2]Beschwört den perfektionierten Koloss oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wie Schönheit liegt auch Perfektion im Auge des Betrachters. Doch Sehkraft kann chirurgisch verbessert werden.\"\nBeute von:\nZeitrisse\nVerkäufer:\nNora mit dem Bohrer\nZone:\nTyrholdreservoir\nKosten:\n3.000"}
MultiLanguageItemData['de'][206680] = {name = "[q4]Zügel des geißelgebundenen Bezwingers", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren geißelgebundenen Frostbrutbezwinger oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Einstmals im Dienst der Geißel stehend existieren diese untoten Drachen nur, um Tod, Krankheit und Zerstörung zu verbreiten.\"\nBeute von:\nZeitrisse\nVerkäufer:\nBaron Splitter\nZone:\nTyrholdreservoir\nKosten:\n3.000"}
