MultiLanguageItemData['de'][206956] = {name = "[q4]Parakausales Fragment von Sulfuras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, zusätzlich 9875 Feuerschaden zu verursachen. Eure offensiven Nahkampffähigkeiten haben eine Chance, das Fragment ausbrechen zu lassen, sodass es 8229 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Das Fragment hat zusätzlich eine Chance, auf Euren erlittenen Schaden zu reagieren und mit einem Gegenangriff 9875 Feuerschaden zu verursachen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206957] = {name = "Gripsi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Dieser kleine Roboter sprang frohen Mutes in Eure Arme, als Ihr ihn aufheben wolltet. Er surrt fröhlich in Eurer Tasche und klingt fast schon so, als würde er schnurren.\""}
MultiLanguageItemData['de'][206958] = {name = "[q4]Parakausales Fragment von Val'anyr", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, Euch für 15 Sek. den Segen der Ewigen Könige zu gewähren, durch den Eure Heilungen das Ziel bis zu zehnmal mit einem Schild umhüllen, der 10980 Schaden absorbiert. Der Schild hält 8 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206959] = {name = "[q4]Funke der Träume", additional_info = "Saison 3 von Dragonflight\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\n[q2]Gewährt die folgende Eigenschaft: Legt die Startgegenstandsstufe nach Herstellungsqualität (450-463) fest, markiert als 'Traumgefertigt'.\n[q]\"Ein mächtiger Funke, der vom Traum beeinflusst wurde. Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\"\nVerkaufspreis:"}
