MultiLanguageItemData['de'][206976] = {name = "[q3]Zügel des Königlichen Schwärmers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Drohnen umschwärmen jeden, der es wagt, sich ihrer Königin ungefragt zu nähern.\"\nHandelsposten"}
MultiLanguageItemData['de'][206977] = {name = "[q4]Traumwappen des verzauberten Welpen", additional_info = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n[q2]+160 Rezeptschwierigkeit\n[q]Benutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n[q]\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][206978] = {name = "[q3]Somnius", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:"}
MultiLanguageItemData['de'][206979] = {name = "[q3]Posidriss", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ruft Posidriss herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n[q2]Ruft Posidriss herbei, damit Ihr gemeinsame Abenteuer erleben könnt.\n80 ( 80)\nVerkaufspreis:"}
MultiLanguageItemData['de'][206983] = {name = "[q4]Parakausales Fragment von Frostgram", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Beim Tod von Spielercharakteren oder Gegnern in der Nähe erhaltet Ihr eine verlorene Seele, bis zu maximal 10. Beim Verschlingen verlorener Seelen\n[q2]Benutzen: Gebt Euch der Verderbnis der Geißel hin, verschlingt alle verlorenen Seelen\n\n Dieser Effekt kann sich je nach Spezialisierung unterscheiden. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][206984] = {name = "Blutgetränktes Buch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Das Blut ist längst getrocknet. Seltsamerweise scheint der Text in diesem Buch erst geschrieben worden zu sein, nachdem das Blut schon trocken war.\""}
MultiLanguageItemData['de'][206993] = {name = "[q3]Taschenuhr des Investi-gators", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Dreht die Zeiger der Uhr.\n[q]\"Sand wird freigesetzt, wenn sich der zweite Zeiger bewegt.\""}
MultiLanguageItemData['de'][206996] = {name = "Ein Hinweis", additional_info = "Geheimnisse von Azeroth\nEinzigartig\nDauer: 22 std."}
MultiLanguageItemData['de'][206997] = {name = "[q3]Vergoldete Sonnenbrille", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nKopf Kosmetisch\n[q]\"Die Zukunft ist so strahlend, dass ich eine Sonnenbrille brauche.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][206998] = {name = "Bernschwert", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Die Klinge ist mit Macken, Dellen und Kratzern übersät. Sie hat offensichtlich schon viele Kämpfe erlebt... allerdings bleibt unklar, gegen wen.\""}
MultiLanguageItemData['de'][207002] = {name = "[q3]Eingeschlossenes Schicksal", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Garantiert, dass der nächste Zeitriss, den Ihr abschließt, Euch eine Belohnung gewährt.\n[q]\"Ein Fragment der Möglichkeit, das durch den Kollaps der Zeitwege greifbar gemacht wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][207003] = {name = "Vergoldete Vase", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Eine große goldene Vase. Sie ist leer, und ein kurzer Blick ins Innere offenbart eine schwarze, schmutzähnliche Substanz. Ein seltsamer Fund auf dem Gipfel von Eiskrone.\""}
MultiLanguageItemData['de'][207004] = {name = "Foliant des Beschwörers", additional_info = "Questgegenstand\n[q2]Benutzen: Läutert teufelsberührte Satyrleichen innerhalb von 15 Metern und bannt verderbende Energien.\n[q]\"Wenn Ihr Eure Hand auf den Folianten legt, könnt Ihr ein leichtes Summen vernehmen. In diesen Seiten steckt gewaltige Macht.\""}
MultiLanguageItemData['de'][207005] = {name = "[q4]Parakausales Fragment von Donnerflosse, Feuchtklinge des Gezeitensuchers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure offensiven Zauber und Fähigkeiten haben eine Chance, an der Position Eures aktuellen Ziels einen Wirbelsturm zu beschwören. Der Wirbelsturm folgt dem ursprünglichen Ziel und verursacht im Verlauf von 10 Sek. ( 2629 * 10) Naturschaden, der auf alle getroffenen Gegner aufgeteilt wird.\n\n Während sie sich im Wirbelsturm befinden, werden Gegner zu elektrischen Leitern. Erleidet ein elektrischer Leiter Schaden, besteht eine hohe Chance, einen Gabelblitz auszulösen, der 7620 Naturschaden verursacht, der zwischen dem Ziel und bis zu 4 weiteren Zielen in der Nähe aufgeteilt wird. (10s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][207008] = {name = "Ein Fisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Nur ein großer Fisch. Doch verglichen mit anderen Fischen, sieht der hier wie ein guter Fisch aus.\""}
MultiLanguageItemData['de'][207011] = {name = "[q4]Kriegsklingen der Hakkari, wiedergeboren", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q]\"Legenden zufolge können diese Klingen nur am Rande des Wahnsinns von einer Seele geschmiedet werden, deren Zorn noch heißer schwelt als die sengenden Flammen des Hasses.\""}
