MultiLanguageItemData['de'][207161] = {name = "[q4]Mantel der lodernden Opfergabe", additional_info = "Wird beim Aufheben gebunden\nRücken\n353 Rüstung\n+337 [Beweglichkeit oder Stärke oder Intelligenz]\n+1.197 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 139.\n[q2]Erhöht Eure Meisterschaftswertung um + 347.\n[q]\"Ein weiterer Feuerlord wurde von den Flammen seines Ehrgeizes verschlungen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][207162] = {name = "[q4]Signet des letzten Ältesten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+1.197 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 288.\n[q2]+ 1.514 Vielseitigkeit\n[q]\"Igira führte die Djaradin nur in den Untergang, nachdem sie die Flammen ihres Hasses endlos geschürt hatte.\"\nVerkaufspreis:"}
