MultiLanguageItemData['de'][208577] = {name = "[q5]Symbiotischer Leuchtsporengriff", additional_info = "Wird beim Aufheben gebunden\n\"Dieser anpassungsfähige Griff ist in der Lage, enormen Mengen fluktuierender Schattenflamme zu widerstehen. In Zusammenarbeit mit Lederverarbeitungsmeister Erden gefertigt.\""}
