MultiLanguageItemData['de'][208683] = {name = "[q3]Ritualkolben von Arinor", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Streitkolben}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n[q]\"Keine der Ritualisten unter den Arinorlandwarten haben überlebt, doch ihre Werkzeuge sind geblieben.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208684] = {name = "[q3]Kummer des Anachoreten", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Dolch}\n2 - 5 Schaden Geschwindigkeit 3.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\n[q]\"Ein Anachoret, der dazu gezwungen ist, sich auf seine Klinge zu verlassen, hat bereits mindestens einmal versagt.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208685] = {name = "[q3]Geborgene Kaarinosklinge", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n[q]\"Es sind nur noch wenige Relikte der verlorenen Gipfel von Kaarinos vorhanden, doch denen, die sich noch an sie erinnern können, sind sie dafür umso bedeutender.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208686] = {name = "[q3]Velenitclaymore", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Zweihändig} {Schwert}\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n[q]\"Einst von jenen Eredar geführt, die Velen ihre Treue geschworen haben, bevor die Dunkelheit über Argus kam.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208688] = {name = "[q3]Telaastispitzhacke", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Axt}\n1 - 4 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\nHaltbarkeit 50 / 50\n[q]\"Nur wenige erinnern sich an die reichen Minen der Weiten von Telaasti, die vor Jahrtausenden durch den Bau von Antorus verschlungen wurden.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
