MultiLanguageItemData['de'][208691] = {name = "[q2]Argunitformation", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Geschenk von Arzaals Verbündeten, die noch auf Argus verweilen. Enthält Verschleierten Argunit und andere Materialien.\"\n[q2]<Zum Öffnen rechtsklicken>"}
