MultiLanguageItemData['de'][208878] = {name = "[q2]Schließkiste des Abenteurers", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält Ausrüstung für andere Klassenspezialisierungen.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][208879] = {name = "[q3]Ensemble: Zier des Kaldoreibeschützers", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen der Zier des Kaldoreibeschützers. Dieses Set kann nur von Charakteren der Nachtelfen getragen werden.\n[q]\"Für jene Nachtelfen, die im Dienst für den Wald, den Mond und das Volk der Kaldorei große Leistungen vollbringen.\""}
MultiLanguageItemData['de'][208881] = {name = "Schauderschnappblüte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (3)\n[q]\"Eine andersweltliche Blume, die eine geisterhafte Kälte verströmt.\""}
MultiLanguageItemData['de'][208882] = {name = "[q3]Wickel des Kaldoreibeschützers", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nBeine Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208883] = {name = "[q3]Sandkastensturmgreif", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Hüpft auf diesen federnden Spielzeuggreifen oder hebt Eure Waffe und ruft den Donner herbei, um einen übermütigen Ritt zu erleben. (3 Min Abklingzeit)\n[q]\"Warnung: Sicherheitsgeschirr nicht im Lieferumfang enthalten.\""}
MultiLanguageItemData['de'][208884] = {name = "Wurzelwiederherstellungsfrucht", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht der traumgewachsenen Heilfrucht die Essenz und versucht, Gracus zu heilen.\n[q]\"Eine aus dem Traum gewachsene Frucht, die von Heilungsmagie erfüllt ist und auf Wesen der Natur die größte Wirkung hat.\""}
MultiLanguageItemData['de'][208885] = {name = "[q3]Gelenkbänder des Kaldoreibeschützers", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\nHandgelenk Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208886] = {name = "Feurige Essenz", additional_info = "Questgegenstand\n[q]\"Ein zähflüssiger Klumpen, der Hitze ausstrahlt. Wie ein schleimiges Lagerfeuer.\""}
MultiLanguageItemData['de'][208887] = {name = "Erdens Notizen", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Hastig geschriebene Notizen zu verschiedenen Reagenzien, die für einen symbiotischen Leuchtsporengriff erforderlich sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][208888] = {name = "Notiz eines Kontakts der Kirin Tor", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q]\"Bobby Carlisle gab Euch diese Notiz, um Euch dabei zu helfen, in Karazhan ein Buch zu finden, das Informationen zu den Tafeln und ihren Inhalten enthalten sollte.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][208889] = {name = "Tyrs Vermächtnis", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Eine komplette, auf Drakonisch geschriebene Geschichte von Tyrs Vermächtnis und den Artefakten, die in Uldorus aufbewahrt werden.\""}
