MultiLanguageItemData['de'][208927] = {name = "Sandschimmerperle", additional_info = "Questgegenstand\n[q]\"Für ihre außergewöhnliche Schönheit berüchtigt.\""}
MultiLanguageItemData['de'][208928] = {name = "Zaqaliverzierungen", additional_info = "Questgegenstand\n[q]\"Dies scheint ein fast unbeschädigter Stein mit einer kleinen Verzierung zu sein.\""}
MultiLanguageItemData['de'][208929] = {name = "Tolle Sehenswürdigkeiten in Valdrakken", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q]\"Einige interessante Orte, die man aus völlig normalen Gründen besuchen sollte. - Klaudia Huhu\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][208930] = {name = "Samtige Peitscherblätter", additional_info = "Questgegenstand\n[q]\"Weich und zart, perfekt für ein Schlaflager.\""}
MultiLanguageItemData['de'][208931] = {name = "Seidiger Salbei", additional_info = "Questgegenstand\n[q]\"Dick und weich, sehr gemütlich.\""}
MultiLanguageItemData['de'][208932] = {name = "[q3]Ein Teil des vierten Hinweises", additional_info = "Geheimnisse von Azeroth\n[q]\"Ein Teil eines Hinweises, um Mimirons erstes Stück zu finden.\"\n[q2]<Zum Lesen rechtsklicken>"}
