MultiLanguageItemData['de'][208936] = {name = "Gesammelter Bericht", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Finalisierte Ergebnisse für Klaudia Huhu.\""}
MultiLanguageItemData['de'][208937] = {name = "Ein schlammiges Tagebuch", additional_info = "[q]\"Ihr habt dieses Tagebuch im Gras gefunden, und seine Seiten sind voller Matsch. Die letzten Seiten sind ein Fenster in eine gebrochene Seele.\"\n[q2]<Zum Lesen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][208938] = {name = "Metamorpher Ruß", additional_info = "Questgegenstand\n[q]\"Die beständige Glut in dieser Asche scheint ihre Form zu verändern, während Ihr sie beobachtet.\""}
MultiLanguageItemData['de'][208939] = {name = "[q4]Gorridar, Dunkelklinge des Zerreißers", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Schwert}\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n[q]\"Bösartigkeit und Hass, verbunden zu einer Klinge, die ganze Welten verwüsten kann. Hütet Euch vor jenen, die eine solche Klinge neidvoll betrachten.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208940] = {name = "[q4]Leerengesang, Stab des Herolds", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Zweihändig} {Stab}\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n[q]\"Ein Geschenk von Dimensius, verliehen zur Blütezeit des Schwarzen Imperiums. Vom Schatten berührte werden von seinem quälenden Flüstern angezogen.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208941] = {name = "[q4]M'thorus, Dolch des Großen Entwurfs", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Dolch}\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n[q]\"Den Schatten darf nicht gestattet werden, zu schwären. Chaos muss niedergerungen werden, wo es sich einnistet. Wahre Kinder der Titanen werden dem Ruf ihrer Erschaffer folgen.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208942] = {name = "Bewahrerbefehle Drei", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q]\"Ein Notizzettel, der ein Kugelartefakt beschreibt, das die Bewahrer gerettet wissen wollen.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][208943] = {name = "[q4]Arsenal: Kosmische Waffentruhe", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Sammelt die in der kosmischen Waffentruhe des Arsenals enthaltenen Erscheinungen ein.\n[q]\"Aus dem uralten Gewebe des Kosmos geschmiedete Waffen. Wer diese Sammlung zusammengestellt hat, bleibt ebenso rätselhaft wie die Gründe dafür. Wer sie führt, zieht die Augen jener auf sich, die solche Macht suchen.\""}
MultiLanguageItemData['de'][208944] = {name = "Kugel von Rathmus", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Titanenschrift ziert die Metallbänder, die die glühende Kugel umgeben.\""}
MultiLanguageItemData['de'][208945] = {name = "[q7]Parakausale Kiste", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Öffnet die Kiste, um 500 parakausale Flocken zu erhalten.\n[q]\"Für das Wohlergehen der Zeitlinie wird leider empfohlen, die Kiste erst zu öffnen, nachdem sie versendet wurde.\""}
MultiLanguageItemData['de'][208946] = {name = "Brennende Rune", additional_info = "Questgegenstand\n[q]\"Eine mysteriöse Gravur, die unangenehme Hitze ausstrahlt.\""}
MultiLanguageItemData['de'][208947] = {name = "Verzauberte Gießkanne", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Spritzt Wasser auf verzauberte Sträucher und verleiht ihnen damit Energie, um sich Magnolia Eich zuzuwenden.\n[q]\"Mächtiger als die durchschnittliche Gießkanne.\""}
MultiLanguageItemData['de'][208949] = {name = "Aufgeheizter Ruhestein", additional_info = "Questgegenstand\n[q]\"Warm und einladend, großartig zum Aufwärmen der Hände.\""}
MultiLanguageItemData['de'][208950] = {name = "Smaragdfaser", additional_info = "Questgegenstand\n[q]\"Eine robuste Faser, die erstaunlich zugfest ist.\""}
MultiLanguageItemData['de'][208951] = {name = "[q7]Parakausaler Verbund", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Zerschmettert dies, um 1000 parakausale Flocken zu erhalten.\n[q]\"Eine Kristallformation, die sich kurz vor der Kollision zweier Zeitwege bildet und aus verdichteten Sanden der Zeit besteht.\""}
MultiLanguageItemData['de'][208952] = {name = "[q7]Soridormis Empfehlungsschreiben", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Lest dies, um 1000 Ruf bei Soridormi zu erhalten.\n[q]\"Ein Empfehlungsschreiben unterzeichnet von Soridormi.\""}
