MultiLanguageItemData['de'][208957] = {name = "Leitung des Südlichen Sturms", additional_info = "Questgegenstand\n80 ( 80)\n[q]\"Der uralte Obelisk scheint aus einem Stück elektrisch geladenem Glas oder Kristall gehauen zu sein.\""}
MultiLanguageItemData['de'][208958] = {name = "Notizen zum uralten Tyrholdartefakt", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q]\"Enthält Notizen von Kathos und Bobby zu den Sicherheitsvorkehrungen des Artefakts bei Tyrhold.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][208959] = {name = "[q4]Taesavir, Schwert des Großen Entwurfs", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Schwert}\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n[q]\"Eine Klinge, so scharf, dass sie nur von Aggramar selbst geschliffen werden kann. Jene, die sich dem Willen der Titanen widersetzen, sollten sich vor ihrem Träger hüten.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][208960] = {name = "[q3]Titanischer Fokussierkristall", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q]\"Dies ist eindeutig eins der Objekte, die zertrümmert wurden und für den zweiten Satz an Artefaktschlössern benötigt werden.\""}
MultiLanguageItemData['de'][208962] = {name = "[q4]Siederas, Breitschwert des Zerreißers", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Zweihändig} {Schwert}\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nDieser Gegenstand kann nicht direkt gekauft werden. Schaut im Reisetagebuch nach, wenn Ihr wissen möchtet, wie Ihr die kosmische Waffentruhe erhaltet.\n[q]\"Aus böswilligem Chaos geschmiedet, um das Herz des Ziels zu treffen. Jene, deren Seelen mit alles verzehrender Wut brennen, werden von seinem dunklen Feuer angezogen.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
