MultiLanguageItemData['de'][209996] = {name = "Haltespulenrune", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Belegt Euch selbst mit 'Haltespulenentzug', indem Ihr Euch an eine beliebige seltene Kreatur im Smaragdgrünen Traum bindet.\n\n Seltene Kreaturen zu besiegen, während 'Haltespulenentzug' aktiv ist, gewährt 'Straffe Haltespule'. (5 Sek. Abklingzeit)\n[q]\"Lydiaras Rune, mit der von mächtigen Kreaturen im Smaragdgrünen Traum straffe Haltespulen gewonnen werden können.\""}
MultiLanguageItemData['de'][209997] = {name = "[q3]Destilliertes Wissen der Zeitwege", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig (5)\n[q2]Benutzen: Erhöht die durch das Töten von Monstern und das Abschließen von Quests erhaltene Erfahrung um 5%.\n\n Der Abschluss eines Zeitwanderungsdungeons verstärkt den Effekt und setzt die Dauer zurück.\n\n Beim Erreichen von 4 Anwendung(en), erfolgt eine Umwandlung zu ' Meister der Zeitwege ', was den Effekt auf 30% erhöht."}
MultiLanguageItemData['de'][209998] = {name = "[q4]Lydiaras Bindungsrune", additional_info = "Wird beim Aufheben gebunden\n[q]\"In Zusammenarbeit mit Lydiara Flüsterfeder gefertigt.\""}
MultiLanguageItemData['de'][209999] = {name = "Lydiaras Rune der Schattenbindung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bindet Euch an Knorrenwurzel, Igira oder Volcoross, um schattengebunden zu werden.\n\n Während der 'Schattenbund' besteht, seid Ihr mit 'Lodernde Schattenflamme' belegt, was Euch abhängig von Eurer Entfernung zum Ziel um 0-50% verlangsamt und wodurch alle 5 Sek. die Chance besteht, Eure Mobilität einzuschränken. (5 Sek. Abklingzeit)\n[q]\"Eine Rune der Schattenbindung, die auf Fyr'alath eingestimmt werden kann.\""}
MultiLanguageItemData['de'][210001] = {name = "[q4]Ordungspergamentprototyp", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Pergamentprototyp, das Shalasar aus leuchtenden Ascheflocken hergestellt hat.\""}
MultiLanguageItemData['de'][210002] = {name = "Aschene Wünschelrute", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht Waffen oder Rüstungen von mächtiger (EPISCH) Qualität leuchtende Ascheflocken. Der anvisierte Gegenstand wird ZERSTÖRT und kann nicht zurückgeholt werden. (5 Min Abklingzeit)\n[q]\"Eine Wünschelrute, die dem Benutzer die Fähigkeit verleiht, mächtige Ausrüstungsgegenstände zu entzaubern, um leuchtende Ascheflocken zu erhalten.\""}
