MultiLanguageItemData['de'][210008] = {name = "[q4]Schwelende Rune der Bindung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Möge das Feuer die Hindernisse auf Eurem Weg tilgen!\"\nPromotion:\nCataclysm Classic"}
MultiLanguageItemData['de'][210009] = {name = "[q4]Traumlaubgriffprototyp", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein Runenprototyp, den Erden aus ledrigem Schattentraumlaub gefertigt hat.\""}
MultiLanguageItemData['de'][210010] = {name = "Erdens Notizen zu symbiotischen Sporen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Teile Erdens Notizen mit einem verbündeten Lederverarbeiter und bringe ihm vorübergehend bei, wie man Erdens Traumlaubgriff herstellt. Der Lederverarbeiter muss sich in der gleichen Gruppe befinden. (30 Min Abklingzeit)\n\"Notizen zu den Anforderungen für die Herstellung eines experimentellen symbiotischen Leuchtsporengriffs. Geschrieben von Lederverarbeitungsmeister Erden.\""}
MultiLanguageItemData['de'][210011] = {name = "Shalasars Notizen zu weiser Magie", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Teile Shalasars Notizen mit einem verbündeten Verzauberer und bringe ihm vorübergehend bei, wie man Shalasars weises Pergament herstellt. Der Verzauberer muss sich in der gleichen Gruppe befinden. (30 Min Abklingzeit)\n[q]\"Notizen zu den Anforderungen für die Herstellung eines experimentellen weisen Pergaments. Geschrieben von Meisterverzauberin Shalasar Glimmerstaub.\""}
MultiLanguageItemData['de'][210012] = {name = "Erdens symbiotischer Leuchtsporengriff", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Versucht, den symbiotischen Leuchtsporengriff an Fyr'alath zu binden, wobei Ihr 10 Sek. lang pro Sekunde Schattenflammenschaden in Höhe von 10-25% Eurer maximalen Gesundheit erleidet. (30 Sek. Abklingzeit)\n[q]\"Ein ungetesteter Leuchtsporengriff\""}
MultiLanguageItemData['de'][210014] = {name = "[q3]Geheimnisvolle zeitlose Samen", additional_info = "Questgegenstand\nEinzigartig (20)\n[q2]Benutzen: Pflanzt einen Samen der passenden Größe in einem Bereich mit Traumsaaterde in der Nähe.\n[q]\"Traumsaat, die darauf wartet, erweckt zu werden.\""}
MultiLanguageItemData['de'][210016] = {name = "Schleier der Schlummereule", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Geht in Verstohlenheit über. Der Beginn eines Kampfs und der Einsatz von Fähigkeiten beenden den Effekt. Gegner entdecken Euch, wenn Ihr Euch zu sehr nähert. (8 Sek. Abklingzeit)\n[q]\"Ruft Schlummereule Bodwin an, damit er Euch eine vorübergehende Verstohlenheitsaura verleiht.\""}
