MultiLanguageItemData['de'][210184] = {name = "[q4]Halbvoller Trank des traumlosen Schlafs", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)\n[q]\"Hier ist es wesentlich einfacher, es einfach \"Wasser\" zu nennen.\""}
MultiLanguageItemData['de'][210185] = {name = "[q4]Spritztrank der Narkolepsie", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)\n[q]\"Das Ziel ist ja offensichtlich, Gegner einschlafen zu lassen, daher erscheint es kontraproduktiv, sie dabei zu bespritzen.\""}
MultiLanguageItemData['de'][210189] = {name = "Exarch Hataarus Handwerkslinse", additional_info = "Questgegenstand\n[q]\"Eine kleine, goldene Linse, getrübt von Alter und Nutzung. Die präzise geschliffenen Facetten erlauben Konstrukteuren, die Energiekanäle zu sehen, die durch die Kristalle strömen, mit denen sie arbeiten.\""}
MultiLanguageItemData['de'][210190] = {name = "[q4]Brandwurzel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigtAlchemie der Dracheninseln\n(25)\n[q]\"Qualmt in Eurer Hand. Es wäre ein fantastischer Katalysator für Eure Gebräue, aber viel Glück dabei, Kräuterkundige davon zu überzeugen, die Hand dafür ins Feuer zu legen.\""}
MultiLanguageItemData['de'][210193] = {name = "[q4]Experimenteller Traumfänger", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Einen Magneten in den Smaragdgrünen Traum zu bringen, macht diesen nicht direkt zu einem Traumfänger, aber irgendjemand musste es versuchen.\""}
MultiLanguageItemData['de'][210194] = {name = "[q4]Schlaflositron", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Ein sorgfältig kalibriertes Gerät, das ein hohes Geräusch erzeugt, das nur schlafende Druiden hören können.\""}
MultiLanguageItemData['de'][210197] = {name = "[q4]Ungeschlüpfte Batterie", additional_info = "Wird beim Aufheben gebunden\nDauer: 3 tagen\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n[q]\"Dies wurde anscheinend für ein verlegtes Ei gehalten, doch kann man sich durchaus fragen, was geschlüpft wäre, wenn die Brut nicht unterbrochen worden wäre.\""}
