MultiLanguageItemData['de'][210769] = {name = "[q4]Zügel der Springfluttraumkralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n[q]\"Versprüht die Art Enthusiasmus und Energie, die jeden neidisch machen würde.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1"}
MultiLanguageItemData['de'][210770] = {name = "[q3]Beutel mit Traumwappen des Drachen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt 15 Traumwappen des Drachen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können."}
MultiLanguageItemData['de'][210774] = {name = "[q4]Zügel der ockerfarbenen Traumkralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Verspielte Traumkrallen verzieren sich oft selbst mit einer Fülle an Farben, wie sie nur die Herbstzeit zu bieten hat.\"\nQuest:\nEin bisschen Hoffnung ist immer gut\nZone:\nSmaragdgrüner Traum"}
MultiLanguageItemData['de'][210775] = {name = "[q4]Zügel der schneeweichen Traumkralle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n[q]\"Unbeschwert und sanft wie Schnee können sie von einer Schneewehe zur nächsten hüpfen, ohne dabei Spuren zu hinterlassen.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1"}
