MultiLanguageItemData['de'][210777] = {name = "[q3]Schlafi", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nIhr müsst eine Felsschnecke als Haustier in Eurer Sammlung haben, um eine neue mit Traumenergie zu erfüllen."}
MultiLanguageItemData['de'][210778] = {name = "Windtotem des Archivars", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Beschwört ein Windtotem an Eure Position, um die Ausgrabung zu unterstützen. (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][210780] = {name = "[q4]Geringe Glut von Fyr'alath", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Empfangt die Glut und erhöht dadurch dauerhaft Eure Chance, Fyr'alath, den Traumreißer, zu erhalten.\n[q]\"Die Hymne des Traumreißers ruft Euch aus dem Inneren.\""}
MultiLanguageItemData['de'][210782] = {name = "[q2]Schlummernder Mondfisch", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft den Mondfisch in die Gewässer von Amirdrassil zurück. Verleiht einen Stapel Mondfischessenz.\n[q]\"Dieser geisterhafte Fisch kommt nur in den Wassern von Amirdrassil vor. Der Fisch wird von Eurer Einstimmung auf den Smaragdgrünen Traum angezogen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][210783] = {name = "[q2]Erwachender Sonnenfisch", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft den Sonnenfisch in die Gewässer von Amirdrassil zurück. Verleiht einen Stapel Sonnenfischessenz.\n[q]\"Dieser verspielte Fisch kann in glühend heißen Temperaturen überleben und ist nur in Amirdrassil anzutreffen. Er scheint von der inneren Verbindung zwischen Euch und dem Weltenbaum angezogen zu werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][210784] = {name = "[q3]Xena, der wunderliche Schnurrwels", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Werft Xena zurück in die Gewässer von Amirdrassil.\n[q]\"Xenas prismatische Schuppen reflektieren jegliche Form von Licht mit einem Leuchten, das nur als wunderlich bezeichnet werden kann.\"\nVerkaufspreis:"}
