MultiLanguageItemData['de'][210926] = {name = "Paket mit Schokolade nur für mich, mich, mich", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 15 Sek. ( 630000 / 5 * 15) Gesundheit wieder her. Wenn Ihr mindestens 15 Sek. mit Essen verbringt, spürt Ihr die Liebe und für 2 Stunden wird Eure Moral gestärkt.\nBenötigtLiebe liegt in der Luft\n[q]\"Eine Liebeserklärung an überzeugte Schokonascher.\""}
