MultiLanguageItemData['de'][210939] = {name = "[q3]Nullstein", additional_info = "Handwerksmaterial\n\"Wird manchmal von Spielercharakteren gesammelt, die den Beruf Bergbau ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][210944] = {name = "[q4]Smaragdmal der Meisterschaft", additional_info = "Saison 3 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig\n[q]\"Wird für außerordentliche Dienste an die Drachenspezies verliehen. Bringt es Theozhaklos dem Neugierigen am Urquellausguck im Smaragdgrünen Traum, um mächtige Ausrüstung für Eure Mühen zu erhalten.\""}
MultiLanguageItemData['de'][210945] = {name = "[q4]Sternstreifer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst einen Traumhirsch als Reittier in Eurer Sammlung haben, um einen neuen mit Traumenergie zu erfüllen.\n\n\n[q]\"Wie es sich wohl anfühlt, die Sterne aus ihrer Verankerung am Himmel reißen zu können? Vielleicht wird Sternstreifer uns eines Tages zeigen, wie das geht.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1"}
MultiLanguageItemData['de'][210946] = {name = "[q4]Mammyth", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst ein Magmammut als Reittier in Eurer Sammlung haben, um ein neues mit Traumenergie zu erfüllen.\n\n\n[q]\"Im Traum ist der Mythos manchmal realer als seine Grundlage.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1"}
MultiLanguageItemData['de'][210947] = {name = "[q4]Flammenverzerrte Kuriosität", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine Erinnerung an die feurige Zukunft, die Fyrakk vorschwebte. Kirasztia am Urquellausguck im Smaragdgrünen Traum weiß vielleicht, wie man die Geheimnisse darin freisetzt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][210948] = {name = "[q4]Gedankenschwinge", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst eine Schieferschwinge als Reittier in Eurer Sammlung haben, um eine neue mit Traumenergie zu erfüllen.\n\n\n[q]\"Es gibt nichts Schöneres, als seine Gedanken fliegen zu lassen.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1"}
