MultiLanguageItemData['de'][212227] = {name = "[q4]Zügel des ausgefuchsten Freundchens", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört das ausgefuchste Freundchen als Reittier und gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese magischen Kreaturen gedeihen durch Liebe und Freundschaft.\"\nHandelsposten"}
MultiLanguageItemData['de'][212228] = {name = "[q4]Zügel des gleitenden Himmelsfuchses", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört den gleitenden Himmelsfuchs als Reittier und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Steigt mit dem treusten und liebevollsten Fuchs in ganz Azeroth in die Lüfte.\"\nWoW-Shop"}
MultiLanguageItemData['de'][212229] = {name = "[q4]Zügel des Zwielichthimmelsstreuners", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört den Zwielichthimmelsstreuner als Reittier und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Er wird von einigen auch als Mitternachtstrickser bezeichnet und viele Paare glauben, dass er dafür verantwortlich ist, dass sich ihre Wege in der Nacht gekreuzt haben.\""}
MultiLanguageItemData['de'][212289] = {name = "Boshaftes Fläschchen der klassischen Geister", additional_info = "[q2]Benutzen: Trinkt dies, um Eure Manaregeneration um 8% zu erhöhen, wenn Ihr 5 Sek. lang keinen hilfreichen Zauber gewirkt habt, der Mana kostet.\n\n Erhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:"}
MultiLanguageItemData['de'][212292] = {name = "Boshaftes Fläschchen der Ehre", additional_info = "[q2]Benutzen: Trinkt dies, um Eure erhaltene Ehre um 15% zu erhöhen. Kann in allen gewerteten und ungewerteten PvP-Umgebungen eingesetzt werden.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:"}
MultiLanguageItemData['de'][212295] = {name = "Boshaftes Fläschchen des manifestierten Jähzorns", additional_info = "[q2]Benutzen: Bei Eurem Tod manifestiert sich Eure Wut als rasender Elementar, durch den Ihr Euch 10 Sek. lang an Euren Feinden rächen könnt. Kann nur einmal alle 2 Min. auftreten.\n\n Erhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:"}
MultiLanguageItemData['de'][212298] = {name = "Boshaftes Fläschchen der Abrisskugel", additional_info = "[q2]Benutzen: Todesstöße von Spielercharakteren erhöhen 20 Sek. lang Euren verursachten Schaden um 8% und Euren erlittenen Schaden um 4%. Bis zu 5-mal stapelbar. Wenn Ihr getötet werdet, während dieser Effekt aktiv ist, erhält Euer Angreifer einen Teil dieser Macht.\n\n Erhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:"}
