MultiLanguageItemData['de'][212449] = {name = "[q4]Sik'rans endloses Arsenal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Nimmt eine Kampfhaltung basierend auf der zuletzt gezückten Waffe ein.\n[q2]Benutzen: Surekisches Gedeihen \nBeschwört zwei Schwerter aus dem Arsenal, um Euer Ziel wild anzugreifen und im Verlauf von 3 Sek. ( 1 * 705278 ) Schattenschaden zuzufügen. Gewährt 338 Parieren und 225 Vermeidung, bis die nächste Waffe gezogen wird. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][212450] = {name = "[q4]Autorität des Schwarmfürsten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 1.001.\n[q2]Anlegen: Eure Angriffe und Fähigkeiten haben eine hohe Chance, einen Skarabäus zu beschwören, der ein stärkendes Fleischstück aus Eurem Ziel reißt. Skarabäen verursachen 6915 körperlicher Schaden und verringern Euren erlittenen Schaden um 50% bis 172816 Schaden verhindert wurde.\n[q2]Benutzen: Bringt Euren Schwarm zur Raserei und beschwört im Verlauf von 3 Sek. 12 Skarabäen, die Eure Gegner heimsuchen. Die Anzahl der Skarabäen wird durch Euer Tempo erhöht. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][212451] = {name = "[q4]Anomale Zauberschmiede", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Intelligenz\n[q2]Anlegen: Sammelt alle 15 Sek. dunkle Macht von der Zauberschmiede, um Euren nächsten Einsatz von [Eurem Spezialisierungszauber] zu ermächtigen, damit er zusätzlich ( 1 * 73672 ) Schattenschaden verursacht.\n{[q2]Benutzen: Verstärkt die Macht der Zauberschmiede ohne Rücksicht auf Verluste und multipliziert bis zu 5-mal ihren aktuellen Schaden} bis kurz nach Verlassen des Kampfes um 125%. Bei maximaler Macht erhaltet Ihr 6 Sek. lang 830 {Tempo, wenn Ihr Euren nächsten Einsatz von [Eurem Spezialisierungszauber] ermächtigt.\n\n Hütet Euch vor flüchtigen Blicken ins Ungehörige. (1 Min Abklingzeit)}\nVerkaufspreis:"}
MultiLanguageItemData['de'][212452] = {name = "[q4]Grausame Spritze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.001.\n[q2]Anlegen: Bei Euren Heilzaubern besteht eine hohe Chance, dass Ihr Euch eine Aufladung ' Instabiles Serum ' injiziert. Mehrere Aufladungen können sich überschneiden.\n\n Wenn ein Verbündeter unter 70% Gesundheit fällt, stoßt Ihr eine Aufladung aus und heilt ihn um 240979 Gesundheit. Aufladungen, die nach 15 Sek. noch nicht verbraucht wurden, werden katalysiert und gewähren Euch stattdessen 10 Sek. lang 2894 Intelligenz.\nVerkaufspreis:"}
MultiLanguageItemData['de'][212453] = {name = "[q4]Ätzendes Himmelsschreckenorgan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Stärke\n[q2]Benutzen: Bespritzt Euer Ziel mit instabiler Säure, die 20 Sek. lang alle 1 Sek. ( 1 * 7902 ) Naturschaden verursacht.\n\n Eure Fähigkeiten verstärken den Schaden der Säure für die verbleibende Dauer pro Sekunde um ( 1 * 7902 ) zusätzlichen Naturschaden, bespritzen bis zu 5 Gegner in der Nähe und fügen ihnen pro Stapel ( 1 * 790 ) Naturschaden zu. (1s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][212454] = {name = "[q4]Mandat der verrückten Königin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.001.\n[q2]Benutzen: Nehmt, was rechtmäßig Euch gehört und labt Euch an der Essenz Eures Ziels, um ( 1 * 2174283 ) Schattenschaden zu verursachen und Euch im Verlauf von 2 Sek. um 320973 zu heilen. Schaden und Heilung erhöhen sich gemäß der fehlenden Gesundheit des Ziels.\n\n Wenn der Effekt das Ziel tötet, wird die Abklingzeit um 60 Sek. reduziert. (2 Min Abklingzeit)\nVerkaufspreis:"}
