MultiLanguageItemData['de'][212756] = {name = "[q3]Unerbittlicher Schwinger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Wenn Eure Gesundheit unter 75% fällt, wird für bis zu 15 Sek. die Verteidigungsmatrix aktiviert und absorbiert 50% des erlittenen Schadens, bis zu maximal 16069 Schaden. Während die Matrix aktiv ist, pulsiert der Schwinger alle 1 Sek., um allen Gegnern in der Nähe 177 Feuerschaden zuzufügen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n Dies kann nur alle 1.5 Min. auftreten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][212757] = {name = "[q3]Granyths robuste Schuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Verringert den erlittenen Schaden 20 Sek. lang um 75% oder bis 22723 Schaden absorbiert wurden. Bei aktivem Schild ist Eure Rüstung um 179 erhöht und wird um weitere 9 erhöht, wenn Ihr einen Treffer erleidet. Bis zu 20-mal stapelbar. Der Schild explodiert, wenn er durchbrochen wird, und verursacht dabei 4970 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird.\n\n Der Schaden erhöht sich für jeden getroffenen Gegner, bis zu einem Maximum von 5 Gegnern. (100ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][212758] = {name = "[q2]Entflammender Schrecken", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, zusätzlichen Feuerschaden zu verursachen und Euren Gegner 3 Sek. lang mit Entsetzen zu erfüllen.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][212759] = {name = "[q2]Meteoritensturm", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, einen Meteoritenhagel zu beschwören, der Gegnern in der Nähe Feuerschaden zufügt und sie für 3 Sek. betäubt.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][212760] = {name = "[q2]Lauffeuer", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Angriffe haben eine Chance, Feuerschaden zu verursachen und 'Lauffeuer' auf einen Gegner in der Nähe überspringen zu lassen, das 10 Sek. lang alle 1 Sek. Feuerschaden verursacht.\n\n 'Lauffeuer' ist bis zu 3-mal stapelbar und springt auf Gegner in der Nähe über.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][212761] = {name = "[q0]Beutel voller Münzen", additional_info = "[q]\"Jemand muss diesen vor langer, langer Zeit zur sicheren Verwahrung versteckt haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][212762] = {name = "[q2]Beflecktes Hornsignet", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Die Dracthyr scheinen sich die Idee für Hornschmuck von den vor ihnen hier lebenden Drachkin abgeschaut zu haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][212763] = {name = "[q0]Verdorbener Honigwein", additional_info = "[q]\"Die Flüssigkeit in dieser Flasche ist milchig und glanzlos. Sie sollte wohl besser nicht mehr getrunken werden, könnte aber dennoch noch wertvolle Einblicke geben.\"\nVerkaufspreis:"}
