MultiLanguageItemData['de'][212977] = {name = "[q2]Drakonidische Schildplakette", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Die Wörter selbst gingen über die Jahre verloren, aber die bloße Existenz eines Schilds setzt ein Schriftsystem und Zivilisation voraus, die vor zahllosen Generationen bestand.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][212978] = {name = "[q2]Drachenmalerpalette", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Jeder kann Farben auf eine Leinwand schmieren, aber die Nutzung einer Palette zeigt eine Stufe von Absicht, welche die Vorstellungskraft eines Archivars reizt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][212979] = {name = "[q2]Hearthstone-Starterpaket", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält ein Starterset mit Hearthstone-Karten für Eure Sammlung.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][212980] = {name = "Wachsartige Ausscheidung", additional_info = "Questgegenstand\n[q]\"Die Produktion mag furchtbar anmuten, aber diese wachsartige Substanz ist fest und dabei formbar und brennt auch noch schön. Perfekt, um Kerzen zu machen.\""}
