MultiLanguageItemData['de'][213000] = {name = "[q2]Heilige Flammenwerferfackel", additional_info = "[q]\"Richtet die Fackel aus, dreht am Griff und seht dabei zu, wie die heiligen Flammen jeden einhüllen, den Ihr nicht mögt. Brennt jedes Nerubernetz nieder.\""}
MultiLanguageItemData['de'][213001] = {name = "Erzklumpen", additional_info = "Questgegenstand\n73 ( 73)\n[q]\"Dieser Klumpen Roherz schaut aus der Erde hervor. Er fühlt sich kalt an und ist überraschend leicht.\""}
MultiLanguageItemData['de'][213002] = {name = "Geladener Kern", additional_info = "Questgegenstand\n73 ( 73)\n[q]\"Dieses seltsame Organ ersetzt das Herz der Kreatur. Selbst nach ihrem Tod strahlt es eine schwache Energie aus.\""}
