MultiLanguageItemData['de'][213019] = {name = "Hearthstone-Karte: Cairne Bluthuf", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fügt diese Karte Eurer Sammlung hinzu."}
MultiLanguageItemData['de'][213020] = {name = "[q2]Uralte Drakonidenschaufel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Durch sorgfältige Beobachtung kann das Alter dieser Schaufel bestimmt werden. Wichtiger noch, dies enthüllt auch, wann der Ackerbau eingeführt wurde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213021] = {name = "[q2]Drakonidenphiole mit Korken", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Der Korken scheint sich über eine Ewigkeit des Verfalls mit der Flasche verbunden zu haben. Ob man sie zulässt oder öffnet, man lernt in beiden Fällen gleich viel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213022] = {name = "[q2]Drakonidenschmiedehammer", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Es ist zwar praktisch unmöglich, das Alter dieses speziellen Hammers zu bestimmen, aber die für seine Herstellung verwendeten Materialien können viel über die Technologie der Zivilisation verraten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213023] = {name = "[q2]Ölgetränkte Fackel der Djaradin", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Nachdem die Djaradin Öl entdeckt hatten, gab es nur wenig, für das sie es nicht verwendeten. Feuer, Waffen, Zerstreuung, alles wurde von dieser neuen Entdeckung beeinflusst.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213024] = {name = "[q2]Blutiger Becher der Djaradin", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Über die Kultur der Djaradin ist wenig bekannt, aber man kommt schon zu gewissen Schlüssen, wenn man blutverkrustete Tassen findet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213025] = {name = "[q2]Uralter Bolzen der Djaradin", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Djaradinwaffen waren vor Jahrhunderten so grausam wie heute und haben sich seit ihrem Aufstieg zur Macht wenig entwickelt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213026] = {name = "[q0]Massiver Drakonidenpinsel", additional_info = "[q]\"Große Drachkin führen diese Pinsel mit überraschender Geschicklichkeit und streichen damit Heime oder malen ausgefeilte Wandgemälde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213027] = {name = "[q0]Abgeschlagene Drakonidentasse", additional_info = "[q]\"Dieser schlecht erhaltene Kelch war seinerzeit ein Vermögen wert, bringt heute aber nur einen geringen Erlös beim örtlichen Händler ein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213028] = {name = "[q0]Gerissener Zirkel", additional_info = "[q]\"Kompasse werden dafür eingesetzt, riesige Archive von Land- und Seekarten zu erstellen, und ein solcher Fund ist nur der erste Schritt bei der Entdeckung des technologischen Fortschritts einer uralten Zivilisation.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213029] = {name = "[q0]Verbogene Drakonidengabel", additional_info = "[q]\"Eine Drakonidengabel mag dem Laien uninteressant vorkommen, aber dieses Werkzeug verrät die Raffinesse seines Herstellers.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213030] = {name = "[q0]Rostige Gartenschere", additional_info = "[q]\"Ein kleiner Tropfen Blut an der Spitze der Schere erklärt vielleicht, warum ein frustrierter Gärtner diese vor Ewigkeiten wegwarf.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213031] = {name = "[q0]Unförmiger Drakonidenkelch", additional_info = "[q]\"Die Jahre haben ihre Spuren an diesem Kelch hinterlassen, aber ein geschultes Auge kann noch viel aus den Überresten lesen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213032] = {name = "[q0]Verzerrter Drakonidenkrug", additional_info = "[q]\"Der zugehörige Deckel passt nicht mehr auf den Krug, kann jetzt aber als winziger Unterteller benutzt werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213033] = {name = "[q0]Brüchige Zange des Schmieds", additional_info = "[q]\"Diese schwer gezeichnete Zange hat jahrhundertelang Feuer geschürt. Winzige Fehler und Kratzer im Metall enthüllen viel davon, was sie gepackt hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213034] = {name = "[q0]Gesprungene Drakonidenschale", additional_info = "[q]\"Diese wunderschöne Schale ist für den alltäglichen Gebrauch ungeeignet, wäre aber ein großartiger Mittelpunkt der Galerie eines jeden Archäologen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213035] = {name = "[q0]Verkrusteter Dracthyrpinsel", additional_info = "[q]\"Dieser Pinsel ist mit Unmengen von Farbe verkrustet und eine Fundgrube an Proben verschiedener Pigmente und Lösungen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213037] = {name = "[q0]Gezackte Gartenschaufel", additional_info = "[q]\"Jahre der Nutzung haben diese Schaufel so schwer beschädigt, dass sie nicht mehr zu reparieren ist. Oh, die Geschichten, die sie erzählen könnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213038] = {name = "[q0]Gesprungene Lupe", additional_info = "[q]\"Dies hätte nützlich dabei sein können, das Kleingedruckte in Neltharions Plänen für die Dracthyr zu lesen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213039] = {name = "[q0]Dünner Drakonidenlöffel", additional_info = "[q]\"Von Utensilien bis hin zu Besteck kann praktisch alles dazu dienen, die Geschichten des alltäglichen Lebens der Bewohner zu erzählen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213040] = {name = "[q0]Mattes Amulett der Djaradin", additional_info = "[q]\"Abnutzung hat viele der Feinheiten dieses Amuletts praktisch verschwinden lassen, aber die allgemeine Form könnte dennoch einiges über die Traditionen der Djaradin verraten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213041] = {name = "[q0]Ausgetrocknete Schriftrolle der Djaradin", additional_info = "[q]\"Nachdem genug Teile gesammelt wurden, um diesen seltenen Fund gewissenhaft zusammenzusetzen, stellt sich heraus, dass diese Schriftrolle mit bedeutungslosen Kritzeleien bedeckt ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213042] = {name = "[q0]Verschlissenes Banner der Djaradin", additional_info = "[q]\"Ein Banner der Djaradin weht in Friedens- ebenso wie in Kriegszeiten und zeigt sein Alter durch die Risse und Schäden, die es über ein langes Leben erleidet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213043] = {name = "[q0]Brüchiges Leder der Djaradin", additional_info = "[q]\"Dieses Leder eignet sich wohl kaum noch fürs Handwerk, außerdem ist seine Herkunft gänzlich unbekannt und bleibt wohl besser ein Geheimnis.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213044] = {name = "[q0]Zerfetztes Reißzahnamulett", additional_info = "[q]\"Bei genauerem Hinsehen scheint der Reißzahn für dieses Amulett von einem Djaradin zu stammen. Vielleicht eine Kampftrophäe?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213045] = {name = "[q0]Gerissene Halskette der Djaradin", additional_info = "[q]\"Dieses kaputte Amulett kann nur wenig verraten, da die Hälfte seiner Teile über die Jahre verloren gingen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213062] = {name = "[q3]Goldene Paradiesaxt", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Einhändig} {Axt}\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n[q]\"Obwohl ihre strahlenden Farben an die Federn von Dschungelvögeln erinnern, kitzeln ihre Ränder nicht.\"\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
