MultiLanguageItemData['de'][213357] = {name = "[q2]Kristallene Wahrsageschale", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Wenn Ihr in die Schale blickt, fühlt es sich an, als könntet Ihr beinahe ein Bild erkennen. Vielleicht ist das auch nur Euer Spiegelbild.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213358] = {name = "[q0]Unvorsichtig ausgegrabener Schädel", additional_info = "[q]\"Aus diesem seltenen Fund hätte man vielleicht große Weisheit lesen können, aber wer ihn auch zuerst gefunden hat, rammte erst mal eine Spitzhacke direkt hindurch!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213359] = {name = "[q2]Gebrochener Drakonidenstab", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Die Zeit hat diesen magischen Fokus inaktiv werden lassen, aber die Gravuren am Schaft erzählen eine noch eindringlichere Geschichte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213360] = {name = "[q0]Weggeworfenes Drakonidenamulett", additional_info = "[q]\"Das Juwel, das früher in diesem Amulett prangte, wurde herausgebrochen, was das Schmuckstück nahezu wertlos macht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213361] = {name = "[q0]Verstörendes Kinderspielzeug", additional_info = "[q]\"Kinder haben beunruhigendes Gefallen an verstörenden Figuren gefunden. Vielleicht sollte dieses Rätsel lieber ungelöst bleiben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213362] = {name = "[q0]Uralte Drakonidensüßigkeit", additional_info = "[q2]Benutzen: Esst mich.\n[q]\"Es mag seine Form bewahrt haben, aber diese steinharte Drakonidenleckerei hat ihr Mindesthaltbarkeitsdatum ganz sicher überschritten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213363] = {name = "[q0]Abgeworfene Augenhaut", additional_info = "[q]\"Wenn Reptilien ihre Schuppen abwerfen, verlieren viele Arten auch die Haut auf den Augen. In dieser Zeit sind die Kreaturen oft blind und wehrlos.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213364] = {name = "[q0]Leere Parfümphiole", additional_info = "[q]\"Ein wunderbares Aroma haftet noch immer am Hals der Phiole.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213365] = {name = "[q2]Geschnitzter Höhlenkristall", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Komplizierte Formen wurden in diesen Kristall geschnitten, wodurch er das Licht auf einzigartige Weise einfängt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213366] = {name = "[q0]Streifen einer Niffenkopfbedeckung", additional_info = "[q]\"Wenn man Material und Entwurf dieses Niffenhuts mit denen vergleicht, die heute allgemein verwendet werden, kann man daraus die Entwicklung der Niffenmode ableiten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213367] = {name = "[q0]Weggeworfener Krallenprototyp", additional_info = "[q]\"Dies scheint ein rudimentärer Versuch zu sein, die Grabfähigkeiten der Niffen zu verbessern. Das Projekt scheint aufgrund von mangelnder Notwendigkeit verworfen worden zu sein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213368] = {name = "[q0]Kratz-und-Schnüffel-Stein", additional_info = "\"An diesem Stein zu kratzen, widerspricht allen Prinzipien der Archäologie, ist aber durchaus verlockend.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213374] = {name = "[q0]Niffennasenstöpsel", additional_info = "[q]\"Niffennasen sind so empfindlich, dass diese manchmal einfach eine Möglichkeit brauchen, für den Tag abzuschalten und etwas Schlaf zu bekommen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213375] = {name = "[q2]Säckchen mit vergrabenen Wertgegenständen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"In den seltenen Fällen, in denen ein Niffen vergisst, wo er sein Glitzerzeug vergraben hat, werden diese verlorenen Taschen zu wunderbaren Zeitkapseln.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213377] = {name = "[q0]Zerfetztes Bilderbuch", additional_info = "[q]\"Riesige Niffenkrallen und empfindliche Bücher vertragen sich nicht gut. Immerhin haben sie es versucht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213380] = {name = "[q0]Unidentifizierbares pferdeartiges Fossil", additional_info = "[q]\"Kommt das auf den Zentaurenstapel oder den Pferdestapel?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213382] = {name = "[q2]Teil einer Zentaurenjagdkarte", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Man kann sehr viel über die hiesigen Zentauren lernen, wenn man ihre Jagdweisen kennt. Dieses Kartenfragment zeigt die überraschende Koordination der damaligen Jagdgruppen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213384] = {name = "[q0]Pferdehaarpuppe", additional_info = "[q]\"Von Generation an Generation weitergegeben, wobei jedes neue Elternpaar einzelne Stiche zur Näherei beitrug.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213385] = {name = "[q0]Steife Bürste", additional_info = "[q]\"Es gibt zwischen Zentauren kein größeres Zeichen von Nähe und Vertrauen als gegenseitige Pflege.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213386] = {name = "[q0]Ausgegrabene Steinpfeilspitze", additional_info = "[q]\"Die Form und Größe der Pfeilspitze enthüllt viel darüber, wie sich die Jagdmethoden der Zentauren über die Jahre verändert haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213387] = {name = "[q0]Primitive Zentaurenschnitzerei", additional_info = "[q]\"Viele Zentauren lieben die Schnitzerei als Tradition, die weiter zurückreicht als sämtliche Aufzeichnungen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213388] = {name = "[q0]Verblasstes Zentaurenbild", additional_info = "[q]\"Ein Nachteil des Nomadenlebens ist, dass sich Höhlenmalereien nicht mitnehmen lassen. Erfindungsreiche Zentauren der Vergangenheit lösten das Problem mit ihren Malereihäuten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213389] = {name = "[q2]Uraltes Zentaurentagebuch", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n[q]\"Anscheinend aus der Sicht eines Kindes geschrieben. Dieses Tagebuch verrät viel über das Leben der frühen Zentauren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213392] = {name = "Duftgranate", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft eine geruchsintensive Granate, um eine wilde Kampfschale zu betäuben und einen Niffen von Rak-Ush auf ihre Position hinzuweisen.\n[q]\"Eine von den Nerubern hergestellte Granate, voll mit einem netten, beruhigenden Rauch. Also wenn man Käfer ist.\""}
