MultiLanguageItemData['de'][213595] = {name = "[q4]Leine des gefiederten Windwellenreiters", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Vor dem Aufsteigen die aktuelle Windstärke und Höhe überprüfen. Bäume und andere hohe Objekte vermeiden. Beschädigte Drachen sind von der Rückgabe ausgeschlossen.\" - Bedienungsanleitung des Windwellenreiters\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213596] = {name = "[q4]Zügel des Tagsturmwindrosses", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wenn ein Blitz die Sonne trifft, soll ein gleißendes Biest in roter Rüstung aus den Himmeln herabsteigen. Das Tagsturmwindross hat von dieser Legende noch nie gehört und war schon immer hier.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213597] = {name = "[q4]Zügel des Waldwindrosses", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das Fell dieses Windrosses passt nicht nur farblich zu seiner bewaldeten Heimat, für gewöhnlich ist es auch mit Rindenstücken und Blättern gespickt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213598] = {name = "[q4]Zügel des flinken Windrosses", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Windrösser sind ungemein sanft und leicht zu trainieren... wenn man sie fangen kann.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213600] = {name = "[q4]Zügel des Marmorqilen", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Von einem Mogumagier erschaffen, der seinem Lieblingsstein Leben einhauchte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213601] = {name = "[q4]Zügel des Qilenwächters", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als Quan der Unerbittliche im Kampf fiel, harrten seine treuen Hunde seiner Rückkehr. Jahrtausende später warten sie noch immer geduldig.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213602] = {name = "[q4]Zügel des goldenen Reitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Kaiser soll einst eine große Summe für einen goldenen Kranich bezahlt haben. Als er erkannte, dass der Kranich lediglich seine Farbe mit dem wertvollen Metall teilte, verkroch er sich voller Scham eine Woche in seinem Schlafgemach.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213603] = {name = "[q4]Zügel des bleichen Reitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Und ich sah, und siehe, ein fahler... Kranich?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213604] = {name = "[q4]Zügel des tropischen Reitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Bewohner des Jadewalds nutzt seine Färbung zur Tarnung.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213605] = {name = "[q4]Zügel des Rosenreitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser farbenprächtige Vogel wird oft mit einem Flamingo oder Marabu verwechselt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213606] = {name = "[q4]Zügel des silbernen Reitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser große Vogel gehört zu den anmutigsten und elegantesten Kranichen, mehr noch als der Bronzekranich, wenn auch nicht so sehr wie der Goldene.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213607] = {name = "[q4]Zügel des luxuriösen Reitkranichs", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein majestätischer Vogel, aber ziemlich wählerisch, was sein Futter angeht.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213608] = {name = "[q4]Zügel der verschneiten Reitziege", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Bergziegen des Kun-Lai-Gipfels sind bekannt dafür, auf der Suche nach Kafabohnen und Salzlecksteinen selbst die höchsten Wipfel zu erklimmen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213609] = {name = "[q4]Zügel der kleinen roten Reitziege", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Was dieser Ziege an Größe fehlt, macht sie mit Sturheit wett.\"\nWeltereignis:\nMists of Pandaria: Remix"}
