MultiLanguageItemData['de'][213611] = {name = "[q3]Zappelnde Probe", additional_info = "Handwerksmaterial\n[q]\"Eine kleine, zappelnde Biomasseprobe, die in modifizierten Kräutern oder heulendem Erz gefunden werden kann. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213612] = {name = "[q3]Grünliche Sporen", additional_info = "Handwerksmaterial\n\"Eine Gruppe Sporen, die vor Lebensenergie strotzen. Wird von Spielercharakteren erworben, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213613] = {name = "[q3]Leylinienrückstände", additional_info = "Handwerksmaterial\n\"Eine Substanz, die leichte Spuren verbleibender Arkanenergie aufweist. Wird von Spielercharakteren erworben, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][213621] = {name = "[q4]Zügel des Jadepterrordax", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das bevorzugte Reittier der Zandalari ist ein großartiger Sänger, zumindest denkt es das.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213622] = {name = "[q4]Zügel der Nachtpterrorschwinge", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Gelehrten erkennen im fürchterlichen Kreischen dieser Kreatur ein \"Fürchtet mich, ich bin die Nacht!\"\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213623] = {name = "[q4]Zügel des blutigen Himmelskreischers", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Dinosaurier trägt noch immer den Zorn seiner Vorfahren von der Zandalariinvasion in sich.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213624] = {name = "[q4]Kobaltkoloss", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n\"Die einstige Bergbau- und Holzfällermaschine nahm schnell chaotische Züge an, als den Ingenieuren der Gedanke kam, ob man sie nicht noch etwas cooler machen könnte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213625] = {name = "[q4]Teufelseisenkoloss", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Kriegsmaschine wurde aus einer Zeitlinie gestohlen, in der Garrosh Höllschrei sich der Brennenden Legion anschloss. Unnötig zu erwähnen, dass von dieser Zeitlinie nicht mehr viel übrig ist.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213626] = {name = "[q4]Zügel des violetten Shado-Pan-Reittigers", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wollt Ihr einen Tiger wecken, nehmt einen langen Stock. Oder noch besser: Schickt einen Freund, den Tiger zu wecken.\" - Pandarensprichwort\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213627] = {name = "[q4]Zügel des fahlen Mushan", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das fahle Mushan ist das köstlichste seiner Art, allerdings wird es nicht gern daran erinnert.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213628] = {name = "[q4]Zügel des Flussläufermushan", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das Mushan ist eine gierige Bestie. Es kann zwar gezähmt werden, doch wird es ein zweites, drittes, ja sogar viertes Frühstück an jedem Tag verlangen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][213629] = {name = "Entwanzerhut", additional_info = "Questgegenstand\n[q2]Benutzen: Fügt dem aktuellen gegnerischen Ziel 20 Naturschaden zu und springt auf Ziele in der Nähe über... mit unberechenbaren Folgen. Kann auch auf Kreaturen überspringen, die keine Testsubjekte sind. (8 Sek. Abklingzeit)\n[q]\"Jennis Erfindung müsste die Käfer in der Nähe von Mmarl entfernen. Theoretisch.\""}
MultiLanguageItemData['de'][213630] = {name = "Fass mit Schwarzpulver", additional_info = "Questgegenstand\n[q]\"Spinnen hassen dieses Zeug.\""}
