MultiLanguageItemData['de'][215464] = {name = "Fragment eines Erinnerungsedelsteins", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Matt und mit spinnwebenartigen Rissen durchzogen. Der Edelsteinteil ist so gebrochen, dass er in Eurer Hand zerfallen könnte. Der ursprüngliche Edelstein muss beträchtlichen Schaden erlitten haben. Der ist nicht mehr zu retten.\""}
MultiLanguageItemData['de'][215466] = {name = "Geheiligte Vorräte", additional_info = "[q]\"Diese Vorräte sind in der Lage, die Barrieren der Finsternis in der Umgebung zu zerstreuen.\""}
