MultiLanguageItemData['de'][216624] = {name = "[q2]Mal der Arroganz", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Angreifer erhalten ein 'Mal der Arroganz', das 10 Sek. lang alle 2 Sek. Schattenschaden verursacht und bis zu 5-mal stapelbar ist.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216625] = {name = "[q2]Rasanter Schlag", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance von 100%, 4 bis 7 zusätzliche automatische Angriffe auszulösen. (10 Sek. Abklingzeit)\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216626] = {name = "[q2]Töten", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Wenn Ihr einen Gegner angreift, der weniger als 10% Gesundheit besitzt, versucht Ihr, ihn zu 'Töten', was Schattenschaden in Höhe von 100% Eurer maximalen Gesundheit verursacht.\n\n Ihr könnt höchstens einmal versuchen, einen Gegner zu 'Töten'.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216627] = {name = "[q2]Schild des Tüftlermeisters", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Gewährt einen Schild, der Schaden in Höhe von 15% Eurer Gesamtgesundheit verursacht.\n\n Dieser Schild regeneriert sich, wenn er 5 Sek. lang keinen Schaden erleidet.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216628] = {name = "[q2]Siegesfeuer", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Immer, wenn Ihr einen Gegner besiegt, brecht Ihr aus, was innerhalb von 12 Metern Gegnern Feuerschaden zufügt und Verbündete heilt.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216629] = {name = "[q3]Blinzeln", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Blinzeln\nTeleportiert Euch 20 Meter, oder bis Ihr auf ein Hindernis stoßt, vorwärts und befreit Euch von Betäubungs- und Bewegungsunfähigkeitseffekten.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][216630] = {name = "[q3]Heldenhafter Sprung", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Heldenhafter Sprung\nSpringt durch die Luft zu einem Zielort und schmettert mit zerstörerischer Gewalt auf den Boden, sodass alle Gegner innerhalb von 8 Metern (23.5% der Zaubermacht + 23.5% der Angriffskraft) körperlichen Schaden erleiden.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
