MultiLanguageItemData['de'][216644] = {name = "[q3]Fehlerhafter tödlicher Saphir", additional_info = "Prismatischer Edelstein\n[q2]Benutzen: Kombiniert 3 dieser Edelsteine zu einem noch mächtigeren Edelstein.\n80 ( 80)\n[q]\"Passt in einen prismatischen Sockel. Die gewährte Macht hängt vom eingesetzten Gegenstand ab.\""}
MultiLanguageItemData['de'][216647] = {name = "[q2]Hagelsturm", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Baut alle 3 Sek. eine Aufladung von 'Hagelsturm' auf. Bei 10 Stapeln wird Hagel auf Gegner innerhalb von 50 Metern entfesselt. Jeder Einschlag verursacht Frostschaden und belegt Gegner mit 'Betäubende Kälte'.\n\n Betäubende Kälte\nVerringert die Bewegungsgeschwindigkeit um 30% und den verursachten Schaden um 10%. Angreifen entfernt einen Stapel 'Betäubende Kälte'.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216648] = {name = "[q2]Kaltfront", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, bis zu 5 Verbündeten einen Schild zu gewähren, der gleichmäßig aufgeteilt Schaden absorbiert, und alle Gegner innerhalb von 50 Metern mit 'Betäubende Kälte' zu belegen.\n\n Betäubende Kälte\nVerringert die Bewegungsgeschwindigkeit um 30% und den verursachten Schaden um 10%. Angreifen entfernt einen Stapel 'Betäubende Kälte'.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216649] = {name = "[q2]Brüchig", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Fähigkeiten belegen Gegner mit 'Brüchig', was 10% Eures verursachten Schadens ansammelt. Wenn ein mit 'Brüchig' belegter Gegner getötet wird, explodiert er und fügt Gegnern innerhalb von 12 Metern Frostschaden zu, der gleichmäßig unter den Zielen aufgeteilt wird.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216650] = {name = "[q2]Erinnerung an Rache", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Alle 10 Sek. 1% Hauptwert pro 5% verlorener Gesundheit.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216651] = {name = "[q2]Sengendes Licht", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: 10% Eurer Heilung werden als 'Sengendes Licht' auf Verbündeten gebündelt. Nach 3 Sek. wird 'Sengendes Licht' verbraucht, um einen Verbündeten zu heilen und allen Gegnern innerhalb von 12 Metern Heiligschaden zuzufügen.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][216653] = {name = "Säckchen des Zeitläufers", additional_info = "Wird beim Aufheben gebunden\n36 Platz Tasche\n80 ( 80)"}
MultiLanguageItemData['de'][216655] = {name = "Goblinhaftrakete", additional_info = "Verbrauchbares\n[q2]Benutzen: Verschießt ein Sperrfeuer aus Raketen, die einen Kleber enthalten, in einer Linie vor dem Zaubernden.\n\n Die Bewegungsgeschwindigkeit von Gegnern wird im Kleber drastisch verringert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][216657] = {name = "[q3]Testgegenstand C", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Erhöht Eure Bewegungsgeschwindigkeit um 50%, aber fügt Euch alle 1 Sek. Schaden in Höhe von 4% Eurer maximalen Gesundheit zu. Bewegungseinschränkende Effekte können Euch nicht auf unter 100% Eurer normalen Bewegungsgeschwindigkeit verlangsamen. Hält bis Abbruch an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][216658] = {name = "Schattenwerfer der Sureki", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die Neruber nutzen diese Emitter, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\""}
MultiLanguageItemData['de'][216659] = {name = "Schattenwerfer der Sureki", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Neruber nutzen diese Schattenwerfer, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\""}
MultiLanguageItemData['de'][216660] = {name = "Schattenwerfer der Sureki", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Neruber nutzen diese Schattenwerfer, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\""}
MultiLanguageItemData['de'][216663] = {name = "[q4]Vergessenssphäre", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Vergessenssphäre\nFormt eine Kugel aus reinster Leere, die den von Gegnern innerhalb von 15 Metern erlittenen Schaden 10 Sek. lang um 15% erhöht. Nach 4 Sek. explodiert die Kugel, verursacht Schattenschaden und betäubt getroffene Gegner für 1 Sek.\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][216664] = {name = "Fädlingköder", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft eine Spinnlingpheromongranate auf den Boden, um Spinnlinge von Rak-Ush anzulocken. (6 Sek. Abklingzeit)\n[q]\"Ein granatenartiges Objekt, das Fädlinge von Rak-Ush anlockt.\""}
MultiLanguageItemData['de'][216665] = {name = "[q4]Entfernungshemmer der Kriegsmeutenbank", additional_info = "Wird beim Aufheben gebunden"}
