MultiLanguageItemData['de'][216669] = {name = "Zerschmetterte Überbleibsel", additional_info = "Questgegenstand\n[q]\"Einst Teil einer machtvollen Schlüsselflamme.\""}
MultiLanguageItemData['de'][216670] = {name = "Feuerbienenwachs", additional_info = "Questgegenstand\n[q]\"Das weiche Wachs ist noch warm. Im Inneren befinden sich schimmernde Funken.\""}
MultiLanguageItemData['de'][216671] = {name = "[q4]Donnernde Kugel", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Donnernde Kugel\nVerwandelt Euch in eine donnernde Kugel und fügt Gegnern innerhalb von 30 Metern im Verlauf von 4 Sek. Naturschaden zu. Als donnernde Kugel wird Euer erlittener Schaden um 50% und Eure Bewegungsgeschwindigkeit um 70% verringert. Außerdem werdet Ihr immun gegen Kontrollverlusteffekte.\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][216672] = {name = "Der Strauchdieb", additional_info = "Verbrauchbares\n[q2]Benutzen: Verkleidet Euch als einfacher Strauch. Ihr und Eure Verbündeten seid unsichtbar, während Ihr verkleidet seid.\n\n Eure Basiscombo wird durch 'Buschschlag' ersetzt, was Euer aktuelles Ziel betäubt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][216677] = {name = "Korgrans Laterne", additional_info = "Questgegenstand\n73 ( 73)\n[q]\"Der geladene Kern der Laterne taucht den Bereich in kaltes, blaues Licht. Auf der Unterseite befindet sich eine Gravur mit der Inschrift: \"Von Korgran und einem geschätzten Freund hergestellt\".\""}
MultiLanguageItemData['de'][216681] = {name = "Händlerstandteile", additional_info = "Questgegenstand\n[q]\"Ein abwechslungsreiches Bündel aus Holzverschnitten, rostigem Metall, Stofffetzen und verschiedenen Behältern, das nach Jankys Vorgaben zusammengestellt wurde.\""}
MultiLanguageItemData['de'][216682] = {name = "Die Einladung des Wesirs", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine Einladung für ein Treffen mit dem Vertreter des Wesirs. Verdächtig persönlich.\"\n[q2]<Zum Lesen rechtsklicken>"}
