MultiLanguageItemData['de'][216687] = {name = "Zusammengeflickte Verbände", additional_info = "Questgegenstand\n[q2]Benutzen: Kann in der Not zur Heilung eines verletzten Soldaten verwendet werden. (2 Sek. Abklingzeit)\n[q]\"Diese Verbände sehen aus, als hätte jemand einfach nur ein paar Stofffetzen zusammengeworfen. Sie werden die Heilung unterstützen, aber auch wirklich nur gerade so eben.\""}
MultiLanguageItemData['de'][216688] = {name = "Schlüssel zu den Hochhöhlen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ag'thax in den Hochhöhlen wird sich sehr freuen, dass er jetzt in seinen neuen Bau kommt.\""}
MultiLanguageItemData['de'][216689] = {name = "Alberts Kopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n[q]\"Von Albert ist nur noch sein augenloser Kopf übrig.\""}
MultiLanguageItemData['de'][216693] = {name = "Schattenflutkrabbe", additional_info = "Questgegenstand\n[q]\"Sehr lebendig, sehr schnappfreudig. Gut, dass Ihr einen Käfig habt!\""}
MultiLanguageItemData['de'][216694] = {name = "Empfehlungsschreiben", additional_info = "Questgegenstand\n[q]\"Ohne Zweifel Eure beste Arbeit.\""}
MultiLanguageItemData['de'][216695] = {name = "[q4]Lebenssturm", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n{[q2]Anlegen: Erlernt folgenden Zauber.\n\n Lebenssturm\nBeschwört einen Sturm. Ruft alle 1 Sek. 5 Blitzschläge herab. Jeder Blitzschlag fügt einem Gegner innerhalb von 30 Metern Naturschaden} zu.\n\n Während des Sturms wachsen um den Zaubernden 3 Blumen. Nach 3 Sek. erblühen die Blumen und stellen bei Verbündeten Gesundheit wieder her und gewähren ihnen {Tempo. Hält 10 Sek. lang an.}\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][216696] = {name = "[q2]Versteckte Hosen", additional_info = "Kosmetisch\nBeine Kosmetisch\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][216697] = {name = "Signet des Ratsvorstehers", additional_info = "Questgegenstand\n[q]\"Der quadratische Stein dieses schweren Rings wurde im Laufe der Zeit durch Abnutzung geglättet. In das Band sind fremdartige Zeichen graviert.\""}
MultiLanguageItemData['de'][216708] = {name = "Heilige Kerze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Dekoriert einen Bereich mit einer Arathikerze, die 15 Min. lang brennt.\n[q]\"Den Gefallenen zur Ehre und den Verlorenen ein Wegweiser.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][216710] = {name = "[q4]Hochlanddrache: Verkörperung des drakonischen Gladiators", additional_info = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird."}
MultiLanguageItemData['de'][216711] = {name = "[q4]Chi-Ji, der Rote Kranich", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt den folgenden Zauber.\n\n Chi-Ji, der Rote Kranich\n Erhöht die Bewegungsgeschwindigkeit um 50%, gewährt Immunität gegen bewegungseinschränkende Effekte und folgende Zauber. Hält 20 Sek. lang an.\n\n Kranichschwarm\nFlattert ein kurzes Stück vorwärts.\n\n Flammende Nova\nEine Feuerexplosion wirft Euch zurück, was Gegnern innerhalb von 10 Metern Feuerschaden zufügt und Verbündete in diesem Bereich heilt.\n\n Gefieder der Hoffnung\nChi-Ji wirft alle 2 Sek. eine Feder ab. Wer die Feder berührt, löst eine Salve von 'Flamme der Hoffnung' aus, die Gegnern Schaden zufügt und Verbündete heilt.\n\n Flamme der Hoffnung\nFügt Gegnern innerhalb von 30 Metern alle 2 Sek. Feuerschaden zu oder stellt bei Verbündeten in diesem Bereich Gesundheit wieder her. Betrifft 5 Ziele.\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][216712] = {name = "Bronzene Taschenuhr", additional_info = "Questgegenstand\nEinzigartig\n80 ( 80)\n[q]\"Wenn Ihr dies benutzt, wird die Zeit zurückgedreht und Eure Position zurückgesetzt.\""}
MultiLanguageItemData['de'][216719] = {name = "Kapitän Fasshaxes Kanonade", additional_info = "Verbrauchbares\n[q2]Benutzen: Signalisiert Fasshaxe, dass er Eure Position mit einem Kanonensperrfeuer belegen soll. Das Sperrfeuer fügt ALLEN Zielen, die von ihm erfasst werden, schweren Schaden zu.\nVerkaufspreis:"}
MultiLanguageItemData['de'][216720] = {name = "Wertvolle Teile", additional_info = "Questgegenstand\n[q]\"Eine fettverschmierte Anhäufung esoterischer Maschinenteile.\""}
