MultiLanguageItemData['de'][216882] = {name = "Eintrag 467-21-5", additional_info = "Questgegenstand\n[q]\"Beobachtung: Die Myzelausbreitung hat alarmierende Ausmaße angenommen und greift nun auf benachbarte Vegetation über. Die Fungianer zeigen eine gesteigerte Reaktion auf umweltbedingte Stimuli, was auf einen potenziellen Wandel in ihrem ökologischen Verhalten deuten könnte.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][216888] = {name = "Eintrag: 652-12-3", additional_info = "Questgegenstand\n[q]\"Anmerkung: Fungianer zeigen aggressive mykorrhizalische Interaktionen, die andere konkurrierende Fungusarten verdrängen. Das beschleunigte Wachstum wirft Bedenken hinsichtlich der potenziellen ökologischen Ungleichgewichte im betroffenen Bereich auf.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][216889] = {name = "Eintrag: 893-03-9", additional_info = "Questgegenstand\n[q]\"Beobachtung: Fungianer breiten sich nun über den ursprünglichen Studienbereich hinweg aus. Es wurden aggressive Myzelübergriffe in unerwarteten Habitaten festgestellt. Es bedarf einer dringenden Untersuchung, um die ökologischen Auswirkungen dieses neuartigen Verhaltens festzustellen (...)\"\n[q2]<Zum Lesen rechtsklicken>"}
