MultiLanguageItemData['de'][217605] = {name = "Zeitlose Schriftrolle der Intelligenz", additional_info = "[q2]Benutzen: Erfüllt das Ziel mit Brillanz, die seine Intelligenz 1 Stunde lang um 4% erhöht.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)"}
MultiLanguageItemData['de'][217606] = {name = "Zeitlose Schriftrolle der Seelenstärke", additional_info = "[q2]Benutzen: Erfüllt das Ziel mit Lebenskraft, die seine Ausdauer 1 Stunde lang um 4% erhöht.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)"}
MultiLanguageItemData['de'][217607] = {name = "Zeitlose Schriftrolle der Wildnis", additional_info = "[q2]Benutzen: Erfüllt ein verbündetes Ziel mit der Macht der Wildnis. Erhöht die Vielseitigkeit des Ziels 1 Stunde lang um 2%.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt.\n80 ( 80)"}
MultiLanguageItemData['de'][217608] = {name = "Zeitlose Schriftrolle des Schlachtrufs", additional_info = "[q2]Benutzen: Erhöht die Angriffskraft aller Gruppen- und Schlachtzugsmitglieder innerhalb von 100 Metern 1 Stunde lang um 4%.\n80 ( 80)"}
MultiLanguageItemData['de'][217610] = {name = "Erinnerungsedelstein eines Irdenen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Dieser eckig geschliffene Edelstein ist schwer für seine Größe und leuchtet schwach. Die Irdenen haben diesen Speicher in Edelsteinform zur Programmierung ihrer Erinnerungen entwickelt. Er kann auf die Archive der Irdenen hochgeladen werden.\""}
MultiLanguageItemData['de'][217612] = {name = "[q4]Halsband von Zovaals Schemenbestie", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"War ich ein guter Junge?\", fragte die Seele Zovaal. \"Nein. Ich habe gehört, Ihr wart der Schlimmste.\"\nErfolg:\nZurück aus dem Jenseits\nKategorie:\nErweiterungsfeatures"}
