MultiLanguageItemData['de'][217898] = {name = "Gebet des geläuterten Hasses", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Der nächste Angriff, der Eure Gesundheit unter 35% bringt, löst ' Geläuterter Hass ' aus.\n\nGeläuterter Hass :\nStellt Eure Gesundheit, Euren Elan und Eure Klassenressourcen vollständig wieder her.\n80 ( 80)"}
MultiLanguageItemData['de'][217899] = {name = "Gebet des geläuterten Stolzes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Erlangt außerhalb des Kampfes ' Geläuterter Stolz '.\n\nGeläuterter Stolz :\nVerschwindet von der Bildfläche in die Verstohlenheit. Euer nächster Angriff erzielt garantiert einen kritischen Treffer.\n80 ( 80)"}
MultiLanguageItemData['de'][217900] = {name = "Gebet des geläuterten Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Wenn Ihr das nächste Mal getroffen werdet, entfesselt Ihr ' Geläuterter Zorn '.\n\nGeläuterter Zorn :\nFügt Gegnern innerhalb von 8 Metern 2625000 körperlichen Schaden zu und betäubt sie für 3 Sek.\n80 ( 80)"}
MultiLanguageItemData['de'][217901] = {name = "Zeitlose Trommeln", additional_info = "[q2]Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\n Wenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder ähnlichen Effekten profitieren. (2 Min Abklingzeit)\n80 ( 80)"}
MultiLanguageItemData['de'][217902] = {name = "Phiole des Zeitläufers", additional_info = "[q2]Benutzen: Erhöht Eure Manaregeneration 6 Sek. lang um 1000%.\n\n Verringert die Bewegungsgeschwindigkeit um 50%. (6 Sek. Abklingzeit)\n80 ( 80)"}
MultiLanguageItemData['de'][217903] = {name = "[q2]Rechtschaffene Stärkung", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: 10% Eures Schadens wird als 'Rechtschaffene Stärkung' gesammelt. 'Rechtschaffene Stärkung' wird alle 3 Sek. verbraucht und heilt bis zu 3 Verbündete innerhalb von 50 Metern um die verbrauchte Menge.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][217904] = {name = "Zeitläufertrunk der Macht", additional_info = "[q2]Benutzen: Stellt 525000 Mana wieder her und erhöht Hauptwert 30 Min. lang um 3%. (5 Min Abklingzeit)\n80 ( 80)\n[q]\"Zusätzliche Vorräte sind bei Nostwin an beliebigen Ewigen Basaren erhältlich.\""}
MultiLanguageItemData['de'][217905] = {name = "Zeitläufertrunk der Gesundheit", additional_info = "[q2]Benutzen: Stellt 1050000 Gesundheit wieder her und erhöht die Ausdauer 30 Min. lang um 3%. (5 Min Abklingzeit)\n80 ( 80)\n[q]\"Zusätzliche Vorräte sind bei Nostwin an beliebigen Ewigen Basaren erhältlich.\""}
MultiLanguageItemData['de'][217906] = {name = "Drachenleckerli", additional_info = "Einzigartig (3)\n[q2]Benutzen: Stellt Elan vollständig wieder her und gewährt der Fluggeschwindigkeit einen Schub. Nur beim Drachenreiten einsetzbar. (15 Sek. Abklingzeit)\n80 ( 80)"}
MultiLanguageItemData['de'][217907] = {name = "[q2]Wärme", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erhöht die erhaltene Heilung um 10%. 75% der überschüssigen Heilung wird als 'Wärme' gesammelt. 'Wärme' wird alle 5 Sek. verbraucht und heilt einen verletzten Verbündeten innerhalb von 50 Metern um die verbrauchte Menge.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][217925] = {name = "Flasche voller Bienen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (3)\n[q2]Benutzen: Ärgert alle Gegner innerhalb von 40 Metern um den Zielort, fordert sie zum Kampf heraus und belegt sie 30 Sek. lang mit 'Beulen'. Nur im Freien einsetzbar.\n\n Beulen :\nLässt einen Gegner 30 Sek. lang 5% mehr Schaden erleiden. Wenn der Gegner Schaden erleidet, besteht die Chance, dass ihm weitere Beulen zugefügt werden. (1 Min Abklingzeit)\n80 ( 80)\n[q]\"Sie summen wie wild.\""}
MultiLanguageItemData['de'][217926] = {name = "Flasche voller toter Bienen", additional_info = "[q2]Benutzen: Fügt Gegnern im Umkreis von 3 Metern 26250 körperlichen Schaden zu. (1 Min Abklingzeit)\n80 ( 80)\n[q]\"Uups.\""}
MultiLanguageItemData['de'][217927] = {name = "[q2]Retter", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Wenn ein Verbündeter mit weniger als 35% Gesundheit geheilt wird, erhält er einen Absorptionsschild in Höhe von 50% der hervorgerufenen Heilung.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][217928] = {name = "Zeitlose Schriftrolle der Auferstehung", additional_info = "[q2]Benutzen: Bringt einen toten Verbündeten mit 35% Gesundheit und Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden. (30 Sek. Abklingzeit)\n80 ( 80)"}
MultiLanguageItemData['de'][217929] = {name = "Zeitlose Schriftrolle der Läuterung", additional_info = "[q2]Benutzen: Hebt alle Flüche, Krankheiten, Gifte und schädlichen magischen Effekte des anvisierten Verbündeten auf. (30 Sek. Abklingzeit)\n80 ( 80)\n[q]\"Die Zeit heilt alle Wunden, Krankheiten, Flüche, Kater...\""}
MultiLanguageItemData['de'][217930] = {name = "Nostwins Gutschein", additional_info = "[q2]Benutzen: Bringt Euch zu einem Ewigen Basar in der Nähe zurück. (15 Min Abklingzeit)\n80 ( 80)\n[q]\"Beehrt uns bald wieder!\""}
MultiLanguageItemData['de'][217956] = {name = "Zeitlose Schriftrolle der Beschwörung", additional_info = "[q2]Benutzen: Führt ein Ritual zur Erschaffung eines Beschwörungsportals durch, das 3 Min. lang bestehen bleibt und von Verbündeten benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören. (30 Sek. Abklingzeit)\n80 ( 80)"}
MultiLanguageItemData['de'][217957] = {name = "[q2]Rettung", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: 4% der Heilung wird als Errettung angesammelt. Liegt die Gesundheit eines Verbündeten nach von Euch erhaltener Heilung unter 50%, wird die Errettung verbraucht und heilt bis zu 3 Verbündete innerhalb von 50 Metern um die verbrauchte Menge. Die Heilung wird gleichmäßig unter ihnen aufgeteilt.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
