MultiLanguageItemData['de'][217983] = {name = "[q3]Rückzug", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Rückzug\nSpringt rückwärts, hebt alle bewegungseinschränkenden Effekte auf und erhöht 4 Sek. lang Eure Bewegungsgeschwindigkeit um 25%.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][217985] = {name = "[q3]Unvergessener goldener Greif", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört einen reitbaren unvergessenen goldenen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"In Sturmwind sind Löwen beliebt, und der Greif ist zur Hälfte Löwe. Deswegen sind diese Kreaturen ein wichtiger Bestandteil der Luftreisen durch die Gebiete der Allianz.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25"}
MultiLanguageItemData['de'][217986] = {name = "[q2]\"Köstliche\" Eibestandteile", additional_info = "[q]\"Koboldköche aus Lorenhall sind sich einig! Ohne diese Eier ist kein Gericht komplett.\""}
MultiLanguageItemData['de'][217987] = {name = "[q3]Unvergessener Windreiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört einen reitbaren grünen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Hunderte Schlachten in Dutzenden Kampagnen wurden auf dem Rücken dieser geehrten Kreaturen bestritten und gewonnen.\"\nVerkäufer:\nGedenker Amuul\nZone:\nDalaran\nKosten:\n25"}
