MultiLanguageItemData['de'][218003] = {name = "[q3]Glaubenssprung", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Glaubenssprung\nZieht die Seele eines Gruppen- oder Schlachtzugsmitglieds zu Euch, sodass es sofort direkt vor Euch landet und seine Bewegungsgeschwindigkeit 3 Sek. lang um 40% erhöht wird.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][218004] = {name = "[q3]Verschwinden", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Verschwinden\nErmöglicht es Euch, sofort zu verschwinden und so im Kampf 10 Sek. lang in den Verstohlenheitsmodus überzugehen. Schaden oder schädliche Effekte heben die Verstohlenheit nicht auf. Bewegungseinschränkende Effekte werden beim Verschwinden entfernt.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
