MultiLanguageItemData['de'][218082] = {name = "[q3]Gunst des Geistwandlers", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Gunst des Geistwandlers\nEin Ruf nach Führung durch die Geister gestattet es 15 Sek. lang, Zauber aus der Bewegung heraus zu wirken. Kann während des Wirkens anderer Zauber gewirkt werden.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][218084] = {name = "Zusammengeknüllte Notiz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n[q]\"Ein um einen Schlüssel gewickelter Zettel, der bei Klaskins Leiche gefunden wurde.\""}
