MultiLanguageItemData['de'][218105] = {name = "[q3]Klingensegen der Loa", additional_info = "Kosmetisch\n[q7]Wird an Kriegsmeute gebunden\n{Zweihändig} {Schwert}\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\n[q2]Benutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen."}
MultiLanguageItemData['de'][218106] = {name = "Stillsteinfroschfalle", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft eine Froschfalle auf den Boden, die 20 körperlichen Schaden verursacht, wenn ein Gegner darauf tritt, und diesen für 6 Sek. betäubt.\n\n Kann beim Stillsteintümpel und in den umgebenden Gebieten verwendet werden. (10 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][218107] = {name = "Funkenkäferglas", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Wenn Ihr das Glas schüttelt, beginnen die Funkenkäfer im Inneren schwach zu leuchten und die Umgebung ein wenig zu erhellen.\n\n Mit diesem Licht könnt Ihr verborgene Gegenstände im Stillsteintümpel und Schlüsselflammengebieten in der Nähe finden. (15 Sek. Abklingzeit)\n[q]\"Die leuchtenden, kleinen Käfer im Inneren sorgen für ein fantastisches, farbenfrohes Licht.\""}
MultiLanguageItemData['de'][218108] = {name = "[q3]Dunkler Pakt", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Dunkler Pakt\nOpfert 20% Eurer aktuellen Gesundheit, um Euch 20 Sek. lang in einen Schild zu hüllen, der Schaden in Höhe von 200% der geopferten Gesundheit absorbiert. Kann eingesetzt werden, während Ihr von Kontrollverlusteffekten betroffen seid.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][218109] = {name = "[q3]Unaufhaltsamer Tod", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Unaufhaltsamer Tod\nEure Bewegungsgeschwindigkeit ist 10 Sek. lang um 35% erhöht. Ihr könnt nicht auf weniger als 100% Eurer normalen Geschwindigkeit verlangsamt werden und seid immun gegen externe Bewegungseffekte und Rückstöße.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][218110] = {name = "[q3]Seelengestalt", additional_info = "Zahnradedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Seelengestalt\nVerwandelt Euch für 12 Sek. in einen Vulpin, teleportiert Euch 15 Meter vorwärts und erhöht Eure Bewegungsgeschwindigkeit um 50%. Ihr könnt 'Seelengestalt' alle paar Sekunden erneut aktivieren, um Euch noch einmal zu teleportieren.\n80 ( 80)\n[q]\"Passt in einen Zahnradsockel.\""}
MultiLanguageItemData['de'][218111] = {name = "[q4]Zügel des Bernpterrordax", additional_info = "Remix: Pandaria\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Pterrordax könnte und würde Euch in Sekundenschnelle verspeisen. Ist es wirklich so eine gute Idee, auf ihm zu reiten?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['de'][218112] = {name = "[q3]Farbenfroher Strandstuhl", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Stellt einen farbenfrohen Strandstuhl auf. (5 Min Abklingzeit)\n[q]\"Nach einem Bad im kühlen Nass gegen die Sommerhitze erwartet Euch herrliche Entspannung auf dieser harmonischen Farbkomposition, die an warme Sonnenuntergänge und Regenbögen erinnert.\""}
