MultiLanguageItemData['de'][218114] = {name = "[q4]Auge der Erweckung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fügt einem Gegenstand der Saison 4 von Dragonflight, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Armschienen, Gürtel und Ringe angewandt werden."}
