MultiLanguageItemData['de'][218121] = {name = "[q3]Kerzenlicht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Von Euch geht eine schwache Flamme aus. Die Dunkelheit vermag sie nicht zu vertreiben, aber sie offenbart 5 Min. lang durch die Dunkelheit verborgene Geheimnisse.\n\n Solange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen.\n[q]\"Ihr habt die Kerze tatsächlich genommen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][218122] = {name = "[q2]Gestohlenes Relikt", additional_info = "[q]\"Das Licht in diesem Relikt leuchtet immer noch, trotz der Versuche der Kobyss, es zu verderben.\""}
MultiLanguageItemData['de'][218123] = {name = "[q2]Leuchtender Splitter", additional_info = "[q]\"Ihr konntet den Schmutz abfegen, der verwendet wurde, um das Leuchten dieses Splitters zu verdunkeln.\""}
MultiLanguageItemData['de'][218124] = {name = "Elementextraktor", additional_info = "Questgegenstand\n[q2]Benutzen: Entzieht Elementaren Elementarenergie, um einzigartige Kräfte zu erhalten. (5 Sek. Abklingzeit)\n[q]\"Ein Gerät, das unerschütterliche Kräfte von Elementaren aufspürt und sie ihnen entzieht.\""}
MultiLanguageItemData['de'][218125] = {name = "[q4]Reaktiver eingewebter Wappenschild", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Schild}hand} {Schild}\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n[q2]43 Rüstung\nHaltbarkeit 120 / 120\n[q2]Anlegen: Beim Erleiden von Magieschaden besteht eine Chance, dass die Spinnweben reagieren und sich anpassen, wodurch sie Euch für 30 Sek. Sek. mit Schutzfäden einwickeln. Solange die Schutzfäden aktiv sind, absorbieren sie sämtlichen Schaden, den Ihr durch Zauber dieser Quelle erleiden würdet, bis zu 81103 Schaden. (2 Min. Abklingzeit) (2Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][218126] = {name = "[q4]Spritze des Besudlers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\n{Zweihändig} {Stangenwaffe}\n487 - 905 Schaden Geschwindigkeit 3.60\n(193.3 Schaden pro Sekunde)\n+416 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 478.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, das Blut Eures Gegners zu besudeln und im Verlauf von 10 Sek. [ 1 * ( 3233 * (5))] Naturschaden zu verursachen. Weitere Injektionen überschneiden sich.\n\n Wenn ein von 'Besudeltes Blut' betroffenes Ziel stirbt, wird das verbleibende Gift entzogen und in die Klinge zurückgeführt, wodurch Eure nächsten Nahkampffähigkeiten ( 1 * 8083 ) zusätzlichen Naturschaden verursachen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][218127] = {name = "Immerblühender Pilz", additional_info = "Questgegenstand\n[q]\"Dieser Pilz wächst schnell und scheint auf allem zu sprießen.\""}
