MultiLanguageItemData['de'][219007] = {name = "[q2]Köder für scheue Kreaturen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\nBenötigt Kürschnerei von Khaz Algar (1)\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219008] = {name = "[q4]Überragender Wildtierköder", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder und lockt eine hochkarätige scheue Kreatur aus ihrem Versteck.\n\n Kann nur in der Grollenden Einöde in den Schallenden Tiefen eingesetzt werden.\nBenötigt Kürschnerei von Khaz Algar (1)\n[q]\"Ein exquisiter Köder, der nach detaillierten Vorgaben hergestellt wurde, um ein mächtiges Wildtier anzulocken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219009] = {name = "[q3]Köder für kristalline Kreaturen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit Kristallpulver angereichert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219010] = {name = "[q3]Köder für zuckende Kreaturen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit einer Essenz angereichert, die vor boshafter Energie trieft.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219011] = {name = "[q3]Köder für sporenverschmolzene Kreaturen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\n Die Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\n Kann nur im Freien in Khaz Algar verwendet werden.\n[q]\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit magischen Sporen angereichert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219013] = {name = "[q4]Vortrefflicher Bestienreißzahn", additional_info = "Handwerksmaterial\n[q]\"Ein riesiger Reißzahn einer besonders mächtigen, aber scheuen Kreatur in Khaz Algar, der von Kürschnern gewonnen wurde. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219014] = {name = "[q2]Rachsüchtiger Feuergeist", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 493.\n[q2]Anlegen: Eure Distanzangriffe haben eine Chance, eine rachsüchtige Flamme zu Eurem Ziel zu schicken, die ( 1 * 19916 ) Feuerschaden verursacht, wenn sie dieses erreicht.\n\n Der Geist wächst, während er sich auf das Ziel zubewegt, und verursacht bis zu 100% zusätzlichen Feuerschaden.\nVerkaufspreis:"}
