MultiLanguageItemData['de'][219284] = {name = "Explosivstangen", additional_info = "Questgegenstand\n[q2]Benutzen: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 Sek..\n Inflicts 4 Fire damage to enemies within 5 yards of the impact. (5 Sek. Abklingzeit)\n[q]\"Dieser Sprengstoff ist für zwei Dinge gut: Koboldtunnel zum Einsturz bringen.\""}
