MultiLanguageItemData['de'][219294] = {name = "[q3]Energiegeladene Sturmkrähenfeder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\n[q2]Benutzen: Hält die Feder für [1.0][1] Sek. hoch, um mit der Macht des Sturms zuzuschlagen, der auf den Zielort niedergeht und ( 1 * 124864 ) Naturschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219295] = {name = "[q3]Siegel der algarischen Einigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, einen irdenen Verbündeten zu Hilfe zu rufen, der Euch im Kampf unterstützt. (15s Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219296] = {name = "[q3]Entropischer Skardynkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 604.\n[q2]Anlegen: Eure Zauber haben eine Chance, die Leerenenergie zu destabilisieren und ein verderbtes Fragment freizusetzen. Wenn Ihr ein Fragment aufnehmt, werdet Ihr kurzzeitig von seiner Macht durchdrungen, was Eure Intelligenz 15 Sek. lang um 1421 erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219297] = {name = "[q3]Glutbräukrug", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Teilt gelegentlich ein Getränk mit Verbündeten, die Euch im Kampf beistehen, das ihnen 15 Sek. lang 700 ihres Primärwertes gewährt und 19079 Schaden absorbiert. Auch Ihr nehmt einen Schluck, der 377 Hauptwert gewährt und 97936 Schaden absorbiert.\n\n Wenn Eure Gesundheit unter 50% fällt, nehmt Ihr einen Notfallschluck. Dies kann nur einmal alle 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\n[q]\"Für den Konsum niederer Sterblicher verdünnt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219298] = {name = "[q3]Gefräßiger Honigbrummer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Ruft einen unersättlichen Verbündeten herbei und reitet in den Sonnenuntergang (oder $443387rad1 Meter weit, wenn diese Strecke kürzer ist). Außerdem werden ( 1 * 149371 ) Feuerschaden zwischen allen Gegnern aufgeteilt, über die Ihr hinwegreitet. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219299] = {name = "[q3]Synergetischer Gebräuterialisator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Anlegen: Eure Zauber haben eine Chance, das Gerät aufzuladen und ein Auffüllfass in die Nähe Eures Ziels anzufordern. Wenn das Fass beschädigt wird, explodiert es und verursacht ( 1 * 84121 ) Feuerschaden, die unter den Gegnern in der Nähe aufgeteilt werden.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219300] = {name = "[q3]Skarmoraksplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Stärke\n[q2]Benutzen: Haltet den Splitter fest umschlossen, um Euch mit kristalliner Energie anzureichern und Eure Meisterschaft für 15 Sek. um 2756 zu erhöhen. (1 Min, 30 Sek. Abklingzeit)\n[q2]Anlegen: Der Splitter zieht Restenergie von besiegten Gegnern an und erhöht Eure Meisterschaft für 15 Sek. um 58 , bis zu 5-mal.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219301] = {name = "[q3]Übertakteter Zahnradbumerangwerfer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Benutzen: Wirft den überhitzten Zahnradbumerang und fügt Gegnern ( 1 * 41390 ) Flammenschlagschaden zu, wobei er an Hitze verliert, während er sie durchschneidet. (2 Min Abklingzeit)\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, die Zahnräder der Schleuder per Kurbel aufzuziehen, was deren Abklingzeit um 5 Sek. verringert und Eure Waffe aufheizt, wodurch Euer nächster Angriff ( 1 * 23306 ) zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219302] = {name = "[q3]Symphonie des Schrottsängers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Anlegen: Eure Heilfähigkeiten haben eine Chance, Metall in der Nähe dazu zu bringen, einen Schild um einen Verbündeten zu bilden, der 45216 Schaden absorbiert.\n\n Der Schild reagiert explosiv auf Feuer und fügt nahen Gegnern 4162 Feuerschaden zu, wenn er getroffen wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219303] = {name = "[q3]Zuwachs des Obersten Sprechers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 604.\n[q2]Benutzen: Lädt den Kristall auf, um einen Spalt zu beschwören, der Gegnern in der Nähe Energie entzieht und im Verlauf von 6 Sek. ( 1 * 45046 * 6) Schattenschaden verursacht.\n\n Wenn der Spalt kollabiert, kehrt die entzogene Energie zu Euch zurück, um Eure Intelligenz 20 Sek. lang um 135 zu erhöhen und für jeden getroffenen Gegnern weiter zu steigern. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219304] = {name = "[q3]Wachspfeife des Wagenführers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\n[q2]Anlegen: Eure Angriffe haben eine Chance, eine Koboldlore auf Euer Ziel zu lenken. Diese entsendet einen rasenden Trupp, der mit Gegnern zusammenstößt und ( 1 * 61010 ) körperlichen Schaden verursacht, die unter allen getroffenen Gegnern aufgeteilt werden.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\n[q]\"Die symbolische Trophäe eines Helden, denn die Kobolde müssen nicht beschworen werden, die Kobolde verzehren sich nach den Katakomben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][219305] = {name = "[q3]Verziertes Lohenzarwachs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Anlegen: Eure Zauber haben eine Chance, das Wachs zu verzaubern, um für 15 Sek. eine lodernde Kerze zu erzeugen, die Eure Vielseitigkeit um 1292 und, während Ihr in ihrem Licht bleibt, weiter um 339 erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219306] = {name = "[q3]Stichel des Kerzenkönigs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Benutzen: Schnitzt eine Wachskopie Eures Ziels, die 50% des erlittenen Schadens absorbiert. Durch die Absorption erhitzt sich das Wachs, bis es nach Absorption von 264398 Schaden schmilzt. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219307] = {name = "[q3]Fragment der Dunkelheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, die Dunkelheit zu Euch zu rufen, wodurch sich Eure Hauptwert um 281 erhöht, bis zu ( 281 * 5).\n\n Bei Erreichen voller Kraft wird die Dunkelheit entfesselt und verursacht ( 1 * 35879 * 15 / 3) Schattenschaden, die zwischen Gegnern in der Nähe im Verlauf von 15 Sek. aufgeteilt werden, bevor sie wieder in das Fragment verblasst.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219308] = {name = "[q3]Siegel des Priorats", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Erhebt Euer Siegel zum Licht und erhöht so Euren höchsten Sekundärwert 20 Sek. lang um 2756 . Eure Tat inspiriert andere Siegelträger Eurer Gruppe in der Nähe und gewährt ihnen 20 Sek. lang 73 desselben Werts. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219309] = {name = "[q3]Foliant der Hingabe des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Ihr blättert zu den 50 Versen der inneren Abhärtung weiter und lest sie, während Ihr angegriffen werdet.\n 'Innere Abhärtung' erhöht Eure Rüstung um 1438 und gewährt Euren Angriffen eine Chance, einen Schutz zu beschwören, der 67723 Magieschaden absorbiert. Sobald Ihr fertig seid, blättert Ihr zum nächsten Kapitel weiter.\n\nGilt nur für Tankspezialisierungen. (500ms Abklingzeit)\n[q2]Benutzen: Blättert mit erhöhter Strahlung durch die Textstellen des Folianten. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219310] = {name = "[q3]Explodierender Lichtsplitter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Benutzen: Beschwört eine berstende Lichtbrut, die ihre Gesundheit opfert, um Lichtstöße zu entfesseln, die 57024 Heiligschaden verursachen, der alle 2 Sekunden auf Gegner in der Nähe aufgeteilt wird, solange die Brut lebt. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219311] = {name = "[q3]Leerenpaktstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Stärke\n{[q2]Anlegen: Eure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 35361 ) Schattenschaden} verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer {Tempo 10 Sek. lang um 377 erhöht.\n\n Euer Tod beendet den Pakt und führt zu einer gewaltigen Explosion.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][219312] = {name = "[q3]Ermächtigender Kristall von Anub'ikkaj", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\n[q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, eine wachsende Ermächtigung aus dem Kristall freizusetzen, die einen zufälligen Sekundärwert 20 Sek. lang um 1392 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219313] = {name = "[q3]Mereldars Tribut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Benutzen: Entfesselt einen Tribut aus heiligem Licht auf das Ziel und fügt ihm ( 1 * 53941 ) Heiligschaden zu. Die nächsten 5 Verbündeten, die das Ziel angreifen, erhalten den 'Segen von Mereldar', was ihre Vielseitigkeit 10 Sek. lang um 658 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219314] = {name = "[q3]Kokonbrut von Ara-Kara", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 604.\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, den Kokon zu bewegen, der ein Ei freigibt, das Eure Hauptwert um 213 erhöht. Jedes Ei schlüpft nach 1 Min. Die neue Brut greift Euer nächstes Ziel an und fügt ihm im Verlauf von 8 Sek. ( 1 * 1598 * 8) Naturschaden zu. (100ms Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219315] = {name = "[q3]Aggressionsablenkungsmodul", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure Spottfähigkeiten aktivieren die brechende Energie des Moduls und schützen Euch vor 50% des erlittenen Schadens, bis zu 301603 . Dies kann nur einmal pro 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen. (1Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219316] = {name = "[q3]Endlose Schwarmdrüse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Die Drüse setzt Pheromone frei, die einen endlosen Schwarm von Insekten anlocken, die Euch umkreisen. Wenn Ihr Schaden erleidet, habt Ihr eine hohe Chance auf einen Gegenschlag, der über 6 Sek. ( 2726 * 6) Naturschaden verursacht und den Euch zugefügten Schaden um 3781 reduziert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219317] = {name = "[q3]Edikt des Ernters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\n[q2]Anlegen: Eure Schadenszauber und -fähigkeiten haben eine Chance, eine Kugel aus instabilem Schwarzblut auf Euer Ziel zuschweben zu lassen, die beim Aufprall explodiert und ( 1 * 55918 ) Schattenschaden verursacht, die zwischen allen Gegnern in der Nähe aufgeteilt werden. Wenn Ihr die Kugel abfangt, könnt Ihr deren Macht entziehen und damit Eure Meisterschaft 15 Sek. lang um 1653 erhöhen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219318] = {name = "[q3]Kehlkopf des oppressiven Orators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Eure Angriffe haben eine Chance, den Kehlkopf in Bewegung zu versetzen, sodass sein finsteres Flüstern Euch beeinflusst. Jedes Flüstern durchströmt 30 Sek. lang Euren Geist und gewährt 198 Stärke.\n[q2]Benutzen: Schwenkt den Kehlkopf in der Luft, um einen quälenden Chor zu entfesseln, der Gegnern in der Nähe im Verlauf von 3 Sek. ( 1 * 58370 * 3) Schattenschaden zufügt. Euer Flüstern schließt sich dem Chor an und erhöht den Schaden, bevor er verstummt. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219319] = {name = "[q3]Doppelfangbesteck", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\n[q2]Benutzen: Öffnet den Beutel und zückt die Schattenklinge von Nx, um schnell auf Gegner vor Euch loszugehen und allen getroffenen Gegnern ( 1 * 23075 ) Schattenschaden zuzufügen.\n\n Ihr könnt den Beutel bis zu zwei weitere Male innerhalb von 20 Sek. benutzen, bevor er sich selbst versiegelt und seinen Inhalt magisch auflädt. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219320] = {name = "[q3]Zähflüssiges Koaglam", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Anlegen: Eure überschüssige Heilung lockt Schattenenergie aus der Nähe zu Eurer Gruppe, die bis zu 8407 Heilung speichert und die Gesundheit des Ziels wiederherstellt, wenn es Schaden erleidet.\n[q2]Benutzen: Kanalisiert die Kraft des Koaglmats, indem die gesamte aktuelle Schattenenergie auf Euer Ziel konzentriert wird. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219321] = {name = "[q3]Rankendes Mixtorium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\n[q2]Anlegen: Eure Zaubersprüche können Euch dazu inspirieren, an einem Verbündeten zu experimentieren und ihn auf unvorhergesehene Weise 20 Sek. lang zu verbessern.\nVerkaufspreis:"}
