MultiLanguageItemData['de'][219385] = {name = "Lähmungsheilserum", additional_info = "Questgegenstand\n[q2]Benutzen: Verabreicht das Lähmungsheilserum einem Ziel, das durch den Trank des Strippenziehers gelähmt wurde.\n[q]\"Eine Serum zum Heilen von Lähmungen. Die Wirksamkeit kann nicht garantiert werden.\""}
MultiLanguageItemData['de'][219386] = {name = "[q4]Locus der Macht", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Locus der Macht\nKanalisiert arkane Macht für 4 Sek. Alle 0.40 Sek. werden bei Euch und 2 Verbündeten innerhalb von 50 Metern 30 Sek. lang das Tempo, der kritische Trefferwert und die Meisterschaft erhöht.\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][219387] = {name = "[q3]Fass mit Feuerwerkskörpern", additional_info = "Spielzeug\n[q2]Benutzen: Stellt ein gefährliches Fass mit Feuerwerkskörpern auf, das 5 Min. Sek. lang stehen bleibt, um für Euch und Eure Freunde den Nachthimmel grell zu erleuchten!\n\n Andere Spielercharaktere können sich das Feuerwerk auch ansehen, indem sie das Fass angreifen.\n\n Während der Feierlichkeiten von betrunkenen Goblins ist die Abklingzeit verringert. (1 Stunde Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][219388] = {name = "Fackel der Heiligen Flamme", additional_info = "Questgegenstand\n[q2]Benutzen: Bringt eine Gruppe Arathi in der Nähe durch ihren Glauben an die Heilige Flamme zusammen!\n[q]\"Die Fackel brennt hell. Das Knistern und Flackern klingt fast schon musikalisch.\""}
MultiLanguageItemData['de'][219389] = {name = "[q2]Blitzableiter", additional_info = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Eure Fähigkeiten haben eine Chance, Euer Ziel mit 'Blitzableiter' zu belegen. Der kritische Trefferwert von Verbündeten wird 10 Sek. lang erhöht und Gegner erleiden 8 Sek. lang alle 2 Sek. Naturschaden. Wenn 'Blitzableiter' abläuft, kehrt er zu Euch zurück und erhöht 10 Sek. lang Euren kritischen Trefferwert.\n80 ( 80)\n[q]\"Passt in einen Tüfteleisockel.\""}
MultiLanguageItemData['de'][219390] = {name = "[q3]Schlüsselsteinkarte festlegen: Grim Batol", additional_info = "Dauer: 12 std. (Realzeit)\n[q2]Benutzen: Legt Grim Batol als Dungeon für einen mythischen Schlüsselstein fest.\nVerkaufspreis:"}
MultiLanguageItemData['de'][219391] = {name = "[q4]Luftschiff des Tiefenforschers", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer Luftschiff des Tiefenforschers oder gibt es wieder frei.\n\n Bei diesem Transportmittel kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mit diesem Luftfahrzeug könnt Ihr Euch direkt ins Abenteuer stürzen, wo immer es auch sein mag!\"\nQuest:\nAbtauchen\nZone:\nInsel von Dorn"}
MultiLanguageItemData['de'][219392] = {name = "Flammenfluss 7000", additional_info = "Questgegenstand\n[q2]Benutzen: Holt einen Flammenwerfer hervor und verursacht 3 Sek. lang Feuerschaden in einem kegelförmigen Bereich vor Euch. Wirkt gegen die invasiven Nestbauer von Mmarl. (6 Sek. Abklingzeit)\n[q]\"Mit Gazlowes Flammenwerfer lassen sich die Käfer in der Höhle von Mmarl garantiert beeindrucken.\""}
