MultiLanguageItemData['de'][221263] = {name = "[q3]Nerubischer Giftpfeil", additional_info = "[q7]Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\n{[q2]Anlegen: Eure Distanzangriffe haben eine Chance dem Ziel ein lähmendes Gift zu injizieren, das im Verlauf von 9 Sek. ( 1 * 23329 ) Naturschaden} verursacht.\n\n Für jede Sekunde, in der sich das betroffene Ziel bewegt, erhaltet Ihr 10 Sek. lang ( 254 / 5) {Tempo. Bis zu 5-mal stapelbar.}\nVerkaufspreis:"}
MultiLanguageItemData['de'][221264] = {name = "[q3]Bündel des Fungianermystikers", additional_info = "[q7]Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure Zauber haben eine Chance, Sporen freizusetzen, die 4 Verbündeten in der Nähe für 10 Sek. 566 Meisterschaft gewähren. Alle Sporen, die keinen Wirt finden, gewähren stattdessen Euch 80% Meisterschaft.\n\n Wird dieser Effekt durch einen Naturzauber ausgelöst, wird eine zusätzliche Spore freigesetzt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][221265] = {name = "[q3]Amulett der Untergrundbestie", additional_info = "[q7]Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Eure Zauber haben eine Chance, die animalischen Erkenntnisse des Amuletts wachzurufen, die Euren kritischen Trefferwert 12 Sek. lang um 1115 erhöhen.\n\n Wenn Ihr gegen ein Tier oder an der Seite eines Tiers kämpft, ist dieser Effekt um 20% erhöht.\nVerkaufspreis:"}
