MultiLanguageItemData['de'][221871] = {name = "[q2]Prototyp: Trankbombe der Geschwindigkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der ihre Bewegungsgeschwindigkeit 20 Sek. lang um 10-15% (je nach Herstellungsqualität) erhöht.\n\n Von der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221875] = {name = "[q2]Prototyp: Trankbombe der Erholung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der die von ihnen erhaltene Heilung 12 Sek. lang um 5-10% (je nach Herstellungsqualität) erhöht.\n\n Von der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221879] = {name = "[q2]Prototyp: Trankbombe der Macht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Werft eine Trankbombe, die in ihrem Explosionsradius bis zu 5 Verbündete mit einem Trank besprüht, der deren Primärwert 30 Sek. lang um ( 2196 / 5) erhöht.\n\n Von der Explosion erfasste Gegner erleiden 67738 Feuerschaden, der zwischen ihnen aufgeteilt wird.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221903] = {name = "[q2]Prototyp: Tüftelei: Irdener Lieferbohrer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Beschwört einen irdenen Lieferbohrer, der nach verschiedenen Schlachtfeldstärkungen gräbt.\n\n Der Bohrer bleibt 28 Sek. lang aktiv und kann nur im Kampf beschworen werden. Sein Einsatz ist nur auf nicht gewerteten Schlachtfeldern und im Kriegsmodus auf Khaz Algar möglich. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221907] = {name = "[q2]Prototyp: Tüftelei: Herzsuchender Gesundheitsinjektor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Injiziert eine medizinische Frostfeuerformel in Eure Adern, die Euch durch einen Frostschock sofort um 1943637 heilt. Zur Verhinderung einer plötzlichen Unterkühlung brennt Ihr anschließend für 30% des geheilten Betrags.\n\n Teilt sich eine Abklingzeit mit Heiltränken.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221944] = {name = "[q2]Prototyp: Unwiderstehlicher roter Knopf", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\n Hält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221945] = {name = "[q2]Unwiderstehlicher roter Knopf", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Setzt ein Gerät ein, das von Euch oder einem Mitglied Eurer Gruppe bzw. Eures Schlachtzugs aktiviert werden kann, wenn eine Notlage droht. Wenn es aktiviert wird, versucht es, am Ende des Kampfes alle Verbündeten in der Nähe wiederzubeleben.\n\n Hält 1 Stunde lang an oder bis es aktiviert wird. Muss vor dem Kampf eingesetzt werden.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221948] = {name = "[q2]Prototyp: Pausierender Pylon", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\n Der Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\nBenötigt Ingenieurskunst von Khaz Algar (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][221949] = {name = "Pausierender Pylon", additional_info = "[q2]Benutzen: Platziert einen pausierenden Pylonen, der die Stoffwechselprozesse von Spielercharakteren in seiner Nähe unterbricht und den Ablauf der Fläschchen, Phiolen und Sättigungseffekte von Khaz Algar anhält.\n\n Der Pylon ist äußert zerbrechlich und explodiert in der Gegenwart von Gewalt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][221952] = {name = "[q2]Prototyp: Täuschend echte Überbrückungskabel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig: Prototyp (1)\n[q2]Benutzen: Jagt einem \"toten\" Verbündeten Angst ein, indem Ihr ihm mit einem Elektroschock droht, und holt ihn so mit 35% Gesundheit und 10% Mana ins \"Leben\" zurück. Manchmal nimmt das Ziel Eure Drohung nicht ernst.\n\n Kann im Kampf eingesetzt werden. Die Qualität des Gegenstands beeinflusst die Zauberzeit. Kann nicht von Spielercharakteren über Stufe 80 verwendet werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Khaz Algar (1)\n[q]\"Manchmal tun sie nur so.\"\nVerkaufspreis:"}
