MultiLanguageItemData['de'][221977] = {name = "[q4]Scheiterhaufen", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Scheiterhaufen\nGewährt dem Zaubernden 1 Min. lang Hauptwert.\n\n Belegt den Zaubernden alle 1 Sek. mit einem Stapel 'Scheiterhaufen', wodurch er pro Stapel Feuerschaden erleidet.\n\n 'Scheiterhaufen' wird vorzeitig entfernt, wenn der Effekt erneut aktiviert wird. (2 Min. Abklingzeit)\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
MultiLanguageItemData['de'][221982] = {name = "[q4]Bollwerk des Schwarzen Ochsen", additional_info = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Anlegen: Erlernt folgenden Zauber.\n\n Bollwerk des Schwarzen Ochsen\nKanalisiert das Bollwerk des Schwarzen Ochsen. Stürmt auf einen Gegner zu und entfernt alle Betäubungs- und Bewegungsunfähigkeitseffekte, erhaltet einen Schaden absorbierenden Schild und verspottet Gegner innerhalb von 20 Metern. Fügt Gegnern innerhalb von 20 Metern 5 Sek. lang alle 1 Sekunden körperlichen Schaden plus 20% des vom Schild erlittenen Schadens zu.\n80 ( 80)\n[q]\"Passt in einen Metasockel.\""}
