MultiLanguageItemData['de'][223264] = {name = "[q4]Wasserblaue Schwärmilbe", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 23 bei den Durchtrennten Fäden.\nBenötigt Ruhmrang 22 bei den Durchtrennten Fäden.\n\n\n[q]\"Auch wenn es nicht gerade geläufig ist, versichern Euch die Repräsentanten der Durchtrennten Fäden, dass Schwärmilben mehr als fähig sind, Euer Gewicht zu tragen, solltet Ihr auf ihnen reiten wollen.\"\nVerkäufer:\nLady Vinazian\nZone:\nAzj-Kahet\nKosten:\n3.940\n\nVerkäufer:\nY'tekhi\nZone:\nAzj-Kahet\nKosten:\n3.940"}
MultiLanguageItemData['de'][223265] = {name = "[q4]Nistende Schwärmilbe", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als natürliche Gräber lauern sie oft in kleinen Tierbauten, wenn sie Eier legen oder größere Beute überraschen wollen.\"\nZone:\nVision von Sturmwind (Neuerlebt)\nZone:\nVision von Orgrimmar (Neuerlebt)"}
MultiLanguageItemData['de'][223266] = {name = "[q4]Zügel der schattenhaften Schwärmilbe", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Schwärmilben trifft man in der Wildnis von Azj-Kahet häufig an, dazu findet man sie bei den Nerubern, die sie seit Langem zähmen, wodurch sie für unvorsichtige Abenteurer aber nicht weniger gefährlich sind.\"\nErfolg:\nRuhm des Nerub'ar-Plünderers\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageItemData['de'][223267] = {name = "[q4]Schwärmilbenhimmelsjäger", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Schwärmilbenhimmelsjäger, der normalerweise in den kleinsten Winkeln und Ritzen von Felsvorsprüngen zu finden ist, fühlt sich in der Luft wohler, als wenn er sich ausruht.\"\nErfolg:\nGlyphenjäger aus Khaz Algar\nKategorie:\nThe War Within"}
MultiLanguageItemData['de'][223269] = {name = "[q4]Maschinenverteidigungseinheit 1-11", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Einer der vielen Mechanzüge, die dazu entworfen wurden, die Maschine zu bewachen. Nach Jahren treuer Dienste ist er nicht mehr für den Kampf zu gebrauchen, ist allerdings immer noch ein beeindruckendes Transportmittel.\"\nSchatz:\nErweckte Truhe\nZone:\nSchallende Tiefen"}
MultiLanguageItemData['de'][223270] = {name = "[q4]Alunira", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Lange Zeit war die Verkörperung der Wolken auf dem Gipfel eines Blitzberges gefangen. Endlich kann ich den Wind wieder an meinem Rücken spüren.\"\nBeute von:\nZone:\nInsel von Dorn"}
MultiLanguageItemData['de'][223274] = {name = "[q4]Wilder Kieferkriecher", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 22 bei den Durchtrennten Fäden.\nBenötigt Ruhmrang 17 bei den Durchtrennten Fäden.\n\n\n\"Dieser besonders große Kieferkriecher hat die perfekte Größe zum Reiten... haltet aber lieber Hände und Füße außer Reichweite seines Mauls.\"\nVerkäufer:\nLady Vinazian\nZone:\nAzj-Kahet\nKosten:\n2.815\n\nVerkäufer:\nY'tekhi\nZone:\nAzj-Kahet\nKosten:\n2.815"}
MultiLanguageItemData['de'][223276] = {name = "[q4]Unterkrabbler der Witwe", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Ruf 'Verschwörer' bei der Weberin.\n\n\n[q]\"Kinder an der Oberfläche träumen oft vom eigenen Pony oder Wolf, wenn sie ein bestimmtes Alter erreichen. Die junge Witwe Arak'nai hatte ähnliche Ambitionen, auch wenn ihr Geschmack gemäß anderen Standards eher als eklektisch gelten dürfte.\"\nVerkäufer:\nYamas der Ernährer, Hüppi\nZone:\nAzj-Kahet\nKosten:\n2020"}
MultiLanguageItemData['de'][223278] = {name = "[q4]Erbunterkrabbler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Ruf 'Verschwörer' beim General.\n\n\n[q]\"Die Haltung von Arachniden ist eine altbewährte Tradition der Erbmächte. Auch wenn die meisten Exemplare für Transportzwecke oder als Schocktruppen eingesetzt werden, schaffen es die besten Exemplare gelegentlich auch zum Paradereittier.\"\nVerkäufer:\nYamas der Ernährer, Anub'okki, Aspirant Kiipka\nZone:\nAzj-Kahet\nKosten:\n2020"}
MultiLanguageItemData['de'][223279] = {name = "[q4]Unterkrabbler des königlichen Hofs", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Ruf 'Verschwörer' beim Wesir.\n\n\n[q]\"Abstammungsbriefe werden verwendet, um in den gehobenen Kreisen der Kaheti die Herkunft und den Wert vollblütiger Unterkrabbler nachzuweisen. Dieses Verfahren kann sich allerdings als schwieriger als gedacht herausstellen, da eben jene Unterkrabbler dafür anfällig sind, plötzlich von ihren Verwaltern verspeist zu werden.\"\nVerkäufer:\nYamas der Ernährer, Tulumun\nZone:\nAzj-Kahet\nKosten:\n2020"}
