MultiLanguageItemData['de'][224147] = {name = "[q4]Zügel des Himmelsreißers der Sureki", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Himmelsreißer war eine der brutalsten Monstrositäten, die aus Königin Ansureks Experimenten mit dem Schwarzblut der Alten Götter hervorgegangen sind.\"\nBeute von:\nKönigin Ansurek\nZone:\nPalast der Nerub'ar"}
MultiLanguageItemData['de'][224150] = {name = "[q4]Siesbarg", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Armer Kerl.\"\nWeltquest:\nTrostfliegen\nZone:\nAzj-Kahet\nZone:\nStadt der Fäden"}
MultiLanguageItemData['de'][224151] = {name = "[q4]Zügel des aufsteigenden Himmelsreißers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Himmelsreißer sind nur für die Ergebensten der Surekielite gedacht und waren wegen ihres Muts und ihrer Brutalität die Lieblinge von Königin Ansurek.\"\nBeute von:\nKönigin Ansurek\nZone:\nPalast der Nerub'ar (Mythisch)"}
