MultiLanguageItemData['de'][224777] = {name = "Schattenwerfer der Sureki", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die Neruber nutzen diese Emitter, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\""}
