MultiLanguageItemData['de'][224781] = {name = "[q4]Abyssischer Pelz", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 2 zu erhöhen.\n[q]\"Ein kleines Fellbüschel mit tief lila Färbung. Man kann damit nicht viel anfangen, aber ein so faszinierendes und seltenes Objekt findet man nicht oft.\""}
MultiLanguageItemData['de'][224782] = {name = "[q3]Messerscharfe Klaue", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 1 zu erhöhen.\n[q]\"Die kleine, aber extrem scharfe Klaue einer Kreatur. Sie ist zwar nicht groß genug, um für irgendetwas gut zu sein, ist aber ein faszinierendes Forschungsobjekt.\""}
