MultiLanguageItemData['de'][224810] = {name = "Holzwurmelixier", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Aus holzbohrenden Würmern gewonnen. In der Stadt der Fäden berühmt, obwohl es nahezu ungenießbar ist.\""}
MultiLanguageItemData['de'][224811] = {name = "[q3]Zuckerpilze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Die Fungusessenz wandelt Eure Gestalt und erhöht 30 Sek. lang das Tempo um 25%.\n\n Verwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten. (30 Sek. Abklingzeit)\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n[q]\"Kinder lieben es, nach diesen süßen Leckerbissen zu suchen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224813] = {name = "[q3]Großkatzenpfeife", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Beschwört einen großen Kampfluchs, der Euch 5 Min. lang im Kampf zur Seite steht.\n\n Verwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten. (5 Min Abklingzeit)\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n[q]\"Der größte Luchs ist immer nur ein Pfeifen entfernt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224814] = {name = "[q0]Kriegsmeutengebundene Stiefel des Abenteurers", additional_info = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n[q]\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224815] = {name = "[q3]Glücksbringer der Flamme", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Erfüllt Euch mit der Heiligen Flamme, sodass Eure Angriffe und Fähigkeiten gelegentlich einen Elementar des Lichts erschaffen, der Zielen 3 Heiligschaden zufügt.\n\n Verwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten.\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n[q]\"Der schwindende Bestand wird von den Arathor rapide ausgedünnt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224816] = {name = "[q0]Neruberischer Almanach", additional_info = "[q]\"Die Seiten sind mit kaum entzifferbaren Diagrammen und Graphen übersät. Das Einzige, was einigermaßen erkennbar ist, ist eine Zeichnung von seismischen Wellen, die ein Tunnelsystem darunter darstellen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224817] = {name = "[q3]Notizen des Algarikräuterkundigen", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 3 zu erhöhen."}
MultiLanguageItemData['de'][224818] = {name = "[q3]Notizen des Algariminenarbeiters", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Bergbauwissen von Khaz Algar um 3 zu erhöhen."}
MultiLanguageItemData['de'][224822] = {name = "[q4]Schrott durchforsten", additional_info = "[q]\"Durchforstet Schrott um Teile, vergessene Prototypen und mehr zu finden!\""}
MultiLanguageItemData['de'][224831] = {name = "[q4]Würfel der unendlichen Erfindungen (Nur PTR)", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt die Abklingzeit der Ingenieurskunst von Khaz Algar zurück.\n\n Dieser Gegenstand dient ausschließlich Testzwecken.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n[q]\"Zählt als Samophlang, was auch immer das ist.\""}
MultiLanguageItemData['de'][224835] = {name = "[q3]Tiefenhainwurzeln", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 1 zu erhöhen.\n[q]\"Die Wurzeln wachsen weiter, auch nachdem die Rose gepflückt wurde. Nicht wirklich für irgendwas zu gebrauchen, aber ein interessantes Studienobjekt.\""}
MultiLanguageItemData['de'][224837] = {name = "[q3]Verfluchte Hacke", additional_info = "[q7]Wird bis zum Ausrüsten an Kriegsmeute gebunden\n{Einhändig} {Axt}\n1,180 - 2,452 Schaden Geschwindigkeit 2.60\n(698.5 Schaden pro Sekunde)\n+614 [Beweglichkeit oder Stärke]\n+3.002 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 424.\n[q2]Erhöht Eure Tempowertung um + 170.\nHaltbarkeit 90 / 90\n[q2]Wenn dieser Gegenstand in Euren Taschen ist, ausgerüstet ist oder für eine Transmogrifikation verwendet wird, werdet Ihr gelegentlich vom Fluch verzehrt.\n[q]\"Uralte Runen verzieren den metallischen Kopf und Schwanz und folgen dem Griff in tiefen Gravuren. Die Muster werden zum Knauf hin unregelmäßiger, bis sie nur noch wildes Gekritzel sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][224838] = {name = "[q3]Nullsplitter", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Bergbauwissen von Khaz Algar um 1 zu erhöhen.\n[q]\"Ein winziger Splitter Nullstein, der eine pulsierende Aura der Leere verströmt. Er ist nicht sonderlich nützlich für Handwerksarbeiten, aber Ihr könntet mehr über Algari-Erze und -Mineralien lernen, indem Ihr ihn studiert.\""}
