MultiLanguageItemData['de'][225554] = {name = "Sonnenloser Köder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n[q]\"Vom Kopf einer Illusion gezogen, die Kobyss am Sonnenlosen Strand erscheinen ließ. Mit genug Exemplaren könntet Ihr es ihnen vielleicht mit gleicher Münze heimzahlen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][225555] = {name = "Amulett der reinen Flamme", additional_info = "Questgegenstand\n[q2]Benutzen: Tragt ein Parfüm auf, das Eure Zauber und Waffen mit heiligem Feuer verstärkt. (3s Abklingzeit) (30 Sek. Abklingzeit)\n[q]\"Nach Beledars Abbild gefertigt.\""}
MultiLanguageItemData['de'][225556] = {name = "[q3]Uraltes Konstrukt", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört am Zielort Ikarus, den Unzerbrechlichen, der 1 Min. lang bestehen bleibt. Dieser dient als Zielattrappe und kann von der jeweils entgegengesetzten Rolle geheilt werden oder Schaden durch sie erleiden, solange sie bestehen bleibt. Wie weit könnt Ihr die Zahlen steigen lassen?\n\n Kann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][225557] = {name = "Zischender Glutpollen", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q]\"Verursacht äußerst schmerzhafte Niesanfälle. Vielleicht hat die Metbrauerei Verwendung dafür.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][225558] = {name = "Trübflossenköder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n[q]\"Bei einem Kobyss gefunden, der Euch in Velhans Geltung zum Narren halten wollte. Mit genügend Teilen könntet Ihr damit das Blatt wenden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][225559] = {name = "Hungernde Schimmerflosse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n[q]\"Ihr habt diese schimmernde Schuppe einem Kobyss entnommen, der Euch mit einer Illusion im Lauernden Strudel verwirren wollte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][225560] = {name = "Nekrostab der Zornflossen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n[q]\"Den Nekromagiern der Zornflossen entwendet. Er pulsiert vor Macht. Vielleicht könnte er eine Wendung gegen die Kobyss herbeiführen.\"\nVerkaufspreis:"}
