MultiLanguageItemData['de'][225648] = {name = "[q2]Kerzenvertrauter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\n[q2]Anlegen: Eure Zauber haben eine Chance, die Kerze zum Leben zu erwecken. Beschwört einen wächsernen Verbündeten, der Euren Gegnern einheizt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][225649] = {name = "[q2]Schnelldochtkerzenhalter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: <Klasse> ist flinker, <Klasse> ist behänder, <Klasse> erweckt die Macht vom Kerzenständer. Erhöht 20 Sek. lang die Bewegungsgeschwindigkeit um 20% und das Tempo um 2365 . (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][225651] = {name = "[q2]Emblem der Schattenweberin der Kaheti", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 Intelligenz\n[q2]Anlegen: Eure schädlichen Zauber haben eine hohe Chance, mit einem dunklen Ritual zu resonieren und Magie im Emblem zu speichern.\n[q2]Benutzen: Schließt das Ritual ab und entfesselt einen grauenvollen Strahl, der Eurem Ziel ( 1 * 7162 ) Schattenschaden pro gespeicherter Magie zufügt, bis zu [ 1 * ( 7162 * 10)]. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][225653] = {name = "[q2]Entziehendes Lichtbrandzeichen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Beim Erleiden von Schaden besteht eine hohe Chance, den Angreifer mit einem Brandmal zu versehen, das 5730 Heiligfeuerschaden verursacht und Euch um 50% des verursachten Schadens heilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][225654] = {name = "[q2]Imperfektes Aufstiegsserum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+195 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Erhöht Eure Tempowertung um + 246.\n[q2]Benutzen: Trinkt aus der Phiole und steigt im Verlauf von 1,5 Sek. auf, bevor Ihr eine neue mächtigere Gestalt annehmt. Erhöht Eure Hauptwert um 778 und alle anderen Werte um 296 , aber nur für 20 Sek. (2 Min Abklingzeit)\nVerkaufspreis:"}
