MultiLanguageItemData['de'][226506] = {name = "[q4]Hand von Reshkigaal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Reshkigaal wartete ab, während ihr Volk versuchte, den Verbannten an sich zu reißen. Sie wollte angreifen, wenn er abgelenkt war, aber die Spione des Gefängniswärters hatten sie aufgespürt. Mit ihrer Warnung und Hilfe gewann der Gefängniswärter die Oberhand.\"\nHandelsposten"}
MultiLanguageItemData['de'][226507] = {name = "Spinnwebentinktur des Giftigen Dahns", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Reibt Euch mit Huschergift ein, um einen Stapel von 'Mal des Auslöschers' zu entfernen.\nErfordert den Ruf 'Kumpane' beim General.\n[q]\"Eine giftbasierte Körpertinktur, um Schmutz und Spinnweben vom Mal des Auslöschers zu entfernen. 88% natürliche Aromen!\""}
MultiLanguageItemData['de'][226508] = {name = "Einfluss des Wesirs", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ihr habt die richtigen Neruber bestochen.\n\n Wenn die Wachen Euch das nächste Mal aus der Stadt der Fäden verbannen wollen, werdet Ihr stattdessen zum königlichen Apothekarium geschickt. Dieser Effekt bleibt 60 Minuten lang bestehen.\nErfordert den Ruf 'Komplize' beim Wesir.\n[q]\"Eine Reihe \"offizieller\" Dokumente. \"Überzeugt\" die Wachen in der Stadt der Fäden davon, Euch zum Königlichen Apotheker zu bringen, wenn sie Euch erwischen.\""}
MultiLanguageItemData['de'][226509] = {name = "Einsicht des Generals", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ihr könnt den Erkennungsradius der Wachen in der Stadt der Fäden 10 Minuten lang visualisieren.\n\n Ihr habt viel vom General gelernt.\nErfordert den Ruf 'Komplize' beim General.\n[q]\"Eine Kopie der Surekipatrouillen und -methoden. Damit könnt Ihr den Erkennungsradius aller Wachen in der Stadt der Fäden sehen.\""}
MultiLanguageItemData['de'][226510] = {name = "Weberfassade", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ihr nehmt das Antlitz eines wahren Nerubers an. Wachen in der Stadt der Fäden haben nun eine Minute lang einen verringerten Erkennungsradius.\n\n Die Weberin ist meisterlich im Verkleiden.\nErfordert den Ruf 'Komplize' bei der Weberin.\n[q]\"Eine Pheromonmischung, die Wachen in der Stadt der Fäden narrt und ihren Erkennungsradius deutlich verringert. Eine Spezialität der Weber.\""}
MultiLanguageItemData['de'][226511] = {name = "Nerubimorphmaske", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Werft ein Gebräu, um eine Wache in der Stadt der Fäden 30 Sekunden lang in eine weniger bedrohliche Gestalt zu verwandeln.\n\n Ein Spezialrezept des Wesirs höchstpersönlich.\nErfordert den Ruf 'Kumpane' beim Wesir.\nErfordert den Ruf 'Kumpane' bei der Weberin.\n[q]\"Eine Mischung zum Werfen, die Opfer für kurze Zeit in harmlose Weberatten verwandelt. Funktioniert nur bei Wachen in der Stadt der Fäden.\""}
MultiLanguageItemData['de'][226512] = {name = "Schatzkarte: Vergessenes Denkmal", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Deckt den Standort eines vergessenen Denkmals auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' beim General."}
MultiLanguageItemData['de'][226513] = {name = "Schatzkarte: Kahetiausgrabung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Deckt den Standort einer Kahetiausgrabung auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' beim Wesir."}
MultiLanguageItemData['de'][226514] = {name = "Schatzkarte: Weberattenschatz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Deckt den Standort eines Weberattenschatzes auf Eurer Karte auf.\nErfordert den Ruf 'Kumpane' bei der Weberin."}
MultiLanguageItemData['de'][226515] = {name = "Gerüchtekarte: Kopfgeld", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Deckt den Standort eines Kopfgeldgerüchts auf Eurer Karte auf."}
MultiLanguageItemData['de'][226516] = {name = "Gerüchtekarte: Störung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Deckt den Standort eines Störungsgerüchts auf Eurer Karte auf."}
