MultiLanguageItemData['de'][226518] = {name = "Pheroflucht", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lässt verschiedene Pheromone implodieren, die Wachen in der Stadt der Fäden 2 Sekunden lange betäuben, damit Ihr aus dem Kampf entkommt.\nErfordert den Ruf 'Kumpane' beim Wesir.\n[q]\"Werft diese Implosion aus Pheromonen, um Gegner zu betäuben und aus dem Kampf zu fliehen. Funktioniert nur gegen Wachen in der Stadt der Fäden.\""}
MultiLanguageItemData['de'][226519] = {name = "[q3]Expertise des Generals", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Ihr könnt den Erkennungsradius der Wachen in der Stadt der Fäden visualisieren.\n\n Ihr habt viel vom General gelernt.\nErfordert den Ruf 'Kumpane' bei der Weberin, dem General oder dem Wesir.\n[q]\"Eine abgeschriebene Kopie des Kampfleitfadens, den alle Soldaten in Azj-Kahet verinnerlicht haben. Wenn sie aktiv ist, könnt Ihr den Erkennungsradius aller Wachen in der Stadt der Fäden sehen.\""}
MultiLanguageItemData['de'][226520] = {name = "Pheromone der Königin", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Die Pheromone der Königin.\n\n Wachen in der Stadt der Fäden stellen sich Euch nicht mehr in den Weg.\nErfordert den Ruf 'Strippenzieher' bei der Weberin, dem General oder dem Wesir.\n[q]\"Die Pheromone der Königin. Diskret erlangt. Wachen in der Stadt der Fäden können Euch nicht mehr entdecken.\""}
