MultiLanguageItemData['de'][228580] = {name = "Götze der brutalen Kraft", additional_info = "Rang 1/4\nWird beim Aufheben gebunden\n[q2]Benutzen: Springt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung."}
MultiLanguageItemData['de'][228581] = {name = "[q0]Antike Kuriosität", additional_info = "The War Within – Saison 1\nWird beim Aufheben gebunden\nEinzigartig\n[q]\"Schon das Halten dieses Relikts verleiht Euch das Gefühlt, flott auf den Beinen zu sein. Etwas, das die Irdenen im Anbetracht ihrer schweren Rahmen sicherlich schätzen würden.\"\nVerkaufspreis:"}
