MultiLanguageItemData['de'][228940] = {name = "[q3]Ruhestein des berüchtigten Faden", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\n Kann nur von denjenigen verwendet werden, die sich den Durchtrennten Fäden bewiesen haben.\nErfordert den Ruf 'Strippenzieher' bei der Weberin, dem General oder dem Wesir.\n[q]\"Kehrt mit der Hilfe Eurer Patrone der Durchtrennten Fäden nach Hause zurück.\""}
MultiLanguageItemData['de'][228941] = {name = "[q4]Inaktiver seltsamer Schlüssel", additional_info = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n[q2]Benutzen: Sockelt einen Edelstein in den Schlüssel.\n[q]\"Ein ramponierter alter Schlüssel. Er scheint eine Fassung für etwas zu haben.\""}
MultiLanguageItemData['de'][228942] = {name = "[q4]Großzügiger Kasten", additional_info = "80 ( 80)\n[q]\"Enthält mächtige Ausrüstung, ein strahlendes Echo, zusätzliche Währungen und eine Chance auf eine neue oder aufgewertete Kuriosität. Benötigt zum Öffnen einen restaurierten Kastenschlüssel.\""}
MultiLanguageItemData['de'][228943] = {name = "[q3]Durchtrennter Faden des Spionagemeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht dem Einsatz Eures Ruhesteins des berüchtigten Fadens einen kosmetischen Hauch der Weberin.\nErfordert den Ruf 'Strippenzieher' bei der Weberin.\n[q]\"Die Weberin entrichtet ihre besten Wünsche.\""}
