MultiLanguageItemData['de'][228945] = {name = "[q3]Durchtrennter Faden des Exekutors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Verleiht dem Einsatz Eures Ruhesteins des berüchtigten Fadens einen kosmetischen Hauch des Wesirs.\nErfordert den Ruf 'Strippenzieher' beim Wesir.\n[q]\"Der Wesir entrichtet sein höchstes Lob.\""}
MultiLanguageItemData['de'][228946] = {name = "[q3]Handwerkstisch im Nest der Weberin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nErfordert den Ruf 'Kollaborateur' bei der Weberin, dem General oder dem Wesir.\n[q]\"Bringt dies zu Ak'itaz im Nest der Weberin, um einen Handwerkstisch Eurer Wahl herstellen zu lassen.\""}
MultiLanguageItemData['de'][228947] = {name = "[q3]Handwerkstisch im Nest der Weberin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Erhaltet Zugang zu einem Handwerkstisch im Nest der Weberin."}
MultiLanguageItemData['de'][228948] = {name = "Jazz' Schrumpfstrahl", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Schockt eine Kreatur, um sie zu schwächen und sie um 50% zu schrumpfen! Hält 30 Sek. lang an.\n\n Funktioniert nur in den Glücksmomentminen. (5 Sek. Abklingzeit)\n[q]\"Die Strahlenpistole surrt in Euren Händen. Sie wirkt erstaunlicherweise stabil... und das, obwohl sie nur von rostigen Schrauben und Jazz' Hoffnungen und Träumen zusammengehalten wird.\""}
