MultiLanguageItemData['de'][229198] = {name = "Luft-Ass", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Es zeigt eine Hand, die aus einer Wolke herauskommt und ein von einer Krone umgebenes Schwert ergreift.\""}
MultiLanguageItemData['de'][229199] = {name = "Luft-Zwei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine Person mit verbundenen Augen, die zwei starke Winde auf ihren Schultern balanciert.\""}
MultiLanguageItemData['de'][229200] = {name = "Luft-Drei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt drei stürmische Windböen, die ein Herz durchbohren, mit stürmischen Wolken und Regen dahinter.\""}
MultiLanguageItemData['de'][229201] = {name = "Luft-Vier", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt das Bildnis eines Ritters in der Gebetshaltung, in voller Länge, vermutlich auf seinem Grabmal.\""}
MultiLanguageItemData['de'][229202] = {name = "Luft-Fünf", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt einen Mann, der verächtlich auf zwei zurückweichende und niedergeschlagene Gestalten herabblickt, die ihre Luftsäcke auf dem Boden liegen gelassen haben. Zwei weitere trägt er auf seiner linken Schulter, einen dritten hält er in der rechten Hand.\""}
MultiLanguageItemData['de'][229203] = {name = "Luft-Sechs", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt einen Fergen, der Passagiere in seinem Boot zum anderen Ufer bringt. Der Kurs ist ruhig, und da die Fracht leicht ist, kann man sehen, dass die Arbeit nicht überfordernd ist.\""}
MultiLanguageItemData['de'][229204] = {name = "Luft-Sieben", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine Person, die dabei ist, fünf Winde schnell wegzutragen. Zwei andere Winde liegen auf dem Boden und ein Lager ist in der Nähe.\""}
MultiLanguageItemData['de'][229205] = {name = "Luft-Acht", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt einen gefesselten Gefangenen mit verbundenen Augen, der von acht stürmischen Winden umgeben ist. Es handelt sich jedoch eher um vorübergehende Fesseln als um eine unwiderrufliche Knechtschaft.\""}
MultiLanguageItemData['de'][229206] = {name = "Feuer-Ass", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Es zeigt eine Hand, die aus einem brennenden Feuerball herauskommt und einen von Rauch umhüllten Zauberstab hält.\""}
MultiLanguageItemData['de'][229207] = {name = "Feuer-Zwei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine hochgewachsene Gestalt, die von einem Zinnendach aus über das Meer und die Küste blickt. In der rechten Hand hält sie eine Kugel und in der linken einen brennenden Stab, den sie auf der Zinne abstützt. Ein weiterer brennender Stab ist in einem Ring rechts von der Figur angebracht.\""}
MultiLanguageItemData['de'][229208] = {name = "Feuer-Drei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine ruhige, stattliche Gestalt von hinten, die von einer Klippe aus auf die über das Meer fahrenden Schiffe blickt. Drei Stäbe sind im Boden verankert, jeder mit einer Laterne, und die Figur lehnt sich leicht auf einen der Stäbe.\""}
MultiLanguageItemData['de'][229209] = {name = "Feuer-Vier", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt vier große Säulen im Vordergrund, zwischen denen eine große Girlande aus reinsten Flammen hängt. Zwei Figuren halten duftende Blumen hoch, und neben ihnen führt eine Brücke über einen Wassergraben zu einem alten Herrenhaus.\""}
MultiLanguageItemData['de'][229210] = {name = "Feuer-Fünf", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine Gruppe junger Leute, die ihre Stöcke wie beim Sport schwingen. Sie führen einen Scheinkrieg, und ihre Augen brennen wie Feuer.\""}
MultiLanguageItemData['de'][229211] = {name = "Feuer-Sechs", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine Figur auf einem Pferd, die mit einer Lorbeerkrone geschmückt ist und ein Flammenschwert führt. Sechs Lakaien mit ähnlichen Flammenschwertern stehen neben der Figur.\""}
MultiLanguageItemData['de'][229212] = {name = "Feuer-Sieben", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine entschlossene Gestalt, die hoch oben auf einem zerklüfteten Hügel steht und eine Fackel hält. Sieben weitere Fackeln werden von unten auf sie gerichtet.\""}
MultiLanguageItemData['de'][229213] = {name = "Feuer-Acht", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt acht flammende Pfeile, die über den Himmel fliegen und sich dem Ende ihrer Bahn nähern. Das, wofür sie stehen, rückt in greifbare Nähe - vielleicht steht es sogar schon vor der Tür.\""}
MultiLanguageItemData['de'][229214] = {name = "Frost-Ass", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Es zeigt eine Hand, die aus dem frisch gefallenen Schnee herauskommt und den Schaft eines mit dampfendem Wasser gefüllten Kelches umklammert.\""}
MultiLanguageItemData['de'][229215] = {name = "Frost-Zwei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt zwei junge Leute, die in einer Winterlandschaft stehen und sich mit Fahnen aus reinstem Eis gegenseitig anstoßen.\""}
MultiLanguageItemData['de'][229216] = {name = "Frost-Drei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt Feiernde, die mit erhobenen Bechern in einem Garten tanzen, als würden sie sich gegenseitig etwas versprechen. Sanfter Schnee fällt um sie herum.\""}
MultiLanguageItemData['de'][229217] = {name = "Frost-Vier", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine in Pelze gehüllte Gestalt, die unter einer Tanne sitzt und drei Kelche betrachtet, die vor ihr im Schnee liegen. Ein Arm, der aus einer Wolke herausragt, bietet der Figur einen vierten Kelch an. Ihr Gesichtsausdruck verrät Unzufriedenheit.\""}
MultiLanguageItemData['de'][229218] = {name = "Frost-Fünf", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine dunkle, verhüllte Gestalt, die von der Seite auf drei liegende Becher blickt, die in Wasserbecken ruhen. Zwei weitere Becher stehen hinter der Figur auf Sockeln aus Eis. Im Hintergrund führt eine Brücke zu einem kleinen Bergfried.\""}
MultiLanguageItemData['de'][229219] = {name = "Frost-Sechs", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt Kinder in einem alten Garten, die mit Bechern voller schmelzendem Schnee Blumen gießen.\""}
MultiLanguageItemData['de'][229220] = {name = "Frost-Sieben", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt seltsame Visionen, die sich aus sieben Kelchen aus reinstem Eis ergießen. Aber diese Bilder sind die eines fantastischen Geistes.\""}
MultiLanguageItemData['de'][229221] = {name = "Frost-Acht", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine niedergeschlagene Figur, die weggeht und die Schalen ihres Glücks, ihres Unternehmens, ihrer Unternehmung oder ihres früheren Anliegens zurücklässt, um vom eindringenden Eis verschlungen zu werden.\""}
MultiLanguageItemData['de'][229222] = {name = "Erd-Ass", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Es zeigt eine Hand, die aus dem felsigen Boden in einer Staubwolke herauskommt und eine Steinscheibe hochhält.\""}
MultiLanguageItemData['de'][229223] = {name = "Erd-Zwei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt ein Kind, das mit einer Steinscheibe in jeder Hand tanzt. Die Scheiben sind durch die endlose Schnur verbunden, die wie die umgekehrte Zahl 8 aussieht.\""}
MultiLanguageItemData['de'][229224] = {name = "Erd-Drei", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt einen Bildhauer bei der Arbeit in einem Kloster. Der Lehrling hat seine Belohnung erhalten und ist nun ernsthaft an der Arbeit.\""}
MultiLanguageItemData['de'][229225] = {name = "Erd-Vier", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine gekrönte Gestalt mit einer Steinscheibe über dem Kopf, die mit Händen und Armen eine weitere Scheibe umklammert und zwei weitere Scheiben unter den Füßen hat. Sie hält an dem fest, was sie hat.\""}
MultiLanguageItemData['de'][229226] = {name = "Erd-Fünf", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt zwei Bettler in einem Staubsturm, die an einem Fenster vorbeigehen, das von fünf glühenden Steinscheiben erleuchtet wird.\""}
MultiLanguageItemData['de'][229227] = {name = "Erd-Sechs", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine Person in der Kluft eines Händlers, die Geld auf einer Waage abwiegt und an die Bedürftigen und Notleidenden verteilt. Es ist ein Zeugnis vom Erfolg im Leben, aber auch der Herzensgüte.\""}
MultiLanguageItemData['de'][229228] = {name = "Erd-Sieben", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt eine junge Person, die sich auf ihren Stab lehnt und sieben steinerne Scheiben betrachtet, die an einem Haufen Grün zu ihrer Rechten hängen. Man könnte sagen, dass es sich um Schätze handelt, an dem ihr Herz hängt.\""}
MultiLanguageItemData['de'][229229] = {name = "Erd-Acht", additional_info = "Fortunakartenset des Dunkelmond-Jahrmarkts\n[q]\"Sie zeigt einen Künstler in Gestein bei der Arbeit, die er in Form von Trophäen ausstellt.\""}
