MultiLanguageItemData['de'][231064] = {name = "[q3]Wegwerfverkleidung für Gangster", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Verkleidet Euch als echten Halunken aus Lorenhall, damit die Einheimischen Euch fürchten und 20 Min. lang in Ruhe lassen. Kann nur in Lorenhall eingesetzt werden. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][231089] = {name = "Korrespondenz von Zirdo", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein Brief von Zirdo, in dem er Pamsys Beteiligung an der Öffnung der Wand beschreibt, die die Aufmerksamkeit von Gallywix' Schwarzblutabbau erregt hat. Beweist, dass Zirdo Pamsy verraten hat, was zum Angriff von Gozzic auf ihre Ingenieure geführt hat.\""}
MultiLanguageItemData['de'][231099] = {name = "[q3]Umschnallrakete", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Anweisungen\n Schritt 1: Rakete auf den Rücken schnallen\n Schritt 2: Rakete zünden\n Schritt 3: Abheben\n\n Kann nur in Lorenhall benutzt werden. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][231116] = {name = "[q4]Verfluchter Piratenschädel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke]\n[q2]+ 565 Lebensdiebstahl\n[q2]Anlegen: Eure Nahkampfangriffe haben eine Chance, eine Blutnova aufzurühren, die 5 Gegnern innerhalb von 5 Metern um Euch 8 Sek. lang pro Sekunde 15514 Schattenschaden zufügt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][231117] = {name = "[q4]Kugel des Nachtflutwellenbeugers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Intelligenz]\n[q2]Anlegen: Eure Distanzzauber und -fähigkeiten haben eine Chance, einen Batzen Wasser auf einen Gegner zu schleudern, der diesem sowie vier weiteren Gegnern innerhalb von 7 Metern um ihn 76721 Frostschaden zufügt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][231118] = {name = "[q4]Sturmgebundene Rune des Runenmagiers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Alle 6 Sek. im Kampf wird die Rune überladen und trifft einen Gegner in der Nähe mit einem Blitz, der 55239 Naturschaden verursacht.\n\n Dieser Effekt wird sofort ausgelöst, wenn eine Kreatur zum ersten Mal getroffen wird.\nVerkaufspreis:"}
