MultiLanguageItemData['de'][231163] = {name = "Umfunktionierte azerothische Kamera", additional_info = "Questgegenstand\n[q2]Benutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n[q]\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\""}
MultiLanguageItemData['de'][231164] = {name = "Goblingreifkette", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft den Greifhaken nach einem Schrotternter innerhalb von 40 Metern und zieht ihn zu Euch. (5 Sek. Abklingzeit)\n[q]\"So holt man fliegende Roboter aus der Luft. Mit Haken, Schnur und Angelblei.\""}
MultiLanguageItemData['de'][231173] = {name = "[q4]Magnetomech des Schrottmaestros", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Gut dafür geeignet, Müll in rollbare Ballen zu pressen. Laut Schrottmaestroapokryphen, sollen sich daraus eigene Welten entwickeln, wenn sie nur groß genug werden.\"\nErfolg:\nRuhm des Schlachtzüglers der Befreiung von Lorenhall\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageItemData['de'][231263] = {name = "Der Fall der abergläubischen und hungrigen Piraten", additional_info = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n[q]\"Notizen, in denen meine Abenteuer aufgeführt werden, wie ich den Bukanieren von Beutebucht in Zeiten der Not zu Hilfe kam.\"\n[q2]<Zum Lesen rechtsklicken>"}
