MultiLanguageItemData['de'][231756] = {name = "[q4]Funke des Sternenlichts", additional_info = "The War Within – Saison 3\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\n[q2]Gewährt die folgende Eigenschaft: Legt die Startgegenstandsstufe je nach Fertigungsqualität (678-691) fest und markiert den Gegenstand als 'Sternenlichtgefertigt'.\n[q]\"Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\""}
MultiLanguageItemData['de'][231757] = {name = "[q4]Gesplitterter Funke des Sternenlichts", additional_info = "The War Within – Saison 3\nWird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 2 gesplitterte Funken des Sternenlichts mit 250 Tapferkeitssteinen, um einen Funken des Sternenlichts zu erschaffen.\nHandwerksmaterial\n[q]\"Ein Fragment eines Funken des Sternenlichts, der wiederhergestellt werden kann, wenn er mit einem anderen Stück kombiniert wird. Hauptsächlich erhalten durch wöchentliche Truhen.\"\nVerkaufspreis:"}
