MultiLanguageItemData['de'][232991] = {name = "[q4]Die Lied des Wellenbrechers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört die Lied des Wellenbrechers oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Es kommt selten vor, dass ein Matrose genau das Monster, das ihn zum Sterben zurückgelassen hat, an den Bug seines Schiffes schnitzt. Wir sind ein mickriger und gotteslästerlicher Haufen. Dass einer von uns sich herablässt, eine solche Kreatur zu würdigen, grenzt an Wahnsinn.\"\nZone:\nSireneninsel\nErfolg:\nEine denkwürdige Insel"}
MultiLanguageItemData['de'][232992] = {name = "Große Käferteile", additional_info = "Questgegenstand\n[q2]Benutzen: Teilt ein großes Käferteil in 5 kleinere Käferteile. Sehr schade, dass Rhubarn nicht spezifiziert hat, wie groß die Käferteile sein müssen. So ein Pech aber auch.\n[q]\"Eine sehr fleischige und schleimige Portion Käferfleisch.\""}
MultiLanguageItemData['de'][233006] = {name = "[q3]Behälter mit hochprofitablem Schlick", additional_info = "[q]\"Das Zeug riecht merkwürdig und schwappt im Behälter hin und her. Lasst ihn lieber nicht fallen.\""}
