MultiLanguageItemData['de'][233240] = {name = "[q4]Polly Roger", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n\n\n Bei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Als Geißel der ungefähr nordöstlichen See können Riesenpapageien wie Polly bis zu 2.000 Jahre alt werden. Was für ein wunderbarer Fluch für Eure Nachkommen.\"\nBesonderes Ereignis:\nPlunderstorm"}
MultiLanguageItemData['de'][233241] = {name = "[q4]Hakenkralle", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n\n\n Bei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Hakenkralle segelte einst mit den Blutsegelbukanieren und später auch mit den Schwarzmeerräubern, verließ sie jedoch, um zu sehen, welche Beute sich abseits der hohen See finden lässt.\"\nBesonderes Ereignis:\nPlunderstorm"}
MultiLanguageItemData['de'][233242] = {name = "[q4]Königliche Meerfeder", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Riesenpapagei oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die scharfen Schnäbel dieser Papageien sind in der Lage, große Nüsse mit Leichtigkeit zu knacken.\"\nBesonderes Ereignis:\nPlunderstorm"}
MultiLanguageItemData['de'][233243] = {name = "[q4]Silberner Gezeitenhengst", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der Gezeitenhengst und seine silbrigen Schuppen wurden von dem Glitzern der Beute in Eurer Tasche angezogen.\"\nBesonderes Ereignis:\nPlunderstorm"}
