MultiLanguageItemData['de'][233487] = {name = "Pheromonzerstäuber", additional_info = "Questgegenstand\n[q2]Benutzen: Sprüht einen penetranten Duft auf alles vor Euch. (3 Sek. Abklingzeit)\n[q]\"Wird verwendet, um Pheromone auf die Kreaturen in der Oase zu sprühen. Nicht zur Anwendung am eigenen Körper.\""}
