MultiLanguageItemData['de'][234273] = {name = "[q3]Ein verdunkelter Kristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n[q]\"Dieser kalte und dunkle Kristall erwacht durch Eure Berührung zum Leben. Ein blasses, dunkelblaues Glühen geht von ihm aus. Ihr könnt einen leisen Gesang in Eurem Inneren hören.\""}
MultiLanguageItemData['de'][234274] = {name = "[q3]Bauplan: 22H-Rennreifen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man 22H-Rennreifen herstellt.\nBenötigt Ingenieurskunst von Khaz Algar (25)\nBenötigt Ingenieurskunst von Khaz Algar und Ruhmrang 5 bei den Kartellen von Lorenhall.\nVerkaufspreis:"}
MultiLanguageItemData['de'][234281] = {name = "[q3]Kartellarbeit Lorenhall", additional_info = "[q]\"Euer ausgewähltes Kartell wird Eurer Kriegsmeute in dieser Woche Weltquests und andere Aktivitäten zuweisen.\""}
MultiLanguageItemData['de'][234282] = {name = "[q2]Dekorativer Gartenflamingo", additional_info = "[q2]Benutzen: Stellt einen dekorativen Gartenflamingo auf, um sofort für ein lockeres Ambiente zu sorgen. (5 Min Abklingzeit)\n[q]\"Damit habt Ihr immer ein bisschen Flamingoflair dabei.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][234287] = {name = "Strahlender Fokus", additional_info = "[q2]Benutzen: Versucht, die heiligen Energie darin auszulegen.\n[q]\"Ein schwaches Licht glimmt in diesem strahlendem Überbleibsel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][234326] = {name = "[q3]Kernwiederverwertungseinheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Fügt dem Behälter für jeden getöteten Gegner einen Energiekern hinzu, bis maximal 20 Kerne.\n[q2]Benutzen: Verbraucht alle gespeicherten Energiekerne, um eine Woge aus heilender Energie durch Euren Körper zu senden. Heilt Euch sofort um 1239269 Gesundheit sowie im Verlauf von 10 Sek. zusätzlich um 53111 Gesundheit pro verbrauchtem Kern. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][234327] = {name = "[q3]Turbulentes Fragment", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 3 turbulente Fragmente zu einem turbulenten Runenschlüssel.\n[q]\"Selbst in zerschmettertem Zustand vibriert der Stein vor unerschöpflicher Energie. Er dreht und wendet sich kontinuierlich in Euren Taschen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][234328] = {name = "[q3]Strömendes Fragment", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 7 strömende Fragmente zu einem strömenden Runenschlüssel.\n[q]\"Auch wenn der Stein scheinbar leblos ist, wird Euer Verstand beim Betrachten mit Bildern weiter Ozeane gefüllt. Meere mit unergründlichen Tiefen. Der Gedanke an die Ausmaße all dessen ist überwältigend und eine Welle der Furcht fährt durch Euren Körper.\"\nVerkaufspreis:"}
