MultiLanguageItemData['de'][235532] = {name = "[q2]Experimenteller Goblin-Treibstoffzuschlag", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Verringert die maximale Gesundheit um 50% und verleiht einen zufälligen Kampfbonus.\n\n Kann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist. (5 Min Abklingzeit)\n[q]\"Verfallsdatum: 'Seid Ihr etwa ein Drückeberger?'\""}
MultiLanguageItemData['de'][235533] = {name = "[q2]Autobewerberprototyp", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Platziert den Autobewerber, der alle Kreaturen in der Nähe extrem anwidert, wodurch sie Euch 3 Min. lang 50% mehr Schaden zufügen.\n\n Kann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist. (5 Min Abklingzeit)\n3 Aufladungen\nErfordert einen freundlichen Ruf beim Kartell der Düsternisverschmolzenen in Lorenhall.\n[q]\"Wird mit einer minimalen Anzahl von Werbung geliefert. Macht EURE persönliche Marke stilvoll bekannt!\""}
MultiLanguageItemData['de'][235534] = {name = "[q2]Elektropunkturtestmodell", additional_info = "[q7]Wird an Kriegsmeute gebunden\n{[q2]Benutzen: Das Ziel wird von belebender Spannung durchströmt, was 3 Min. lang sein {Tempo um 20% erhöht, den erlittenen Schaden um 25% verringert und es Naturschaden} pulsieren lässt.\n\n Kann bei den meisten seltenen Kreaturen in Lorenhall eingesetzt werden. Ziele lassen zusätzliche Marktforschung für alle Spielercharaktere fallen, während dieser Effekt aktiv ist. (10 Min Abklingzeit)}\n3 Aufladungen\nErfordert einen wohlwollenden Ruf beim Kartell der Düsternisverschmolzenen in Lorenhall.\n[q]\"Ihr wollt mehr Stress und Anspannung in Eurem Leben? Gesucht, gefunden!\""}
MultiLanguageItemData['de'][235535] = {name = "[q2]Diskret verpackte Erfindung", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q]\"Die besten Lösungen sind Düsternisverschmolzene Lösungen. Moment, das ist ein echt fescher Slogan! Gleich aufschreiben!\""}
MultiLanguageItemData['de'][235546] = {name = "Zerfledderte Tagebuchseite", additional_info = "Questgegenstand\n[q]\"Die Seite ist kaum leserlich und stark verwittert. Das Tagebuch scheint lange den Elementen ausgesetzt gewesen zu sein.\""}
MultiLanguageItemData['de'][235548] = {name = "[q4]Vorrat der irdenen Landratte", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält ein Ausrüstungsstück des Champions.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][235549] = {name = "[q4]Karmesinroter Schredderpanzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Experimenteller Schredder, der mehr zum Töten und weniger zum Holzfällen entworfen wurde.\"\nErfolg:\nSchlüsselsteinmeister von The War Within: Saison 2\nKategorie:\nDungeons"}
MultiLanguageItemData['de'][235554] = {name = "[q4]Mitternachtschwarzes Dunkelmondstreitross", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer mitternachtschwarzes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\nHandelsposten"}
MultiLanguageItemData['de'][235555] = {name = "[q4]Lebhaftes Dunkelmondstreitross", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer lebhaftes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"In zerfledderte Zirkusbanner gehüllt, ist dieses schauerliche Reittier die perfekte Mischung aus Schatten und Spektakel.\"\nHandelsposten"}
MultiLanguageItemData['de'][235556] = {name = "[q4]Violettes Dunkelmondstreitross", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer violettes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses Ross trägt die Rätselhaftigkeit und Magie des Dunkelmondjahrmarkts in sich.\"\nHandelsposten"}
