MultiLanguageItemData['de'][235700] = {name = "[q4]Zügel des leerenvernarbten Greifs", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen leerenvernarbten Greif beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Von seinen Haltern verlassen, suchte der leerenvernarbte Greif nach allerlei übrigen Nahrungsquellen, von denen die meisten jedoch von der Leere verdorben waren. Jetzt, wo sie von der Leere genährt werden, landen sie nur, wenn ihr wankelmütiger Appetit von Nahrung angeregt wird, an die sie sich wohlwollend erinnern.\"\nBeute:\nLeerenvernarbter Greif\nZone:\nVision von Sturmwind (Neuerlebt)"}
MultiLanguageItemData['de'][235701] = {name = "Zerfallendes Konstruktionsset für einen Mechaverschrotter", additional_info = "Dauer: 1 tag (Realzeit)\n[q2]Benutzen: Erstellt einen mechanischen Schrottbot, der Ausrüstung repariert und fast alles kauft. Nach 5 Min. verschwindet er. (15 Min Abklingzeit)\n[q]\"Aufgrund ihrer unsachgemäßen Verpackung verlieren die Komponenten dieses Sets laufend an Energie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][235703] = {name = "Noggenfoggers Zwergenauslese", additional_info = "[q2]Benutzen: Werdet etwas kleiner. Bis zu 10-mal stapelbar.\n[q]\"Garantiertes Schrumpfen! Jetzt auf ex trinkbar!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][235704] = {name = "Noggenfoggers Riesenauslese", additional_info = "[q2]Benutzen: Werdet etwas größer. Bis zu 10-mal stapelbar.\n[q]\"Seid Ihr es leid, von oben herab behandelt zu werden? Jetzt auf ex trinkbar!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][235705] = {name = "[q4]Zügel des leerenvernarbten Hengstes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Geschmiedet wie einst die Eisen an ihren Hufen, handelt es sich bei diesen Kreaturen nun weniger um Pferde sondern mehr um Leerenenergie in ihrer Gestalt.\"\nBeute:\nLeerengeschmiedeter Hengst\nZone:\nVision von Sturmwind (Neuerlebt)"}
MultiLanguageItemData['de'][235706] = {name = "[q4]Harnisch der leerenvernarbten Rudelmutter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Im Kampf gegen ihre verdorbenen Halter konnte diese Rudelmutter sich und ihre Welpen befreien. Doch Freiheit von ihren Haltern bedeutete noch lange keine Freiheit von der Leere dieses verlorenen Ortes. Sie brachte ihren Welpen bei, zu noch gefährlicheren Bestien zu werden. Nun durchstreifen sie Orgrimmar auf der Suche nach Futter, während alle ums Überleben kämpfen.\"\nBeute:\nLeerenvernarbte Rudelmutter\nZone:\nVision von Orgrimmar (Neuerlebt)"}
MultiLanguageItemData['de'][235707] = {name = "[q4]Zügel des leerenvernarbten Windreiters", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man einen leerenvernarbten Windreiter beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als die Leerenenergien entfesselt wurden, verfielen die meisten Windreiter in Raserei, wobei sie sich gegenseitig und ihre Ausbilder töteten. Die Tore zu ihrem Horst wurden von den Überlebenden verschlossen. Oben kann man noch einige der überlebenden Windreiter gleiten sehen, doch niemand traut sich, in ihr neues, tödliches Zuhause zurückzukehren, um zu sehen, was davon übrig ist.\"\nBeute:\nLeerenvernarbter Windreiter\nZone:\nVision von Orgrimmar (Neuerlebt)"}
MultiLanguageItemData['de'][235709] = {name = "[q4]Ny'alothischer Schattenwurm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört Euren ny'alothischen Schattenwurm oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Als Überrest der Vergangenheit des Schwarzen Imperiums kehren diese Vorläufer der Kluftwürmer mit dem Aufstieg von Ny'alotha wieder zurück.\"\nErfolg:\nMeister der VisionenKategorie:\nNeuerlebte Visionen von N'Zoth"}
MultiLanguageItemData['de'][235710] = {name = "Noggenfoggers Frischeauslese", additional_info = "Wird beim Aufheben gebunden\nVölker: Goblin\n[q2]Benutzen: Wird vorübergehend kalt.\n[q]\"Tragt die neueste Mode, esst in den schicksten Restaurants und trinkt die angesagtesten Tränke!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][235711] = {name = "[q4]Verderbnis der Aspekte", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört die Verderbnis der Aspekte oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Erfolg \"Gemeinsame Erinnerungen\", bei dem alle Aufwertungen für das Stundenglas der verstörenden Visionen freigeschaltet werden müssen.\n\n\n[q]\"Mit N'Zoths Triumph wird das, was mit Galakrond begann, endlich Wirklichkeit. Und mit dem Verschwinden der Aspekte ist das Verderben ihrer Spezies vollbracht.\"\nVerkäufer:\nTorie\nZone:\nDornogal\nKosten:\n40.000"}
MultiLanguageItemData['de'][235712] = {name = "[q3]Leerenkristallpanther", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\n[q2]Beschwört einen reitbaren Leerenkristallpanther oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Obwohl viele kostbare Edelsteine in verstörenden Visionen von den Leerenenergien verderbt wurden, können Juwelierskunstmeister sie immer noch verwenden, um mächtige Pantherrösser herzustellen.\"\nBeruf:\nJuwelierskunst"}
MultiLanguageItemData['de'][235713] = {name = "Seltsamer Sand", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Esst mich.\n[q]\"Bodensatz von Noggenfoggers Auslese. Muss Teil des Rezepts sein.\""}
