MultiLanguageItemData['de'][236852] = {name = "[q4]Überfliegerkawummstein des Garbagio", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Erfüllt Eure Rüstung mit einem schwachen Echo der Macht des Überfliegers des Garbagio, um zusätzliche optische Effekte für bestimmte Klassensetvorlagen der Befreiung von Lorenhall freizuschalten.\n\n Dieser Effekt gilt für die gesamte Kriegsmeute."}
MultiLanguageItemData['de'][236854] = {name = "Trank des mysteriösen Großbrands", additional_info = "[q2]Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel dieses anzuzünden.\n\n Hält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht."}
MultiLanguageItemData['de'][236856] = {name = "Trank des mysteriösen Systemschocks", additional_info = "[q2]Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel diesem einen Schock zu verpassen. Geschockte Kreaturen erleiden einen regelmäßigen Betäubungseffekt.\n\n Hält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht."}
