MultiLanguageItemData['de'][237268] = {name = "Wie man sich regelmäßig vor Strafzetteln drückt", additional_info = "Einzigartig\n[q]\"Ein abgenutzter Juristikfoliant. Enthält Weisheiten und Verfahren dazu, wie man sich in Lorenhall erfolgreich vor Strafzetteln drückt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][237276] = {name = "Runderneuerter Raketengleiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Schießt Euch in die Luft und gleitet sanft zu Boden. Kann nur im Freien in Lorenhall verwendet werden. (3 Min Abklingzeit)\n[q]\"Das Etikett mit dem Warnhinweis ist angebrannt und lässt sich nicht lesen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][237305] = {name = "[q0]Kalkiger Shungit", additional_info = "[q]\"Ich verstehe es nicht. Es ist nur ein Haufen Steine.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][237306] = {name = "[q2]NEUES goblinisches heißes Eisen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Versucht, das NEUE goblinische heiße Eisen einem verbündeten Spielercharakter zuzuwerfen. Falls er Platz in seinem Rucksack hat, wird er es fangen... vorausgesetzt, Ihr könnt es sicher werfen! (2 Sek. Abklingzeit)\n[q]\"Brandneues Gefühl, gleiche alte Gefahr!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][237313] = {name = "[q0]Definitiv legitimes Samophlang", additional_info = "[q]\"110% authentisches Samophlang aus Lorenhall, das auf keinen Fall aus einem Müllhaufen gefischt wurde. Der Rauch und die Funken sind ganz normal!\"\nVerkaufspreis:"}
