MultiLanguageItemData['de'][237746] = {name = "[q6]Kriegsschwerter der Valarjar", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigtFurorkrieger\n[q]\"Helyas Verrat wird nie vergeben werden. Lasst sie unter den Wellen verrotten, fern der Hallen der Tapferkeit.\""}
MultiLanguageItemData['de'][237747] = {name = "[q6]Kriegsschwerter der Valarjar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigtFurorkrieger\n[q]\"Eigentlich ist es ihre Macht, die diese Waffen wahrhaft außergewöhnlich macht. Ihre Macht und ihr Hass treffen endlos auf Odyns Geist. Der Spannung zwischen diesen Energien durchdringt ewiglich diese Klingen...\""}
MultiLanguageItemData['de'][237748] = {name = "[q6]Schuppenstachel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigtSchutzkrieger\n[q]\"Von hier entspringt die wahre Stärke. Aus tiefen Orten... in der Welt und in Euch selbst.\""}
MultiLanguageItemData['de'][237749] = {name = "[q6]Schuppe des Erdwächters", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigtSchutzkrieger\n[q]\"Es war eine von Neltharions abgeworfenen Schuppen. Sie rettete Magnar das Leben. Der Strahl der Flamme teilte sich um die schwarze Schuppe, doch die Wucht selbst beförderte Magnar aus dem Hort und ließ ihn den Hang des Hochbergs hinunterrollen.\""}
