MultiLanguageItemData['de'][238897] = {name = "[q4]Frühlingsigel der Ernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Das Frühlingsschwein der Ernte hat früh morgens am meisten Energie. Es verbringt den Großteil des Tages damit, nach Futter zu schnüffeln oder nach anderen Ernteschweinen zu rufen.\"\nHandelsposten"}
MultiLanguageItemData['de'][238900] = {name = "[q4]Sommerigel der Ernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der Sommerigel der Ernte genießt es, einfach in der Sonne zu liegen oder in klarem Wasser zu schwimmen. Es zeigt hervorragende Leistungen bei der Nahrungssuche, doch es muss erst mal dazu überredet werden.\"\nHandelsposten"}
MultiLanguageItemData['de'][238901] = {name = "[q4]Winterigel der Ernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der Winterigel der Ernte ist hauptsächlich nachtaktiv. Es ist etwas langsamer als andere Ernteigel, doch seine Ausdauer ist unübertroffen.\"\nHandelsposten"}
MultiLanguageItemData['de'][238902] = {name = "[q4]Herbstigel der Ernte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Der Herbstigel der Ernte ist beim Erschnüffeln von Futter in kühleren Monaten nicht zu übertreffen. Sein ausgeprägter Geruchssinn macht es zu einem exzellenten Begleiter, wenn man in bewaldeten Gebieten auf Nahrungssuche geht, doch aromatischere Umgebungen könnten zum Problem werden.\"\nHandelsposten"}
MultiLanguageItemData['de'][238903] = {name = "Umfunktionierte azerothische Kamera", additional_info = "Questgegenstand\n[q2]Benutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n[q]\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\""}
MultiLanguageItemData['de'][238904] = {name = "Animasauger", additional_info = "Questgegenstand\n[q2]Benutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\n Kann beim Zaubern laufen. (3 Sek. Abklingzeit)\n[q]\"Anscheinend gibt es im hinteren Bereich ein Portal, das direkt nach K'aresh führt. Man hat Euch versichert, dass es sicher ist. Wahrscheinlich.\""}
