MultiLanguageItemData['de'][238909] = {name = "Animasauger", additional_info = "Questgegenstand\n[q2]Benutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\n Kann beim Zaubern laufen. (3 Sek. Abklingzeit)\n[q]\"Hat ein Portal auf der Rückseite der Waffe. Früher führte es nach K'aresh, aber wer weiß schon, wohin jetzt? Zumindest nicht hierher.\""}
MultiLanguageItemData['de'][238910] = {name = "Lasso", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Fängt einen ruhigen Nekrorochen mit dem Lasso, damit Ihr ihn für eine medizinische Untersuchung und Vitamine herbringen könnt. (6 Sek. Abklingzeit)\n[q]\"Ein zu einem Lasso gebundenes Seil. Nichts Ausgefallenes.\""}
MultiLanguageItemData['de'][238911] = {name = "Pheromonzerstäuber", additional_info = "Questgegenstand\n[q2]Benutzen: Sprüht einen penetranten Duft auf alles vor Euch. (3 Sek. Abklingzeit)\n[q]\"Wird verwendet, um Pheromone auf die Kreaturen in der Oase zu sprühen. Nicht zur Anwendung am eigenen Körper.\""}
MultiLanguageItemData['de'][238912] = {name = "Einlullender Pfeil", additional_info = "Questgegenstand\n[q2]Benutzen: Verschießt einen Betäubungspfeil auf Euer Ziel, der es in seligen Tiefschlaf versetzt.\n[q]\"Betäubt alles, das er trifft, indem er vorübergehend das spirituelle Netz unterbricht. Nicht-invasiv und schmerzfrei. Offenbar ein üblicher Streich, den man ahnungslosen Freunden spielt.\""}
MultiLanguageItemData['de'][238913] = {name = "Kondensationsscheibe", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft eine Scheibe, um Kreaturen auf tragbare Größe zu schrumpfen.\n[q]\"Kann geworfen werden, um Kreaturen auf eine tragbare Größe zu schrumpfen.\""}
MultiLanguageItemData['de'][238914] = {name = "Hemets besänftigende Flöte", additional_info = "Questgegenstand\n[q2]Benutzen: Besänftigt aufgebrachte Schlangen in der Oase in einem 30-Meter-Umkreis um Euch. (5 Sek. Abklingzeit)\n[q]\"Die Schlangen sind unruhig. Ihr müsst sie mit Euren fantastischen Flötenkünsten besänftigen.\""}
