MultiLanguageItemData['de'][241632] = {name = "[q0]Heroische Wachsfigur", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein liebevoll geschnitzter und vorsichtig geformter Wachsklumpen, den Skibbles nach Euch modelliert hat. Man erkennt, wie viel Arbeit sie hineingesteckt hat. Was man nicht erkennt, ist, wo das Gesicht sein soll.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][241633] = {name = "[q0]Winzige Dekorakete", additional_info = "Wird beim Aufheben gebunden\n[q]\"Wenn die kleine Kurbel gedreht wird, macht die Miniaturrakete ein leises, surrendes Geräusch und eine hölzerner Auspuffflamme beginnt sich sanft zu drehen. Eine einfache Darstellung eines kleinen Nerubers mit einer Strichfigur wurde in eine der Finnen der Rakete geritzt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][241635] = {name = "[q0]Lückenhaftes Quadrat aus Spinnenseide", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieses kleine, schlecht gewobene Quadrat scheint Muster sowohl der Neruber als auch der Arathi darzustellen. Eure Initialen wurden grob in die Ecke genäht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][241636] = {name = "[q0]Sturmglas und Federhalskette", additional_info = "Wird beim Aufheben gebunden\n[q]\"Eine einzelne, stahlblaue Sturmkrähenfeder baumelt sanft zwischen zwei Fragmenten aus Sturmglas. Eine kleine, rostige, in Lorenhall gefertigte Schraube und Mutter dienen als Schnalle.\"\nVerkaufspreis:"}
