MultiLanguageItemData['de'][242391] = {name = "[q4]Umarmung der Seelenbinderin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4.469 [Beweglichkeit oder Stärke]\n[q2]Benutzen: Aktiviert den Seelenschild, um eine Schockwelle zu entfesseln. Fügt allen Gegnern in der Nähe 69119 Arkanschaden zu und verringert Euren erlittenen Schaden 20 Sek. lang oder bis 2418789 Schaden verhindert wurde, um 50%. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242392] = {name = "[q4]Diamantit-Leerenkern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 1.596.\n[q2]Anlegen: Eure Zauber haben eine Chance, den Leerenkern zu ermächtigen, was Euch 15 Sek. lang 6256 Intelligenz verleiht. Diese Chance ist um 25% erhöht, solange Ihr weniger als 25% Mana habt. Mehrere Anwendungen können sich überlappen.\n\n[q]Scherben der Leere (0/4)\n[q0]Leerenglassspitze\nDiamantit-Leerenkern\nLeerenglaskris\nKlinge des Leerenglasherrschers\n[q0](2) Set : Während ' Diamantit-Leerenkern ' ermächtigt ist, sind Eure Leerenglassplitter 200% effektiver.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242393] = {name = "[q4]Loom'ithars lebende Seide", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 1.596.\n[q2]Benutzen: Webt für 10 Sek. einen arkanen Kokon um Euch selbst und vier Verbündete in der Nähe, der den erlittenen Schaden um 75% verringert, bis 3001672 Schaden abgewandt wurde.\n\n Wenn ein Kokon ausläuft, explodiert er und heilt einen Verbündeten in der Nähe um 50% seiner verbleibenden Kraft. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242394] = {name = "[q4]Vernichtender Arkanokern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4.469 Stärke\n[q2]Anlegen: Eure Angriffe haben eine hohe Chance, den Arkanokern aufzuladen. Bei 10 Ladungen wird ein Wächter eingesetzt und überzieht Euer Ziel mit einer Arkanoexplosion. Diese verursacht ( 1692596 * 1 ) Arkanschaden, der auf Gegner in der Nähe aufgeteilt wird. Stellt 2 Ladungen wieder her, wenn nur ein Gegner getroffen wird.\n\nSchaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242395] = {name = "[q4]Astrale Antenne", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4.469 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Anlegen: Die Antenne hat eine Chance, Arkanenergie aus der Umgebung aufzuspüren und zu Euch zu ziehen, was Euch 10 Sek. lang 4680 kritischen Trefferschaden verleiht. Mehrere Anwendungen können sich überlappen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242396] = {name = "[q4]Unnachgiebiges Netherprisma", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Eure Fähigkeiten, die Schaden zufügen, ziehen fokussierte Leere aus dem Prisma, um ( 207321 * 1 ) kosmischen Schaden zu verursachen, der zwischen Eurem Ziel und nahen Gegnern aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner um 30%, bis insgesamt 150%. Dieser Effekt kann alle 10 Sek. auftreten und sammelt bis zu 18 Mal die latente Macht innerhalb des Prismas. (10s Abklingzeit)\n[q2]Benutzen: Verbraucht sämtliche latente Macht, um 20 Sek. lang 2088 Stärke oder Beweglichkeit pro Stapel zu erhalten. (20 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242397] = {name = "[q4]Siegel der kosmischen Jagd", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4.469 Beweglichkeit\n[q2]Anlegen: Eure Angriffe haben eine hohe Chance, einen kosmischen Ansturm zu entfesseln, der Eurem Ziel ( 243193 * 1 ) kosmischen Schaden zufügt.\n\n Der Schaden wird für jedes Prozent fehlende Gesundheit des Gegners um 2% erhöht und 50% des verursachten Schadens wird auf Gegner in der Nähe aufgeteilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242398] = {name = "[q4]Naazindhris Mystische Peitsche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+4.469 Intelligenz\n[q2]Anlegen: Eure Schaden verursachenden Zauber haben eine hohe Chance, Euer Ziel mit arkaner Macht zu peitschen, was ( 303064 * 1 ) Arkanschaden verursacht, der auf Euer Ziel und die Gegner in Eurer Bahn aufgeteilt wird.\n\n Der Schaden wird für jeden weiteren Gegner um 30%, bis zu 150%, und basierend auf Eurer Meisterschaft noch weiter erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242399] = {name = "[q4]Schreie eines vergessenen Himmels", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.596.\n[q2]Anlegen: Eure schädlichen Zauber und Fähigkeiten haben eine Chance, Euer Ziel mit einem Abgrundkometen zu treffen, der ( 1182609 * 1 ) kosmischen Schaden verursacht und die Schwerkraft des Ziels verstärkt, was den Schaden weiterer Kometen um 5% erhöht.\n\n Gegner implodieren beim Tod und verursachen 944445 kosmischen Schaden pro Schwerkraftstapel, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242400] = {name = "[q4]Befehl des Nexuskönigs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 1.596.\n[q2]Anlegen: Wird alle 30 Sek. an einen Verbündeten in der Nähe eidgebunden.\n\n Mit der direkten Heilung des Verbündeten erfüllt Ihr Euren Eid und erlangt 12 Sek. lang 11101 Intelligenz, während Euer Verbündeter einen Schild in Höhe von 100% der übermäßigen Heilung erhält.\nVerkaufspreis:"}
MultiLanguageItemData['de'][242401] = {name = "[q4]Mal des unablässigen Zorns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.596.\n[q2]Anlegen: Wenn Ihr Schaden erleidet, werdet Ihr erzürnt, wodurch Ihr 55486 Schaden absorbiert und 126822 Schattenschaden pro Erzürnung verursacht, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\n\n Ihr könnt alle 15 Sek. erneut erzürnt gemacht werden, bis zu 15 Stapeln, beruhigt Euch nach Ende des Kampfes aber schnell.\n\nGilt nur für Tankspezialisierungen. (15s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242402] = {name = "[q4]Araz' Ritualschmiede", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.596.\n[q2]Benutzen: Speist einen Teil Eurer Essenz in die Schmiede ein. Euch wird 22009 Hauptwert gewährt, das über 30 Sek. auf Kosten von 15% Eurer maximalen Gesundheit abbaut. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242403] = {name = "[q4]Hinterhältiger Projektor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 1.596.\n[q2]Benutzen: Bringt einen eidgebundenen Trupp der Schattenwache dazu, Euer Ziel und Gegner in der Nähe zu verheeren. Verursacht 7618742 kosmischen Schaden, der auf sie aufgeteilt wird.\n\nSchaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][242404] = {name = "[q4]Alles verschlingender Nukleus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 1.596 Vielseitigkeit\n[q2]Anlegen: Wenn Ihr Schaden erleidet, besteht eine hohe Chance, dass Ihr die Essenz von Gegnern in der Nähe verschlingt, was 581844 Schattenschaden auf sie aufteilt und Euch um 150% des verursachten Schadens heilt.\n\n Tödlicher Schaden, der 2191558 nicht überschreitet, heilt Euch stattdessen um 20% Eurer Gesundheit und rekonstituiert Euch 6 Sek. lang als instabile Leere. Erreicht 50% Gesundheit, um Euch zu stabilisieren und dem Tod zu entgehen. Dieser Effekt kann einmal pro 8 Min. auftreten. Während der Nukleus sich auflädt, kann der Kern keinen Schaden verursachen.\nVerkaufspreis:"}
