MultiLanguageItemData['de'][242555] = {name = "[q6]Aschenbringer", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Vergeltungspaladin\n[q]\"So geschah es, dass Mann und Waffe zu einer Einheit zu verschmelzen schienen. Der Name Aschenbringer wurde zu einer Legende. Er wurde nicht nur der furchterregenden Klinge zugeschrieben, sondern auch dem unerbittlichen Ritter, der sie führte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242556] = {name = "[q6]Zwillingsklingen des Betrügers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigtVerwüstungsdämonenjäger\n[q]\"Statuiert Exempel an jenen, die närrisch genug sind, sich Euch zu widersetzen, dann wird der Rest ihrer Art sich Euch zu Füßen werfen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242557] = {name = "[q6]Zwillingsklingen des Betrügers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigtVerwüstungsdämonenjäger\n[q]\"Das Ende ist gekommen! Lasst die Zerstörung dieser Welt beginnen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242558] = {name = "[q6]Aluneth", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigtArkanmagier\n[q]\"Nach vielen Rückschlägen schaffte Aegwynn es endlich, das Wesen an einen verzauberten Großstab zu binden. Die Aufgabe, Aluneth einzugrenzen, war somit vollbracht, doch die Wächterin brauchte noch Jahre, bis sie die Macht wirklich nutzen konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242559] = {name = "[q6]Klingen des gefallenen Prinzen", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Frosttodesritter\n[q]\"Wenn meine Zeit gekommen ist, sollst du König sein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242560] = {name = "[q6]Klingen des gefallenen Prinzen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Frosttodesritter\n[q]\"Ich werde Euch der Gerechtigkeit des Grabes zuführen... und die wahre Bedeutung der Furcht lehren.\""}
MultiLanguageItemData['de'][242561] = {name = "[q6]G'Hanir, der Mutterbaum", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wiederherstellungsdruide\n[q]\"Am Anfang gab es eine Quelle der Heilung und des Gleichgewichts, einen Ort, an dem alles Leben ruhen und wiederbelebt werden konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242562] = {name = "[q6]Schlund der Verdammten", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Axt}\n4 - 9 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Bluttodesritter\n[q]\"Der Durst des Schlunds ist unstillbar. Wird ihm nicht mit frischen Opfern gedient, wird er nicht zögern, stattdessen von seinem Herrn zu trinken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242563] = {name = "[q6]Apokalypse", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Todesritter\n80 ( 80)\nBenötigt Unheiligtodesritter\n[q]\"Sie soll Zerstörung und Krieg säen. Hunger und Tod. Sie soll mit Macht locken und dann allem Leben ein Ende setzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242564] = {name = "[q6]Reißzähne des Verschlingers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtTäuschungsschurke\n[q]\"Der Biss des Hundes ist noch immer präsent, all die Jahre nach seinem Tod. Für ein derart primitives Werkzeug ist es erstaunlich wirksam und geschmeidig.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242565] = {name = "[q6]Reißzähne des Verschlingers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtTäuschungsschurke\n[q]\"Azhir manari kirel. Akim manari galar!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242566] = {name = "[q6]Fangklaue", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stangenwaffe}\n4 - 9 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Überlebensjäger\n[q]\"Der Adlerspeer. Speer der Wilden Götter. Fangklaue. Diese legendäre Waffe trägt viele Namen und viele Segen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242567] = {name = "[q6]Schicksalshammer", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Streitkolben}\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtVerstärkungsschamane\n[q]\"Ein Fremder wird den Hammer erheben und durch ihn wird die Gerechtigkeit walten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242568] = {name = "[q6]Felo'melorn", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigtFeuermagier\n[q]\"...keine elfischen Waffen. Nicht, wenn sie mit Magie und Hass und einer brennenden Begierde nach Rache neu geschmiedet wurden. Nein, Arthas. Felo'melorn ist stärker als je zuvor. So wie auch ich. - Kael'thas Sonnenwanderer\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242569] = {name = "[q6]Ursocs Klauen", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wächterdruide\n[q]\"Ursoc, Bruder des Ursol und Beschützer der Furbolgstämme... Träger der Kraft des Waldes selbst.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242570] = {name = "[q6]Ursocs Klauen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Faustwaffe}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wächterdruide\n[q]\"Azeroth wird Euch brauchen. Wenn Ihr nicht bereit seid, könnte die Welt fallen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242571] = {name = "[q6]Die Silberne Hand", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Streitkolben}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Heiligpaladin\n[q]\"Tyr antwortete, dass er seine silberne Hand nicht als Zeichen seiner Niederlage ansah. Für ihn war es das Symbol seiner Aufopferung für die Verteidigung von Azeroth und er wollte, dass auch der Rest der Welt dies so sah.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242573] = {name = "[q6]T'uure, Fanal der Naaru", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Heiligpriester\n[q]\"Gesegnet seien die Fackelträger, die Licht ins Dunkel bringen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242574] = {name = "[q6]Thas'dorah, Erbstück von Haus Windläufer", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Distanz} {Bogen}\n4 - 6 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Treffsicherheitsjäger\n[q]\"Als er aus dem Sonnenbrunnen zurückgeholt wurde, strahlte der Bogen Macht aus. Talanas empfand große Ehre beim Anblick dieser Gabe. Er nannte die Waffe Thas'dorah: 'Ehre des Waldes'.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242575] = {name = "[q6]Xal'atath, Klinge des Schwarzen Imperiums", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Schattenpriester\n[q]\"Xal'atath hat ihren eigenen Kopf. Ignoriert ihr unerträgliches Flüstern. Glaubt niemals ihren Lügen. Nehmt, was Ihr von ihr braucht, aber denkt immer daran, dass die dunkle Präsenz in der Klinge nicht Eure Verbündete ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242576] = {name = "[q6]Kriegsklingen der Aldrachi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigtRachsuchtdämonenjäger\n[q]\"Seine Kriegsklingen heulten lauter als das Schlachtgetöse und zerrissen jeden, der ihnen nahekam. Jeder Dämon, den Toranaar bezwang, schien ihn mit neuer Lebenskraft und Stärke zu erfüllen. Er war eine Armee in sich selbst.\""}
MultiLanguageItemData['de'][242577] = {name = "[q6]Kriegsklingen der Aldrachi", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Dämonenjäger\n80 ( 80)\nBenötigtRachsuchtdämonenjäger\n[q]\"Die Aldrachi waren ein stolzes Volk. Zu stolz, um zu dienen. Millionen von Dämonen starben, bevor die Aldrachi ausgelöscht wurden, und nur Sargeras selbst vollbrachte es, ihren König zu töten.\""}
MultiLanguageItemData['de'][242578] = {name = "[q6]Sichel von Elune", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Gleichgewichtsdruide\n[q]\"Hierin steckt eine Kraft, die frei sein will. Durch Gleichgewicht und Beherrschung kann der Wolf gebändigt werden, doch nur für gewisse Zeit.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242579] = {name = "[q6]Fänge von Ashamane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wildheitsdruide\n[q]\"Sie tobte durch die Reihen der Dämonen und verschwand dann zwischen den Bäumen. Sie verbarg sich in den Wipfeln und stürzte sich auf die Kommandanten der Legion. Sie war eine furchterregende Bestie. Sie kannte kein Halten, keine Gnade.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242580] = {name = "[q6]Fänge von Ashamane", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Druide\n80 ( 80)\nBenötigt Wildheitsdruide\n[q]\"Ashamanes Opfer wird bis heute gedacht. Wir leben durch ihre Gnade und ihre Kinder durchstreifen als treue Begleiter noch immer mit uns die Wälder.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242581] = {name = "[q6]Titanenblitz", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Distanz} {Schusswaffe}\n3 - 7 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Jäger\n80 ( 80)\nBenötigt Tierherrschaftsjäger\n\"Ein unnachahmliches Beispiel technomagischer Ingenieurskunst, erfüllt mit der Macht der Stürme.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242582] = {name = "[q6]Schwarzfrost", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigtFrostmagier\n[q]\"Schwarzfrost enthielt nur einen kleinen Teil von Alodis Macht, doch selbst das war mehr, als die meisten Magi je zu beherrschen hoffen durften.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242583] = {name = "[q6]Der Wahrheitshüter", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Schutzpaladin\n[q]\"Als der Hammer das erste Mal fiel, entsprangen Flüsse aus Magma aus dem Eis. Beim zweiten Mal heulte der Himmel auf und Blitze entflammten ihn. Beim dritten Mal drang ein Sonnenstrahl durch den Sturm und flüsterte über die Oberfläche des Wahrheitshüters.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242584] = {name = "[q6]Eidsucher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Paladin\n80 ( 80)\nBenötigt Schutzpaladin\n[q]\"Töten um des Tötens willen... Erobern um der Eroberung willen... Es liegt keine Ehre in solchen Dingen. Nur Schande und Bedauern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242585] = {name = "[q6]Zorn des Lichts", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Disziplinpriester\n[q]\"Wir wohnten an diesem Tag voller Hoffnung und Hingabe der Zeremonie bei... und verließen sie voller Kummer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242586] = {name = "[q6]Die Königsmörder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtMeuchelschurke\n[q]\"Es war kein angenehmer Tod. Doch er war schnell, lautlos und effizient. Als der Orc seinen letzten Atemzug tat, verzerrte dies die tödliche Wunde. Niemand konnte sagen, ob er einem Messer, einer Axt oder einem Speer erlegen war.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242587] = {name = "[q6]Die Königsmörder", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtMeuchelschurke\n[q]\"Unzählige Stimmen wurden zum Schweigen gebracht, unzählige Anführer gestürzt... alles auf sein launisches, finsteres Geheiß. Für diese Taten würde es keine Wiedergutmachung geben, nur Einsamkeit und Kummer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242588] = {name = "[q6]Die Schreckensklingen", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtGesetzloser Schurke\n[q]\"Sie sah sich selbst, wie sie eine riesige Piratenflotte kommandierte, eine, die die See beherrschen und ganz Azeroth unterwerfen konnte. Jeder, der es wagte, sie herauszufordern, wurde verbrannt und jede Stadt, die an ihren Schätzen festhielt, vernichtet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242589] = {name = "[q6]Zorn der Steinmutter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Streitkolben}\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtVerstärkungsschamane\n[q]\"Erschaffen durch die Macht des Schicksalshammers und des Schamanen, der diesen trägt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242591] = {name = "[q6]Sharas'dal, Szepter der Gezeiten", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Streitkolben}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtWiederherstellungsschamane\n[q]\"Sie trieben den Abgrund hinab, doch Azshara und ihre Hochgeborenen blieben ungebrochen. Sie waren von absoluter Dunkelheit umgeben, und die Königin zwang Sharas'dal, ihnen das Licht zu bringen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242592] = {name = "[q6]Schild der Meereskönigin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtWiederherstellungsschamane\n[q]\"Als der Ozean das Leben aus ihren Körpern schmetterte, regten sich uralte Kreaturen in der Dunkelheit. Ihr Flüstern floss durch die Strömung. Ihre Macht legte sich eng um die Königin und ihre Diener.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242593] = {name = "[q6]Die Faust des Ra-den", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtElementarschamane\n[q]\"Um Al'Akirs Untergang zu besiegeln, donnerte Meister Ra seine Faust in den Gipfel des Berges. Der Himmel brach auf und all das Feuer und der Zorn darin stürzte hinab auf den Windlord.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242594] = {name = "[q6]Schutz des hohen Hüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Schamane\n80 ( 80)\nBenötigtElementarschamane\n[q]\"Ra und Helya erschufen einen Schild, den Schutz des hohen Hüters, als Schlüssel für die Elementarebene. Er pulsierte mit der Energie der vier Elemente, die Ra nach Belieben rufen konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242595] = {name = "[q6]Sheilun, Stab der Nebel", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigtNebelwirkermönch\n[q]\"Ihr sucht die ruhige, unausweichliche Macht eines tiefen Flusses, der Schluchten in den stärksten Stein schneidet und Krieger mit seinen Strömungen ohne das leiseste Kräuseln hinfortträgt. Sheilun ist die Verkörperung dieses Konzepts.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242596] = {name = "[q6]Fu Zan, Gefährte des Wanderers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigtBraumeistermönch\n[q]\"Von Anfang an hat dieser Stab legendäre Wesen und unsterbliche Geister begleitet, während sie wichtige Arbeiten in ganz Azeroth ausführten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242597] = {name = "[q6]Fäuste der Himmel", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigtWindläufermönch\n[q]\"Als Irmaat seine zwei Waffen erhob und die Macht in ihnen auf die Probe stellte, entsprang daraus unkontrollierbare Wut.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242598] = {name = "[q6]Szepter des Sargeras", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigtZerstörungshexenmeister\n[q]\"Als schließlich der Moment kam, in dem Ner'zhul zum Handeln gezwungen war, tat er es ganz hemmungslos und dachte dabei nicht an Konsequenzen. Die Vernichtung von Draenor war ihm egal, er hieß sie sogar als Teil seines Vermächtnisses willkommen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242599] = {name = "[q6]Ulthalesh, Sense der Totenwinde", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 4 Schaden Geschwindigkeit 3.60\n(0.8 Schaden pro Sekunde)\n+11 Intelligenz\n+4 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigtGebrechenhexenmeister\n[q]\"Der Meister der Sichel wird entweder Sataiel besiegen oder verschlungen werden, was die Klinge nur noch stärker machen wird. Danach wird ein anderer kommen, um seinen Platz einzunehmen. Und danach wieder ein anderer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242600] = {name = "[q6]Schädel der Man'ari", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigtDämonologiehexenmeister\n[q]\"Als Thal'kiel endlich erschien, war er verändert. Um Jahrhunderte gealtert, allein in der Dunkelheit mit seinen Gedanken und Sklaven. Er war buckelig und hatte ein merkwürdiges Glänzen in den Augen. Er beschwor seine Erwecker und wir antworteten ihm...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242601] = {name = "[q6]Fäuste der Himmel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Faustwaffe}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Mönch\n80 ( 80)\nBenötigtWindläufermönch\n[q]\"Es gab einen großen Lichtblitz und einen Windstoß, und dann war es schon getan - Irmaat konnte seine Waffen spüren. Al'burq und Alra'ed bebten mit der Macht der Elemente.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242602] = {name = "[q6]Geheimnisse der Leere", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Priester\n80 ( 80)\nBenötigt Schattenpriester\n[q]\"Als ich die Klinge berührte, erklang ein Name in meinem Verstand: Xal'atath. Ich wusste, dass ich den Dolch nicht vernichten konnte. Noch nicht. Wie kann man eine Macht bezwingen, die man nicht versteht?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242603] = {name = "[q6]Herz des Phönix", additional_info = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Magier\n80 ( 80)\nBenötigtFeuermagier\n[q]\"Als das Kämpfen ein Ende gefunden hatte, war Dath'Remar mit Dämonenblut bedeckt. Mit Einbruch der Nacht wurde uns klar, dass noch mehr Schlachten bevorstünden. Und dennoch, dieser Elf mit seiner Klinge gab uns Hoffnung, dass der Sieg in Reichweite lag.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242604] = {name = "[q6]Die Schreckensklingen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nKlassen: Schurke\n80 ( 80)\nBenötigtGesetzloser Schurke\n[q]\"Keine Klinge kann so viel unschuldiges Blut vergießen, ohne auch einen Zoll von ihrem Träger einzufordern. Dies ist kein Schatz.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242605] = {name = "[q6]Rückgrat von Thal'kiel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+7 Intelligenz\n+2 Ausdauer\nKlassen: Hexenmeister\n80 ( 80)\nBenötigtDämonologiehexenmeister\n[q]\"Die Schreie des Erweckers hallten über Argus. Sie stellen eine düstere Erinnerung an den Preis dar, den er dafür zahlen musste, sich mit Dämonen eingelassen zu haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][242617] = {name = "[q6]Seltsames Simulakrum", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Untersucht das Simulaktrum und enthüllt seine wahre Natur.\n80 ( 80)\n[q]\"Dies scheint just die Artefaktwaffe zu sein, die Ihr bereits in Händen haltet. Was ist das für ein Zauberwerk?\""}
MultiLanguageItemData['de'][242622] = {name = "[q4]Kriegsmeutengebundenes Reinigungspaket", additional_info = "Veteran\nWird beim Aufheben gebunden\n[q2]Benutzen: Schaltet künftige Veteranengegenstände in neuerlebten verstörenden Visionen frei, die bis zum Ausrüsten kriegsmeutengebunden sind.\nSchließt den Erfolg \"Maskierter Monolog\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während eine beliebige Gesichtslosenmaske aktiv ist."}
MultiLanguageItemData['de'][242623] = {name = "[q4]Verzaubertes kriegsmeutengebundenes Reinigungspaket", additional_info = "Champion\nWird beim Aufheben gebunden\n[q2]Benutzen: Schaltet künftige Championgegenstände in neuerlebten verstörenden Visionen frei, die bis zum Ausrüsten kriegsmeutengebunden sind.\nSchließt den Erfolg \"Symphonie der Masken\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während mindestens 5 Gesichtslosenmasken aktiv sind."}
