MultiLanguageItemData['de'][246067] = {name = "[q4]Perlkrolusk", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Perlkrolusk beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Kroluske wurden als invasive Spezies nach K'aresh gebracht und fanden dort Nutzen beim Transport von Lasten.\"\nBeute:\nUrmag\nZone:\nK'aresh"}
MultiLanguageItemData['de'][246071] = {name = "[q4]Arkannadel des Manaschneiders", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n5,414 - 7,325 Schaden Geschwindigkeit 3.60\n(1,769 Schaden pro Sekunde)\n+20.901 Intelligenz\n+32.645 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.467.\n[q2]+ 768 Vielseitigkeit\nHaltbarkeit 120 / 120\n[q2]Anlegen: Eure Zauber haben eine Chance, Euch einen Stapel 'Ätherplatte', bis zu einem Maximum von 5 Stapeln.\n\n Wenn Ihr das nächste Mal direkten, zielgerichteten Schaden erleidet, wird eine 'Ätherplatte' verbraucht und dieser Schaden um 50% verringert, bis zu einem Maximum von 160756 .\nVerkaufspreis:"}
MultiLanguageItemData['de'][246072] = {name = "[q3]Aufwendige Immerkalte Perle", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Instabile Magie '.\n\n Instabile Magie\nEure kritischen Treffer haben eine Chance, einen Magieschub auszulösen und Gegnern innerhalb von 6 Metern um Euer Ziel [(342% Angriffs-/Zaubermacht)] Arkanschaden zuzufügen.\n\n ' Narans Immerscheibe ' erzielt jetzt immer einen kritischen Treffer bei mit ' Teufelsberührt ' belegten Gegnern.\n80 ( 80)"}
MultiLanguageItemData['de'][246073] = {name = "[q3]Aufwendiger Zorn der Gezeiten", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Berührung der Bosheit '.\n\n Berührung der Bosheit\nEure Schaden verursachenden Zauber und Fähigkeiten sowie die Eurer Diener belegen Gegner regelmäßig mit ' Teufelsberührt '. Der durch ' Verdrehter Kreuzzug ' beschworene höllische Schreckenslord trifft mit ' Teufelsberührt ' belegte Gegner immer kritisch.\n\n\nTeufelsberührt\n Alle 4 Sek. explodiert das Ziel und fügt Gegnern in der Nähe 3 % des in den letzten 4 Sek. erlittenen Schadens zu.\n\n Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246074] = {name = "[q3]Aufwendiger Gesplitterter Komet", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Schrecken aus der Tiefe '.\n\n Schrecken aus der Tiefe\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\n Wenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246075] = {name = "[q3]Aufwendiger Gelmoggs geborstener Schädel", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Seelenstärke des Hochbergs '.\n\n Seelenstärke des Hochbergs\nAlle 12 Sek. sammelt Ihr 3% von sämtlichem erlittenen Schaden als ' Seelenstärke ' an. Nach 8 Sek. wird ' Seelenstärke ' zu einer Schutzbarriere, die 4 Sek. lang Schaden in der angesammelten Höhe absorbiert.\n80 ( 80)"}
MultiLanguageItemData['de'][246076] = {name = "[q3]Aufwendiges Ettinknochenfragment", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Seelen des Krächzens '.\n\n Seelen des Krächzens\nEure Zauber und Fähigkeiten haben eine Chance, einen Schwarm Geisteradler zu beschwören, die auf Gegner in der Nähe herabstürzen und bei Aufprall explodieren. Explosionen heilen Verbündete und fügen Gegnern innerhalb von 5 Metern [[2 * (368% Angriffs-/Zaubermacht)]][[(368% Angriffs-/Zaubermacht)]] Naturschaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246077] = {name = "[q3]Aufwendiger Schimmernder Eisendorn", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' Arkane Aegis '.\n\n Arkane Aegis\nIhr kanalisiert bei Rückwärtsbewegung ' Arkane Aegis ', absorbiert bis zu [(2100% Angriffs-/Zaubermacht)] Schaden und verringert Eure Bewegungsgeschwindigkeit um 80%. Wenn Ihr ' Arkane Aegis ' nicht kanalisiert, regeneriert sie sich um 5% pro Sekunde. Wird die ' Arkane Aegis ' zerschlagen, ist sie 30 Sek. lang unbenutzbar.\n80 ( 80)"}
MultiLanguageItemData['de'][246078] = {name = "[q3]Aufwendige Xakals Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\n{[q2]Anlegen: Gewährt 2 zusätzliche Ränge von ' {Temporalgegenschlag '.\n\n {Temporalgegenschlag\nWenn Ihr Schaden absorbiert, fügt Ihr dem Angreifer [(31% Angriffs-/Zaubermacht)] Arkanschaden} zu und verringert sein Angriffstempo 3 Sek. lang um 20%.}\n80 ( 80)"}
