MultiLanguageItemData['de'][246080] = {name = "[q4]Makelloser Zorn der Gezeiten", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' Berührung der Bosheit '.\n\n Berührung der Bosheit\nEure Schaden verursachenden Zauber und Fähigkeiten sowie die Eurer Diener belegen Gegner regelmäßig mit ' Teufelsberührt '. Der durch ' Verdrehter Kreuzzug ' beschworene höllische Schreckenslord trifft mit ' Teufelsberührt ' belegte Gegner immer kritisch.\n\n\nTeufelsberührt\n Alle 4 Sek. explodiert das Ziel und fügt Gegnern in der Nähe 3 % des in den letzten 4 Sek. erlittenen Schadens zu.\n\n Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246081] = {name = "[q4]Makelloser Gesplitterter Komet", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' Schrecken aus der Tiefe '.\n\n Schrecken aus der Tiefe\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\n Wenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246082] = {name = "[q4]Makelloser Gelmoggs geborstener Schädel", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' Seelenstärke des Hochbergs '.\n\n Seelenstärke des Hochbergs\nAlle 12 Sek. sammelt Ihr 5% von sämtlichem erlittenen Schaden als ' Seelenstärke ' an. Nach 8 Sek. wird ' Seelenstärke ' zu einer Schutzbarriere, die 4 Sek. lang Schaden in der angesammelten Höhe absorbiert.\n80 ( 80)"}
MultiLanguageItemData['de'][246083] = {name = "[q4]Makelloses Ettinknochenfragment", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' Seelen des Krächzens '.\n\n Seelen des Krächzens\nEure Zauber und Fähigkeiten haben eine Chance, einen Schwarm Geisteradler zu beschwören, die auf Gegner in der Nähe herabstürzen und bei Aufprall explodieren. Explosionen heilen Verbündete und fügen Gegnern innerhalb von 5 Metern [[2 * (368% Angriffs-/Zaubermacht)]][[(368% Angriffs-/Zaubermacht)]] Naturschaden zu.\n80 ( 80)"}
MultiLanguageItemData['de'][246084] = {name = "[q4]Makelloser Schimmernder Eisendorn", additional_info = "Wird beim Aufheben gebunden\n[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' Arkane Aegis '.\n\n Arkane Aegis\nIhr kanalisiert bei Rückwärtsbewegung ' Arkane Aegis ', absorbiert bis zu [(2100% Angriffs-/Zaubermacht)] Schaden und verringert Eure Bewegungsgeschwindigkeit um 80%. Wenn Ihr ' Arkane Aegis ' nicht kanalisiert, regeneriert sie sich um 5% pro Sekunde. Wird die ' Arkane Aegis ' zerschlagen, ist sie 30 Sek. lang unbenutzbar.\n80 ( 80)"}
MultiLanguageItemData['de'][246085] = {name = "[q4]Makellose Xakals Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\n{[q2]Anlegen: Gewährt 3 zusätzliche Ränge von ' {Temporalgegenschlag '.\n\n {Temporalgegenschlag\nWenn Ihr Schaden absorbiert, fügt Ihr dem Angreifer [(31% Angriffs-/Zaubermacht)] Arkanschaden} zu und verringert sein Angriffstempo 3 Sek. lang um 20%.}\n80 ( 80)"}
MultiLanguageItemData['de'][246086] = {name = "[q4]Schicksalsweber", additional_info = "The War Within – Saison 3\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nIn Schildhand geführt\n+394 Intelligenz\n+208 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 125.\n[q2]+ 114 Vielseitigkeit\n[q2]Benutzen: Führt ein Weberitual durch, spinnt die Netze des Schicksals und formt sie zu einer schicksalsgewobenen Waffe.\n1 Aufladung\n[q]\"Am Griff sind kaum leserliche Worte eingraviert: \"Die Ritualstätte befindet sich in Azj-Kahet und überblickt die Salinengossen, weit im Norden von Rak-Zakaz.\"\"\nVerkaufspreis:"}
