MultiLanguageItemData['de'][246917] = {name = "[q4]Donnergratelekk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Selbst durch die Infusion mit dämonischer Magie konnte der Wille dieser majestätischen Tiere nicht gebrochen werden, und ihre verderbten Formen wurden nie in den Dienst der Legion eingebunden.\"\nHandelsposten"}
MultiLanguageItemData['de'][246919] = {name = "[q4]Glutversengter Elekk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Brennende Legion war darauf aus, alles zu zerstören, zu stehlen oder zu verderben, was den Draenei Freude bereitete. Und die Elekks von Draenor bildeten da keine Ausnahme.\"\nHandelsposten"}
MultiLanguageItemData['de'][246920] = {name = "[q4]Leerengeschliffener Elekk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Ihr Temperament ist so wild wie die verdrehten Kräfte, die ihre Schöpfung verzerrten. Sie dienen nur, wen sie dazu auserkoren haben.\"\nHandelsposten"}
MultiLanguageItemData['de'][246921] = {name = "[q4]Legionsgeschmiedeter Elekk", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Brennende Legion beneidete die Draenei um ihre Bande zu den Elekks von Draenor. Viele dämonische Bestienmeister verderbten die Spezies für ihre eigenen Bedürfnisse, doch kontrollieren konnte sie keiner.\"\nHandelsposten"}
MultiLanguageItemData['de'][246936] = {name = "[q4]Resonantes Epochenandenken", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fusioniert dieses Epochenandenken mit Eurer Artefaktwaffe, um eine Welle durch alle Zeitlinien und Versionen von \"Euch\" zu erzeugen.\n\n Dieses mächtige Relikt steht in Resonanz mit Eurer Kriegsmeute und erhöht sämtliche erhaltene Erfahrung in Legion Remix dauerhaft um 1%.\n80 ( 80)\n[q]\"Ein kleiner Teil einer epochalen Geschichte.\""}
MultiLanguageItemData['de'][246937] = {name = "[q5]Perfektioniertes Epochenandenken", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Fusioniert dieses Epochenandenken mit Eurer Artefaktwaffe, um eine Welle durch alle Zeitlinien und Versionen von \"Euch\" zu erzeugen.\n\n Dieses perfekte Relikt steht in Resonanz mit Eurer Kriegsmeute und erhöht sämtliche erhaltene Erfahrung in Legion Remix dauerhaft um 10%.\n80 ( 80)\n[q]\"Ein wichtiger Teil einer epochalen Geschichte.\""}
MultiLanguageItemData['de'][246939] = {name = "[q2]Augenglas des Essenzjägers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Intelligenz]\n[q2]Anlegen: Eure kritischen Treffer mit schädlichen Zaubern und Distanzfähigkeiten haben eine hohe Chance, Euch bis zu 5-mal 'Arkanjäger' zu gewähren, was Euren kritischen Trefferwert 8 Sek. lang um 302 pro Stapel erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][246940] = {name = "[q2]Manageschmiedete Ätherzelle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 Intelligenz\n[q2]Anlegen: Eure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 5250 , pro Sekunde um ( 5250 / 15) verringert. Hält 15 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][246941] = {name = "[q2]Symbiotische Äthergaze", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15.398 Ausdauer\n[q2]Anlegen: Blocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 232200 Arkanschaden zufügt und Euch einen Schild gewährt, der 1345046 Schaden absorbiert und 15 Sek. lang anhält.\nVerkaufspreis:"}
MultiLanguageItemData['de'][246944] = {name = "[q2]Verstandvernichtendes Odium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke]\n[q2]Anlegen: Eure schädlichen Fähigkeiten können Risse in Eurem Verstand verursachen. Nach dem zehnten Riss erliegt Ihr dem arkanen Wahnsinn, was Euer Tempo um 2473 erhöht, während Ihr Euren Verstand allmählich mit der Zeit wiederherstellt.\n\n Wenn Ihr einen Gegner tötet oder den Tod eines Verbündeten bezeugt, wird sofort ein Riss verursacht.\n[q]\"Warum sind hier immer so viele Tentakel?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][246945] = {name = "[q2]Körperloser Essenzverschlinger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\n[q2]Benutzen: Reißt magische Essenz aus Eurem Ziel und verschlingt sie, was dem Ziel ( 181008 * 1 ) Arkanschaden zufügt und Euch für 20 Sek. 5426 Eures niedrigsten Sekundärwerts gewährt.\n\n Falls das Ziel ein Astraler war, wird stattdessen Euer höchster Sekundärwert erhöht. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][246947] = {name = "[q2]Verzerrter Managrimmling", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 1.256 Vielseitigkeit\n[q2]Anlegen: Eure Heilzauber und -fähigkeiten haben eine sehr hohe Chance, einen verzerrten Managrimmling zu beschwören, der Euch 10 Sek. lang im Kampf unterstützt. Der verzerrte Managrimmling heilt regelmäßig einen zufälligen Verbündeten in der Nähe um ( 83617 * 1 ). Überschüssige Heilung wird in einen Absorptionsschild umgewandelt, der 5 Sek. lang anhält.\nVerkaufspreis:"}
