MultiLanguageItemData['de'][247720] = {name = "[q4]Schauriges Streitross des kopflosen Reiters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Fliegt durch die Lüfte, fahrt auf Eure Gegner herab, mit diesem Ross seid Ihr immer auf Zack.\"\nHandelsposten"}
MultiLanguageItemData['de'][247721] = {name = "[q4]Makabres Streitross des kopflosen Reiters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mit süßem Sieg über einen garstigen Reiter, ein ghulisches Ross für einen schaurigen Streiter.\"\nHandelsposten"}
MultiLanguageItemData['de'][247722] = {name = "[q4]Brennendes Streitross des kopflosen Reiters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"In Herz und Seele des Rosses ein Feuer erhellt, steigt in den Himmel und zeigt es der Welt.\"\nHandelsposten"}
MultiLanguageItemData['de'][247723] = {name = "[q4]Geheiligtes Streitross des kopflosen Reiters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mit ungewisser Zukunft dank vergangener Taten, wie lang könnt Ihr das mit Eurem Ross noch ertragen?\"\nHandelsposten"}
MultiLanguageItemData['de'][247791] = {name = "[q4]Geschmückter Greif von Nordaeron", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Greifenreiterältesten und Hochschamanen der Wildhämmer von Nordaeron haben ihre Greifen oft mit kunstvollen, federbedeckten Teilen geziert, die ihren Rang und Status zur Schau stellten.\"\nHandelsposten"}
MultiLanguageItemData['de'][247792] = {name = "[q4]Fluggreif des Hochschamanen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die antiken Schamanen der Wildhämmer, die den Greifen als erstes begegneten, glaubten, dass es sich bei ihnen um elementare Geister in sterblicher Form handelte. Diese Begegnung prägte den Wildhammerclan für alle kommenden Generationen.\"\nHandelsposten"}
MultiLanguageItemData['de'][247793] = {name = "[q4]Glutgefiederter Hochlandgreif", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Laut einer Legende der Wildhämmer soll das orangefarbene Gefieder der Greifen ein vererbtes Merkmal ihrer elementaren Vorfahren sein.\"\nHandelsposten"}
MultiLanguageItemData['de'][247794] = {name = "[q4]Himmelsführer der Glutschwinge", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Von den Gebirgsausläufern Khaz Modans sind wir seinen flammenden Schwingen gefolgt... eine Fackel die am dunklen Sommerhimmel gen Norden flog.\" - Die Pilgerfahrt des Ersten Wildweisen\nHandelsposten"}
MultiLanguageItemData['de'][247795] = {name = "[q4]Störrischer Brisenschreiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Störrischen Brisenschreiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Dieses Talbuk ist ein stures, eigensinniges Reittier, selbst wenn es mit seinem Reiter vertraut ist. Mit Vorsicht zu genießen.\"\nHandelsposten"}
MultiLanguageItemData['de'][247808] = {name = "[q6]Bronzenes Simulakrum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n[q]\"Eine makellose Artefaktkopie, geschmiedet von Momentus. Jetzt, da Ihr diese Kopie in Händen haltet, könnt Ihr sie verschrottet, um die Bronze zu nutzen.\""}
