MultiLanguageItemData['de'][247991] = {name = "[q3]Ensemble: Geheiligte Sammlung des Reiters", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Sammelt die Vorlagen dieses Rüstungssets.\n[q]\"Wenn das Dunkel weicht und die Schatten fallen, strahlt Sir Thompson hell, in den heiligen Hallen.\""}
MultiLanguageItemData['de'][248017] = {name = "[q3]Kreischender Quarz", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Stellt den kreischen Quarz auf und lockt die Nemesis an seine Position.\n\n Kann nur verwendet werden, nachdem der Stein der Wiederherstellung in einer Tiefe aktiviert wurde. (1 Stunde Abklingzeit)\n[q]\"Wurde nach dem unterschwelligen Geräusch benannt, den der Stein von sich gibt, wenn er im Freien rausgeholt wird. Seine Frequenzen unterbrechen den Manafluss, was für jene, die stärker auf Mana eingestimmt sind, überaus unangenehm ist.\""}
MultiLanguageItemData['de'][248088] = {name = "[q4]Jade, der strahlende Hellseher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Anwesenheit dieses erhabenen Pandaren-Hasengeists bringt Freude und Glück und gilt als wundervolles Omen. Der Legende nach könnt Ihr in den Augen dieser Geister das größte Glück Eures Lebens erblicken, selbst wenn es noch in der Zukunft liegt.\"\nWoW-Shop"}
MultiLanguageItemData['de'][248089] = {name = "[q4]Umschlungener Traumweber", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die letzten Schläfer erwachen endlich und bringen die Träume der Drachen zurück in die Welt.\"\nPromotion:\nDragonflight: Heroic Edition"}
MultiLanguageItemData['de'][248090] = {name = "[q4]Viridianphasenjäger", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Kreatur stammt von einer Spezies ab, die sich bereits zuvor äußerst geschickt auf natürliche Art und Weise tarnen konnte. Die außerweltlichen Energien, die Draenor in die Scherbenwelt verwandelten, gaben diesen Kreaturen die Fähigkeit, sich durch den Raum zu teleportieren.\"\nPromotion"}
MultiLanguageItemData['de'][248091] = {name = "[q3]Animawyrmling", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Beschwört diesen Gefährten oder gibt ihn wieder frei.\n80 ( 80)"}
MultiLanguageItemData['de'][248092] = {name = "[q3]Zwinki", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][248093] = {name = "[q4]Ensemble: Schattenbannornat des Schreckenslords", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen des Schattenbannornats des Schreckenslords.\n[q]\"Bei so einem Komfort ist es ganz einfach, grün zu leben.\""}
MultiLanguageItemData['de'][248094] = {name = "[q4]Ensemble: Ornat des wellengeborenen Diplomaten", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Sammelt die Vorlagen des Rüstungssets Ornat des wellengeborenen Diplomaten.\n[q]\"Bei so einem Komfort ist es ganz einfach, grün zu leben.\""}
MultiLanguageItemData['de'][248126] = {name = "[q4]Anfängerset des Tiefenforschers", additional_info = "Wird beim Aufheben gebunden\nQuest: Saisonale Erinnerung\n[q]\"Enthält einen restaurierten Kastenschlüssel und einige verbrauchbare Gegenstände.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][248127] = {name = "[q4]Tiefenforschertasche der kosmetischen Überraschung", additional_info = "Wird beim Aufheben gebunden\nQuest: Saisonale Erinnerung\n[q]\"Enthält einen zufälligen kosmetischen Gegenstand der Tiefe für Eure Kriegsmeute.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][248129] = {name = "Branns wiedererlangte Ausrüstung", additional_info = "Questgegenstand\n[q]\"Jede Menge Kleidung, glücklicherweise, aber keinerlei Kuriosität.\""}
MultiLanguageItemData['de'][248140] = {name = "[q6]Bronzenes Simulakrum", additional_info = "Wird beim Aufheben gebunden\n80 ( 80)\n[q]\"Eine makellose Artefaktkopie, geschmiedet von Momentus. Jetzt, da Ihr diese Kopie in Händen haltet, könnt Ihr sie verschrottet, um die Bronze zu nutzen.\""}
MultiLanguageItemData['de'][248141] = {name = "[q6]Seltsames Simulakrum", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Untersucht das Simulaktrum und enthüllt seine wahre Natur.\n80 ( 80)\n[q]\"Dies scheint just die Artefaktwaffe zu sein, die Ihr bereits in Händen haltet. Was ist das für ein Zauberwerk?\""}
MultiLanguageItemData['de'][248142] = {name = "[q4]Beute des Tiefenforschers", additional_info = "The War Within – Saison 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Entschlüsselt zu einem beliebigen Zeitpunkt die Karte. So wird garantiert, dass Ihr am Ende der nächsten Tiefe der Stufe 4 oder höher, die Ihr abschließt, einen versteckten Schatz findet.\n\n Der Inhalt des versteckten Schatzes hängt von der Stufe der abgeschlossenen Tiefe ab.\n[q]\"Bestimmt wartet dort ein großer Schatz.\""}
