MultiLanguageItemData['de'][250721] = {name = "[q4]Zügel des Verschneiten Hochbergadlers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Herumliegende Federn eines verschneiten Adlers auf dem Hochberg gelten als Vorzeichen für wechselnde Winde und Temperaturstürze.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250722] = {name = "[q3]Astraler Stand", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Lasst einen astralen Marktstand vom Himmel herabfallen, der 15 Min. lang dableibt. Kann nur im Freien verwendet werden. (15 Min Abklingzeit)"}
MultiLanguageItemData['de'][250723] = {name = "[q4]Zügel des Baumspitzenhochbergadlers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der majestätische Adler ist ein Symbol für den Stolz der Hochbergstämme. Die Fähigkeit dieser gewaltigen Tiere, Tauren auf ihrem Rücken zu tragen, zeugt von der schieren Größe und Stärke der Kreaturen des Hochbergs.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250724] = {name = "[q3]Schlüsselsteinaffix hinzufügen: Tyrannisch verstärkt", additional_info = "Dauer: 12 std. (Realzeit)\n[q2]Benutzen: Fügt einem mythischen Schlüsselstein das Affix Tyrannisch verstärkt hinzu.\nVerkaufspreis:"}
MultiLanguageItemData['de'][250726] = {name = "[q4]Zügel des Leyfrostmanasäblers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten"}
MultiLanguageItemData['de'][250727] = {name = "[q4]Zügel des Nachtbrunnenmanasäblers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten"}
MultiLanguageItemData['de'][250728] = {name = "[q4]Zügel des Arkbeerenmanasäblers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Ihr Name rührt von ihrer optischen Ähnlichkeit mit den leuchtenden Beeren her, aus denen Arkwein hergestellt wird. Diese stolzen Katzen haben einen scharfen Sinn für die Leylinien, auf denen sie wandeln.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250741] = {name = "[q4]Verwirrender Jeton des Kartells", additional_info = "The War Within – Saison 3\nWird beim Aufheben gebunden\nEinzigartig (200)\n[q]\"Nur neun pro Kunde. Mit Bedacht ausgeben!\""}
MultiLanguageItemData['de'][250745] = {name = "[q4]Zügel des Teufelsvernarbten Manarochens", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen teufelsvernarbten Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\n[q]\"Die ledrige Haut dieses Manarochens trägt die Narben der Teufelsverderbnis und ist Zeugnis des harten Überlebenskampfes auf Argus. Er neigt noch mehr als üblich zu Aggressionsausbrüchen.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250746] = {name = "[q4]Zügel des Blutreißermanarochens", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen Blutreißermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\n[q]\"Die Zerschmetterung von Argus machte diese Art von Manarochen blutrünstig. Nun ernähren sie sich vom verderbten Blut aller Kreaturen, die sie zwischen ihre zahlreichen Zähne bekommen können.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250747] = {name = "[q4]Zügel des Albinomanarochens", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen Albinomanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\n[q]\"Die Zerschmetterung von Argus ließ die Manarochen mutieren, um sich ihrer neuen Umgebung anzupassen. Manche von ihnen gaben die Pigmentierung ihrer Haut auf, um im Gegenzug ihre Sinne zu schärfen.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250748] = {name = "[q4]Zügel des Leuchtenden Manarochens", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen leuchtenden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Manarochen können ein helles Leuchten ausstrahlen, um Beute anzulocken.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250751] = {name = "[q4]Zügel des Zwielichtrenners", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Um Fressfeinden zu entgehen, dämpft dieser Renner das Leuchten seines Horns, wenn er sich versteckt. Provoziert man ihn, stößt er hingegen blendende Lichtblitze aus.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250752] = {name = "[q4]Zügel des Goldenen Sonnenrenners", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Freigeist liebt lange Spaziergänge am Strand und tollt gerne auf bunten Blumenwiesen herum.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250756] = {name = "[q4]Zügel des Türkisrenners", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Benannt nach seinen einzigartig gefärbten Augen, die einem direkt in die Seele zu starren scheinen, zeigt der Türkisrenner mehr Intelligenz als seine Traumläufer-Artgenossen und ist bekannt dafür, den Charakter einer Person hervorragend einschätzen zu können.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250757] = {name = "[q4]Zügel des Düsternisalptraums", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese Kreatur wurde vom Smaragdgrünen Alptraum berührt. Wenn sie einem im Traum erscheint, gilt das als Zeichen des Unglücks, und wer sie im wachen Zustand zu Gesicht bekommt, dem droht eine Katastrophe.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250758] = {name = "[q4]Zügel des Knochenrosses des Vergessens", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote von Mangel und Tod.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][250759] = {name = "[q4]Zügel des Knochenrosses der Seuche", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\n[q]\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote von Krankheit und Leid.\"\nWeltereignis:\nWoW Remix: Legion"}
