MultiLanguageItemData['de'][252954] = {name = "[q4]Teufelsgeweihte Zügel des Giftbrutbezwingers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Todesritter können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Giftbrutbezwinger oder gibt ihn wieder frei. Dieses Reittier steht nur Todesrittern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese fliegende Vereinigung der Mächte des Todes und der Hölle zerfetzt die Lüfte mit ihrem schaurigen Kreischen.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253013] = {name = "[q4]Schlächterzügel des teufelsgeweihten Kreischers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Dämonenjäger können dieses Reittier benutzen.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Nur die fähigsten Dämonenjäger können ihn aus dem Himmel reißen.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253024] = {name = "[q4]Verachtungsflügelgötze des Teufelsdruiden", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt die Fluggestalt 'Verachtungsflügel'. Dieses Reittier steht nur Druiden zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n[q]\"Lehrt Euch, wie man dieses Reittier beschwört. Nur Druiden können dieses Reittier benutzen.\""}
MultiLanguageItemData['de'][253025] = {name = "[q4]Zügel des teufelsgeweihten Wolfsfalken", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Jäger können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Wolfsfalken oder gibt ihn wieder frei. Dieses Reittier steht nur Jägern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Gezeichnet durch den Krieg auf den Verheerten Inseln, verdient dieser Wolfsfalke ein gutes Zuhause.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253026] = {name = "[q4]Teufelsgeweihte Scheibe des Erzmagiers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Magier können dieses Reittier benutzen.\n[q2]Beschwört Eure teufelsgeweihte Scheibe des Erzmagiers oder gibt sie wieder frei. Dieses Reittier steht nur Magiern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Einige Magier sagen, dämonische Magie sei \"instabil\" oder \"korrumpierend\" oder \"verboten\". Einige Magier liegen falsch.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253027] = {name = "[q4]Teufelsgeweihte Glocke des Großmeisters", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Mönche können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Begleiter des Großmeisters oder gibt ihn wieder frei. Dieses Reittier steht nur Mönchen zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das verzerrte Antlitz eines geliebten Begleiters.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253028] = {name = "[q4]Zügel des teufelsgeweihten Streitrosses des Hochlords", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Paladine können dieses Reittier benutzen.\n[q2]Beschwört Euer teufelsgeweihtes Streitross des Hochlords oder gibt es wieder frei. Dieses Reittier steht nur Paladinen zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses Pferd wurde auf ewig durch die verderbte Magie der Legion gezeichnet.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253029] = {name = "[q4]Teufelsgeweihte Pfeife des Suchers", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Priester können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Sucher des Hohepriesters oder gibt ihn wieder frei. Dieses Reittier steht nur Priestern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser dämonisch verderbte gefiederte Freund schlägt in einem frenetischen Tempo mit den Flügeln, um sich weit vom Getümmel am Boden abzuheben.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253030] = {name = "[q4]Zügel des teufelsgeweihten Omens der Schattenklinge", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Schurken können dieses Reittier benutzen.\n[q2]Beschwört Euer teufelsgeweihtes Omen der Schattenklinge oder gibt es wieder frei. Dieses Reittier steht nur Schurken zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Eure Feinde werden vor ihrem Ableben Angst spüren.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253031] = {name = "[q4]Teufelsgeweihtes Totem des Sturmgewitters", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Schamanen können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Sturm des Scharfsehers oder gibt ihn wieder frei. Dieses Reittier steht nur Schamanen zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dämonisch inspirierter Zorn.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253032] = {name = "[q4]Teufelsgeweihte Zügel des Schreckensrosses des Netherlords", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Hexenmeister können dieses Reittier benutzen.\n[q2]Beschwört Euer teufelsgeweihtes Schreckensross des Netherfürsten oder gibt es wieder frei. Dieses Reittier steht nur Hexenmeistern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Er strotzt nur so vor Potenzial.\"\nWeltereignis:\nWoW Remix: Legion"}
MultiLanguageItemData['de'][253033] = {name = "[q4]Eiserne Zügel des teufelsgeweihten Kriegswyrms", additional_info = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Krieger können dieses Reittier benutzen.\n[q2]Beschwört Euren teufelsgeweihten Kriegswyrm oder gibt ihn wieder frei. Dieses Reittier steht nur Kriegern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Der Himmer erschaudert in Erwartung Eurer Ankunft.\"\nWeltereignis:\nWoW Remix: Legion"}
