MultiLanguageItemData['de'][253222] = {name = "[q3]Verderbter Dorn des Traums", additional_info = "Legion Remix: Himmel in Flammen\nWird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 10 davon, um einen Gegenstand aus dem Smaragdgrünen Alptraum herzustellen.\n80 ( 80)\n[q]\"Im Smaragdgrünen Alptraum kann sich selbst ein Dorn zu etwas Mächtigem und Tödlichem entwickeln.\""}
MultiLanguageItemData['de'][253223] = {name = "[q3]Fraktalteufelssplitter", additional_info = "Legion Remix: Legionsrichter\nWird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 10 davon, um einen Gegenstand aus dem Grabmal des Sargeras herzustellen.\n80 ( 80)\n[q]\"Die Macht des Betrügers ist so groß, dass selbst ein Tropfen seines Blutes, der erkaltet und zu einem Splitter kristallisiert, nahezu unendliches Potenzial enthält.\""}
MultiLanguageItemData['de'][253224] = {name = "[q3]Partikel der zerbrochenen Zeit", additional_info = "Legion Remix\nWird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 10 davon, um einen Gegenstand herzustellen, der zu einem verfügbaren Schlachtzug in Legion Remix gehört.\n80 ( 80)\n[q]\"Ein Prismasplitter, der mit dieser fragmentierten Zeitlinie in Resonanz steht. Zugleich nimmt er Gestalt an als verderbter Dorn, als Hexenmeisteredelstein, als teufelsleuchtender Splitter oder als Echo des Todes.\""}
MultiLanguageItemData['de'][253227] = {name = "[q3]Makelloser Zeitfaden", additional_info = "Legion Remix: Echos der Ewigen\nWird beim Aufheben gebunden\n[q2]Benutzen: Kombiniert 10 davon, um einen Gegenstand von unfassbarem Potenzial zu erschaffen.\n80 ( 80)\n[q]\"In einer nun kollabierenden alternativen Zeitlinie, in der der ewige Drachenschwarm mit der Geschichte der dritten Legionsinvasion experimentiert, werden unverderbte Momente zunehmend seltener und bergen eine phänomenale Macht.\""}
