MultiLanguageItemData['de'][258427] = {name = "[q4]Bezähmter Blizzard", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Flockengestöber als fordernder Freund, frostklirrend für verfrorene Freude.\"\nPromotion:"}
MultiLanguageItemData['de'][258428] = {name = "[q4]Schneesturm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Er kam aus Schnee und Eis in die Sonne von Azeroth, die brennt so heiß.\"\n30. Geburtstag von Blizzard"}
MultiLanguageItemData['de'][258429] = {name = "[q3]Mondberührter Netherwelpe", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Netherwelpen beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][258430] = {name = "[q4]Wanderndes Urtum", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Urtume sind standhafte Verteidiger der Wälder Azeroths, sie sind aber auch für ihre eindrucksvollen Kronen aus Blättern bekannt, die im Wechsel der Jahreszeiten ihre Farbe ändern.\"\nPromotion"}
MultiLanguageItemData['de'][258431] = {name = "[q4]Sarges Geschichte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Moment mal, Sarge ist doch gar nicht so groß. Da muss jemand im Hearthstone-Gasthaus eine ziemliche Räuberpistole erzählt haben...\"\nPromotion"}
MultiLanguageItemData['de'][258432] = {name = "[q3]Drakks", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Drakks beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][258475] = {name = "[q4]Küstengleiter der Tuskarr", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Tuskarr haben schon vor langer Zeit gelernt, dass die Knochen der von ihnen gejagten Meerestiere leicht sind, viel Auftrieb bieten und daher hervorragend als Material für Gleiter geeignet sind.\"\nPromotion"}
MultiLanguageItemData['de'][258476] = {name = "[q4]Frostbrutprotowyrm", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieselbe Magie des Untodes, die die Frostbrut zu Dienern des Lichkönigs werden ließ, hat diesen urtümlichen Wyrm erfüllt. Seine Loyalität und Kraft stehen jetzt im Dienste derer, die Azeroth verteidigen.\"\nPromotion:\nWrath of the Lich King Classic"}
MultiLanguageItemData['de'][258477] = {name = "[q4]Telix das Sturmhorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Telix war einst ein einfacher Käfer auf der Verbotenen Insel und wurde dann von Sturmmagie erfüllt, als Raszageth befreit wurde. Mit seinen neuen geschärften Sinnen streift Telix nun auf den Dracheninseln an der Seite der Drachenschuppenexpedition umher... und Eurer!\"\nPromotion"}
MultiLanguageItemData['de'][258479] = {name = "[q4]Algarischer Sturmreiter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren algarischen Sturmreiter oder gibt ihn wieder frei.\n\n Bei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Diese blitzerfüllte Krähe fliegt sogar bei den schwierigsten Wetterbedingungen und wurde dafür ausgebildet, durch die Himmel der Insel von Dorn und die Tiefen darunter zu segeln.\"\nPromotion:\nThe War Within Heroic Edition"}
